insert into _new (name, file, body_part, en, es) values
  ('Curl Concentrado en Polea', 'cable-concentration-curl.gif', 'upper arms', '["Sit on a bench or chair with your feet flat on the floor and your knees slightly bent.", "Hold the cable handle with an underhand grip and rest your elbow against the inside of your thigh.", "Keeping your upper arm stationary, exhale and curl the cable handle towards your shoulder while contracting your biceps.", "Pause for a moment at the top of the movement, then inhale and slowly lower the cable handle back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Siéntate en un banco o silla con los pies planos en el suelo y las rodillas ligeramente flexionadas.", "Sujeta la agarradera del cable con agarre supino y apoya el codo en la parte interna del muslo.", "Manteniendo el brazo superior quieto, exhala y flexiona la agarradera del cable hacia el hombro contrayendo el bíceps.", "Haz una pausa breve en la parte más alta del movimiento, luego inhala y baja lentamente la agarradera del cable de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Curl Concentrado Sentado a 1 Brazo en Polea', 'cable-seated-one-arm-concentration-curl.gif', 'upper arms', '["Sit on a bench with your feet flat on the floor and your back straight.", "Hold a cable handle with one hand and place your elbow on the inside of your thigh, just above the knee.", "Keep your upper arm stationary and curl the cable handle towards your shoulder while exhaling.", "Pause for a moment at the top of the movement, squeezing your biceps.", "Slowly lower the cable handle back to the starting position while inhaling.", "Repeat for the desired number of repetitions, then switch arms."]', '["Siéntate en un banco con los pies apoyados planos en el suelo y la espalda recta.", "Sujeta una agarradera del cable con una mano y coloca el codo en la parte interna del muslo, justo arriba de la rodilla.", "Mantén la parte superior del brazo inmóvil y curva la agarradera del cable hacia el hombro mientras exhalas.", "Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.", "Baja lentamente la agarradera del cable de vuelta a la posición inicial mientras inhalas.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Curl Concentrado Sentado con Agarre Prono', 'dumbbell-seated-revers-grip-concentration-curl.gif', 'upper arms', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand, palm facing up.", "Rest your elbow on the inside of your thigh, just above the knee.", "Keeping your upper arm stationary, exhale and curl the dumbbell towards your shoulder.", "Pause for a moment at the top, squeezing your biceps.", "Inhale and slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en una mano, con la palma hacia arriba.", "Apoya el codo en la parte interna del muslo, justo por encima de la rodilla.", "Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro.", "Haz una pausa breve en la parte alta, apretando los bíceps.", "Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Curl Concentrado Sentado con Barra y Agarre Cerrado', 'barbell-seated-close-grip-concentration-curl.gif', 'upper arms', '["Sit on a bench with your feet flat on the floor and hold a barbell with an underhand grip, hands shoulder-width apart.", "Rest your upper arms against your inner thighs, just above your knees, and let the barbell hang down in front of you.", "Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders, contracting your biceps.", "Hold the contracted position for a brief pause, then inhale and slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con los pies planos sobre el suelo y sujeta una barra con un agarre supino, manos separadas a la altura de los hombros.", "Apoya los brazos superiores contra el interior de los muslos, justo por encima de las rodillas, y deja que la barra cuelgue frente a ti.", "Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros, contrayendo los bíceps.", "Mantén la posición contraída durante una breve pausa, luego inhala y baja lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl Concentrado Sentado con Barra Z y Agarre Cerrado', 'ez-bar-seated-close-grip-concentration-curl.gif', 'upper arms', '["Sit on a bench with your feet flat on the ground and hold an EZ barbell with an underhand grip.", "Rest your elbow on the inside of your thigh, just above the knee.", "Curl the barbell up towards your shoulder while keeping your upper arm stationary.", "Squeeze your biceps at the top of the movement, then slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con los pies apoyados en el suelo y sostén una barra EZ con agarre supino.", "Apoya el codo en la parte interna del muslo, justo por encima de la rodilla.", "Sube la barra curvando el brazo hacia el hombro mientras mantienes el brazo superior inmóvil.", "Contrae los bíceps en la parte superior del movimiento, luego baja lentamente la barra a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl Concentrado sobre Fitball', 'dumbbell-one-arm-concentration-curl-on-stability-ball.gif', 'upper arms', '["Sit on a stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.", "Hold a dumbbell in one hand with your palm facing up and your arm extended down towards the floor.", "Rest your elbow on the inside of your thigh, just above the knee.", "Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder while contracting your biceps.", "Pause for a moment at the top of the movement, then inhale and slowly lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch arms and repeat."]', '["Siéntate sobre un balón de estabilidad con los pies apoyados planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.", "Sostén una mancuerna en una mano con la palma hacia arriba y el brazo extendido hacia el suelo.", "Apoya el codo en la parte interna del muslo, justo por encima de la rodilla.", "Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro contrayendo el bíceps.", "Haz una pausa por un momento en la parte superior del movimiento, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo y repite."]'),
  ('Curl de Arrastre con Barra (Drag Curl)', 'barbell-drag-curl.gif', 'upper arms', '["Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.", "Let the barbell hang at arm''s length in front of your thighs.", "Keeping your upper arms stationary, curl the barbell up towards your chest by contracting your biceps.", "Pause for a moment at the top, then slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre supino, con las palmas hacia arriba.", "Deja que la barra cuelgue a la longitud del brazo frente a los muslos.", "Manteniendo los brazos superiores fijos, levanta la barra hacia el pecho contrayendo los bíceps.", "Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Arrastre en Polea (Drag Curl)', 'cable-drag-curl.gif', 'upper arms', '["Stand facing a cable machine with your feet shoulder-width apart.", "Grasp the cable attachment with an underhand grip, palms facing up, and arms fully extended.", "Keeping your upper arms stationary, exhale and curl the cable attachment towards your shoulders by contracting your biceps.", "Pause for a moment at the top of the movement, squeezing your biceps.", "Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.", "Sujeta el accesorio del cable con agarre supino, palmas hacia arriba, y los brazos completamente extendidos.", "Manteniendo los brazos superiores quietos, exhala y flexiona el accesorio del cable hacia los hombros contrayendo los bíceps.", "Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.", "Inhala y baja lentamente el accesorio del cable de vuelta a la posición inicial, extendiendo completamente los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps a 1 Brazo de Pie', 'dumbbell-one-arm-standing-curl.gif', 'upper arms', '["Stand up straight with a dumbbell in one hand, palm facing forward and arm fully extended.", "Keeping your upper arm stationary, exhale and curl the weight upward while contracting your biceps.", "Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Ponte de pie con una mancuerna en una mano, con la palma hacia adelante y el brazo completamente extendido.", "Manteniendo el brazo superior quieto, exhala y flexiona el peso hacia arriba contrayendo el bíceps.", "Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Curl de Bíceps a 1 Brazo en Polea', 'cable-one-arm-curl.gif', 'upper arms', '["Stand facing the cable machine with your feet shoulder-width apart.", "Grasp the cable handle with an underhand grip, palm facing up.", "Keep your elbow close to your side and slowly curl your forearm up towards your shoulder.", "Pause for a moment at the top, then slowly lower your forearm back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.", "Sujeta la agarradera del cable con un agarre supino, con la palma hacia arriba.", "Mantén el codo cerca del costado y curva lentamente el antebrazo hacia el hombro.", "Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps a 1 Brazo Sentado sobre Fitball', 'dumbbell-one-arm-seated-bicep-curl-on-exercise-ball.gif', 'upper arms', '["Sit on an exercise ball with your feet flat on the ground and your back straight.", "Hold a dumbbell in one hand with your palm facing up and your arm fully extended.", "Keeping your upper arm stationary, curl the dumbbell towards your shoulder by contracting your biceps.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.", "Sostén una mancuerna en una mano con la palma hacia arriba y el brazo completamente extendido.", "Manteniendo el brazo superior quieto, flexiona la mancuerna hacia el hombro contrayendo el bíceps.", "Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Curl de Bíceps a 1 Brazo Sentado sobre Fitball con Pierna Elevada', 'dumbbell-seated-one-arm-bicep-curl-on-exercise-ball-with-leg-raised.gif', 'upper arms', '["Sit on an exercise ball with your feet flat on the ground and your back straight.", "Hold a dumbbell in one hand with your palm facing up and your arm fully extended.", "Place your other hand on your hip for stability.", "Slowly curl the dumbbell towards your shoulder, keeping your upper arm stationary.", "Pause for a moment at the top of the movement, squeezing your bicep.", "Slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions.", "Switch arms and repeat the exercise."]', '["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.", "Sostén una mancuerna en una mano con la palma hacia arriba y el brazo completamente extendido.", "Coloca la otra mano en la cadera para mantener el equilibrio.", "Flexiona lentamente la mancuerna hacia tu hombro, manteniendo fija la parte superior del brazo.", "Haz una pausa por un momento en la parte más alta del movimiento, apretando el bíceps.", "Baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado.", "Cambia de brazo y repite el ejercicio."]'),
  ('Curl de Bíceps a 1 Pierna (Postura de Cigüeña)', 'dumbbell-bicep-curl-with-stork-stance.gif', 'upper arms', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.", "Extend one leg behind you, balancing on the toes of that foot.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions, then switch legs and repeat."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante.", "Extiende una pierna hacia atrás, equilibrándote sobre los dedos de ese pie.", "Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.", "Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado y luego cambia de pierna y repite."]'),
  ('Curl de Bíceps a Press de Hombros Sentado', 'dumbbell-seated-biceps-curl-to-shoulder-press.gif', 'upper arms', '["Sit on a bench with your back straight and feet flat on the ground.", "Hold a dumbbell in each hand with your palms facing forward and arms fully extended.", "Keeping your elbows close to your sides, curl the dumbbells up towards your shoulders.", "Once your forearms are vertical, rotate your wrists so that your palms are facing forward.", "Press the dumbbells overhead until your arms are fully extended.", "Lower the dumbbells back down to the starting position by reversing the movement.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.", "Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos.", "Manteniendo los codos cerca de tus costados, flexiona las mancuernas hacia los hombros.", "Una vez que tus antebrazos estén verticales, gira las muñecas de modo que las palmas queden hacia adelante.", "Presiona las mancuernas por encima de la cabeza hasta que los brazos estén completamente extendidos.", "Baja las mancuernas de vuelta a la posición inicial invirtiendo el movimiento.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps Alterno con Banda Elástica', 'band-alternating-biceps-curl.gif', 'upper arms', '["Stand with your feet shoulder-width apart and hold the band with an underhand grip, palms facing up.", "Keep your elbows close to your sides and slowly curl one arm up towards your shoulder, squeezing your biceps at the top.", "Lower the arm back down to the starting position and repeat with the other arm.", "Continue alternating arms for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sostén la banda con un agarre supino, con las palmas hacia arriba.", "Mantén los codos cerca de los costados y flexiona lentamente un brazo hacia el hombro, apretando el bíceps en la parte superior.", "Baja el brazo de vuelta a la posición inicial y repite con el otro brazo.", "Continúa alternando los brazos durante el número de repeticiones deseado."]'),
  ('Curl de Bíceps Alterno con Barra', 'barbell-alternate-biceps-curl.gif', 'upper arms', '["Stand up straight with your feet shoulder-width apart and hold a barbell in each hand, palms facing forward.", "Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps.", "Continue to raise the barbells until your biceps are fully contracted and the barbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale as you slowly begin to lower the barbells back to the starting position.", "Repeat for the desired number of repetitions, alternating arms."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra en cada mano, con las palmas mirando hacia delante.", "Mantén los brazos superiores fijos y exhala mientras levantas el peso contrayendo los bíceps.", "Continúa levantando las barras hasta que los bíceps estén completamente contraídos y las barras estén a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala mientras comienzas a bajar lentamente las barras de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, alternando los brazos."]'),
  ('Curl de Bíceps Alterno con Mancuernas', 'dumbbell-alternate-biceps-curl.gif', 'upper arms', '["Stand up straight with a dumbbell in each hand, palms facing forward and arms fully extended.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions, alternating arms."]', '["Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante y los brazos completamente extendidos.", "Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.", "Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, alternando los brazos."]'),
  ('Curl de Bíceps Alterno con Mancuernas y Arm Blaster', 'dumbbell-alternate-biceps-curl-with-arm-blaster.gif', 'upper arms', '["Stand up straight with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.", "Place the arm blaster on your upper arms, ensuring a secure fit.", "Keeping your upper arms stationary, exhale and curl one dumbbell up towards your shoulder while contracting your biceps.", "Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly lower the dumbbell back to the starting position.", "Repeat the movement with the opposite arm.", "Continue alternating arms for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante.", "Coloca el soporte para brazos en la parte superior de tus brazos, asegurándote de que quede bien ajustado.", "Manteniendo los brazos superiores quietos, exhala y flexiona una mancuerna hacia el hombro mientras contraes el bíceps.", "Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el movimiento con el brazo contrario.", "Continúa alternando los brazos durante el número de repeticiones deseado."]'),
  ('Curl de Bíceps Alterno Sentado sobre Fitball', 'dumbbell-alternating-seated-bicep-curl-on-exercise-ball.gif', 'upper arms', '["Sit on an exercise ball with your feet flat on the ground and your back straight.", "Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.", "Keeping your upper arms stationary, exhale and curl one dumbbell while rotating your forearm until your palm is facing your shoulder.", "Inhale and slowly lower the dumbbell back to the starting position.", "Repeat the curl with the other arm.", "Continue alternating curls for the desired number of repetitions."]', '["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.", "Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos.", "Manteniendo los brazos superiores quietos, exhala y flexiona una mancuerna mientras rotas el antebrazo hasta que la palma quede frente al hombro.", "Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite la flexión con el otro brazo.", "Continúa alternando flexiones el número de repeticiones deseado."]'),
  ('Curl de Bíceps Alterno sobre Fitball con Pierna Elevada', 'dumbbell-alternating-bicep-curl-with-leg-raised-on-exercise-ball.gif', 'upper arms', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.", "Place an exercise ball behind you and position one foot on top of it, keeping your balance.", "With your arms fully extended and elbows close to your sides, curl one dumbbell towards your shoulder while keeping your upper arm stationary.", "Lower the dumbbell back down to the starting position and repeat with the other arm.", "Continue alternating arms for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante.", "Coloca un balón de ejercicio detrás de ti y apoya un pie sobre él, manteniendo el equilibrio.", "Con los brazos completamente extendidos y los codos cerca de los costados, flexiona una mancuerna hacia el hombro mientras mantienes el brazo superior quieto.", "Baja la mancuerna de vuelta a la posición inicial y repite con el otro brazo.", "Continúa alternando los brazos durante el número de repeticiones deseado."]'),
  ('Curl de Bíceps Camarero (Waiter Curl)', 'dumbbell-waiter-biceps-curl.gif', 'upper arms', '["Stand up straight with a dumbbell in each hand, palms facing forward.", "Keep your upper arms close to your body and your elbows tucked in.", "Slowly curl the dumbbells up towards your shoulders, keeping your wrists straight.", "Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante.", "Mantén la parte superior de los brazos cerca del cuerpo y los codos pegados.", "Flexiona lentamente las mancuernas hacia los hombros, manteniendo las muñecas rectas.", "Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps con Barra y Agarre Abierto', 'barbell-standing-wide-grip-biceps-curl.gif', 'upper arms', '["Stand with your feet shoulder-width apart and hold a barbell with an underhand grip, hands wider than shoulder-width apart.", "Keep your back straight and your elbows close to your torso.", "Exhale and curl the barbell up towards your shoulders, keeping your upper arms stationary.", "Pause for a moment at the top, squeezing your biceps.", "Inhale and slowly lower the barbell back to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre supino, manos más separadas que el ancho de los hombros.", "Mantén la espalda recta y los codos cerca del torso.", "Exhala y flexiona la barra hacia los hombros, manteniendo los brazos superiores quietos.", "Haz una pausa breve en la parte alta, apretando los bíceps.", "Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps con Barra y Arm Blaster', 'barbell-biceps-curl-with-arm-blaster.gif', 'upper arms', '["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, palms facing up.", "Place your upper arms against the arm blaster, keeping your elbows close to your torso.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con un agarre supino, con las palmas hacia arriba.", "Coloca los brazos superiores contra el soporte para brazos, manteniendo los codos cerca del torso.", "Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.", "Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps con Barra Z y Agarre Abierto', 'ez-barbell-standing-wide-grip-biceps-curl.gif', 'upper arms', '["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, hands wider than shoulder-width apart.", "Keep your elbows close to your torso and your upper arms stationary throughout the movement.", "Curl the barbell up towards your shoulders by contracting your biceps.", "Pause for a moment at the top, then slowly lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, manos más separadas que la altura de los hombros.", "Mantén los codos cerca del torso y los brazos superiores quietos durante todo el movimiento.", "Sube la barra hacia los hombros contrayendo los bíceps.", "Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps con Barra Z y Agarre Cerrado', 'ez-barbell-close-grip-curl.gif', 'upper arms', '["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, hands shoulder-width apart.", "Keep your elbows close to your torso and your upper arms stationary throughout the movement.", "Curl the barbell up towards your shoulders, contracting your biceps.", "Pause for a moment at the top, then slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, manos separadas a la altura de los hombros.", "Mantén los codos cerca del torso y los brazos superiores quietos durante todo el movimiento.", "Sube la barra hacia los hombros, contrayendo los bíceps.", "Haz una pausa breve en la parte alta y luego baja lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps con Barra Z y Arm Blaster', 'ez-bar-biceps-curl-with-arm-blaster.gif', 'upper arms', '["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip, palms facing up.", "Place your upper arms against the arm blaster, keeping them stationary throughout the exercise.", "Keeping your elbows close to your body, exhale and curl the barbell up towards your shoulders.", "Pause for a moment at the top, squeezing your biceps.", "Inhale and slowly lower the barbell back to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino, palmas hacia arriba.", "Coloca los brazos superiores contra el soporte de aislamiento de brazos, manteniéndolos inmóviles durante todo el ejercicio.", "Manteniendo los codos cerca del cuerpo, exhala y sube la barra hacia los hombros.", "Haz una pausa breve en la parte alta, apretando los bíceps.", "Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps con Mancuernas y Arm Blaster', 'dumbbell-biceps-curl-with-arm-blaster.gif', 'upper arms', '["Stand up straight with a dumbbell in each hand, palms facing forward.", "Keep your elbows close to your torso and your upper arms stationary.", "Exhale and curl the weights while contracting your biceps.", "Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante.", "Mantén los codos cerca del torso y los brazos superiores quietos.", "Exhala y flexiona las pesas mientras contraes los bíceps.", "Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps con Zancada y Movimiento de Bolos', 'dumbbell-bicep-curl-lunge-with-bowling-motion.gif', 'upper arms', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.", "Take a step forward with your right foot, bending your right knee and lowering your body into a lunge position.", "As you lunge forward, curl the dumbbells up towards your shoulders, keeping your elbows close to your body.", "At the bottom of the lunge, rotate your torso to the right, as if you were bowling a ball.", "Reverse the motion, stepping back with your right foot and returning to the starting position while lowering the dumbbells back down.", "Repeat the lunge and curl motion, this time rotating your torso to the left.", "Continue alternating sides for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con las palmas hacia adelante.", "Da un paso adelante con el pie derecho, flexionando la rodilla derecha y bajando el cuerpo a una posición de zancada.", "Mientras avanzas en la zancada, flexiona las mancuernas hacia los hombros, manteniendo los codos cerca del cuerpo.", "En la parte baja de la zancada, gira el torso hacia la derecha, como si estuvieras lanzando una bola de boliche.", "Invierte el movimiento, retrocediendo con el pie derecho y regresando a la posición inicial mientras bajas las mancuernas de nuevo.", "Repite el movimiento de zancada y flexión, esta vez girando el torso hacia la izquierda.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Curl de Bíceps de Pie con Barra y Agarre Cerrado', 'barbell-standing-close-grip-curl.gif', 'upper arms', '["Stand up straight with your feet shoulder-width apart and hold a barbell with an underhand grip, hands close together.", "Keep your elbows close to your torso and your upper arms stationary throughout the movement.", "Exhale as you curl the weights while contracting your biceps. Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale as you slowly begin to bring the barbell back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre supino, manos juntas.", "Mantén los codos cerca del torso y los brazos superiores quietos durante todo el movimiento.", "Exhala al flexionar el peso contrayendo los bíceps. Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala mientras comienzas a llevar lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps de Pie con Disco', 'weighted-standing-curl.gif', 'upper arms', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.", "Keep your elbows close to your torso and exhale as you curl the weights up to shoulder level.", "Pause for a moment at the top, then inhale as you slowly lower the weights back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante.", "Mantén los codos cerca del torso y exhala mientras curvas los pesos hasta la altura de los hombros.", "Haz una pausa de un momento en la parte superior, luego inhala mientras bajas lentamente los pesos de nuevo a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps de Rodillas sobre Fitball', 'dumbbell-kneeling-bicep-curl-exercise-ball.gif', 'upper arms', '["Kneel on the floor with an exercise ball in front of you.", "Place your elbows on top of the exercise ball, holding a dumbbell in each hand with your palms facing up.", "Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.", "Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Arrodíllate en el suelo con un balón de estabilidad frente a ti.", "Coloca los codos sobre el balón de estabilidad, sosteniendo una mancuerna en cada mano con las palmas hacia arriba.", "Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas contrayendo los bíceps.", "Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps en Cuclillas en Polea', 'cable-squatting-curl.gif', 'upper arms', '["Attach a cable handle to the lowest setting on a cable machine.", "Stand facing the machine with your feet shoulder-width apart.", "Hold the cable handle with an underhand grip, palms facing up, and arms fully extended.", "Lower your body into a squat position, keeping your back straight and knees behind your toes.", "As you squat down, curl the cable handle towards your shoulders, keeping your elbows close to your sides.", "Pause for a moment at the top of the curl, squeezing your biceps.", "Slowly lower the cable handle back to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Coloca un mango de cable en el ajuste más bajo de una máquina de cable.", "Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.", "Sujeta el mango del cable con un agarre supino, con las palmas hacia arriba y los brazos completamente extendidos.", "Baja el cuerpo hacia una posición de sentadilla, manteniendo la espalda recta y las rodillas detrás de las puntas de los pies.", "Mientras te agachas, flexiona el mango del cable hacia los hombros, manteniendo los codos cerca de los costados.", "Haz una pausa breve en la parte alta del movimiento, apretando los bíceps.", "Baja lentamente el mango del cable de vuelta a la posición inicial, extendiendo completamente los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps en Máquina Smith', 'smith-machine-bicep-curl.gif', 'upper arms', '["Adjust the height of the smith machine bar to be at waist level.", "Stand facing the smith machine with your feet shoulder-width apart.", "Grasp the bar with an underhand grip, hands slightly wider than shoulder-width apart.", "Keep your elbows close to your sides and your upper arms stationary.", "Exhale and curl the bar up towards your shoulders, contracting your biceps.", "Pause for a moment at the top of the movement, squeezing your biceps.", "Inhale and slowly lower the bar back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura de la barra de la máquina Smith a la altura de la cintura.", "Ponte de pie frente a la máquina Smith con los pies separados a la altura de los hombros.", "Sujeta la barra con un agarre supino, con las manos un poco más separadas que el ancho de los hombros.", "Mantén los codos cerca de los costados y los brazos superiores quietos.", "Exhala y flexiona la barra hacia los hombros, contrayendo los bíceps.", "Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.", "Inhala y baja lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps en Polea con Agarre Cerrado', 'cable-close-grip-curl.gif', 'upper arms', '["Attach a straight bar to a low pulley cable machine.", "Stand facing the machine with your feet shoulder-width apart and your knees slightly bent.", "Grasp the bar with an underhand grip, hands shoulder-width apart.", "Keep your elbows close to your sides and your upper arms stationary throughout the exercise.", "Exhale and curl the bar up towards your shoulders, contracting your biceps.", "Pause for a moment at the top of the movement, squeezing your biceps.", "Inhale and slowly lower the bar back to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Coloca una barra recta en una máquina de cable con polea baja.", "Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.", "Sujeta la barra con agarre supino, manos separadas a la altura de los hombros.", "Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio.", "Exhala y flexiona la barra hacia los hombros, contrayendo los bíceps.", "Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.", "Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps en Polea de Jalón', 'cable-pulldown-bicep-curl.gif', 'upper arms', '["Attach a straight bar to the cable machine at the highest setting.", "Stand facing the machine with your feet shoulder-width apart.", "Grasp the bar with an underhand grip, hands shoulder-width apart.", "Keep your elbows close to your sides and your upper arms stationary.", "Exhale and slowly curl the bar down towards your thighs, keeping your wrists straight.", "Pause for a moment at the bottom of the movement, squeezing your biceps.", "Inhale and slowly return the bar to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Sujeta una barra recta a la máquina de cable en el ajuste más alto.", "Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.", "Sujeta la barra con agarre supino, manos separadas a la altura de los hombros.", "Mantén los codos cerca de los costados y los brazos superiores quietos.", "Exhala y curva lentamente la barra hacia los muslos, manteniendo las muñecas rectas.", "Haz una pausa por un momento en la parte baja del movimiento, apretando los bíceps.", "Inhala y regresa lentamente la barra a la posición inicial, extendiendo los brazos por completo.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps en Polea en Banco Inclinado', 'cable-two-arm-curl-on-incline-bench.gif', 'upper arms', '["Sit on an incline bench with your back against the pad and your feet flat on the ground.", "Grasp the cable handles with an underhand grip, palms facing up, and your arms fully extended.", "Keeping your upper arms stationary, exhale and curl the handles towards your shoulders while contracting your biceps.", "Pause for a moment at the top of the movement, squeezing your biceps.", "Inhale and slowly lower the handles back to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco inclinado con la espalda apoyada en el respaldo y los pies planos en el suelo.", "Agarra los mangos del cable con un agarre supino, con las palmas hacia arriba y los brazos completamente extendidos.", "Manteniendo los brazos superiores quietos, exhala y flexiona los mangos hacia los hombros mientras contraes los bíceps.", "Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.", "Inhala y baja lentamente los mangos de vuelta a la posición inicial, extendiendo completamente los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps en V sobre Bosu', 'dumbbell-biceps-curl-v-sit-on-bosu-ball.gif', 'upper arms', '["Sit on a bosu ball with your feet flat on the ground and your knees bent at a 90-degree angle.", "Hold a dumbbell in each hand with your palms facing forward and your arms fully extended down by your sides.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un bosu con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.", "Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos hacia abajo a los lados.", "Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.", "Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps Interno de Pie', 'dumbbell-standing-inner-biceps-curl-v-2.gif', 'upper arms', '["Stand up straight with a dumbbell in each hand, palms facing your torso.", "Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.", "While holding your upper arms stationary, curl the weights while contracting your biceps.", "Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Slowly begin to bring the dumbbells back to the starting position as your breathe in.", "Repeat for the recommended amount of repetitions."]', '["Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso.", "Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante.", "Manteniendo fija la parte superior de los brazos, flexiona los pesos mientras contraes los bíceps.", "Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Comienza a llevar lentamente las mancuernas de vuelta a la posición inicial mientras inhalas.", "Repite el número de repeticiones recomendado."]'),
  ('Curl de Bíceps Interno de Pie en Polea', 'cable-standing-inner-curl.gif', 'upper arms', '["Stand facing a cable machine with your feet shoulder-width apart.", "Grasp the cable handle with an underhand grip, palms facing up.", "Keep your elbows close to your sides and your upper arms stationary.", "Exhale and curl the cable handle towards your shoulders, contracting your biceps.", "Pause for a moment at the top of the movement, squeezing your biceps.", "Inhale and slowly lower the cable handle back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.", "Agarra el mango del cable con un agarre supino, con las palmas hacia arriba.", "Mantén los codos cerca de los costados y los brazos superiores quietos.", "Exhala y flexiona el mango del cable hacia los hombros, contrayendo los bíceps.", "Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.", "Inhala y baja lentamente el mango del cable de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps Interno en Banco Inclinado', 'dumbbell-incline-inner-biceps-curl.gif', 'upper arms', '["Sit on an incline bench with a dumbbell in each hand, palms facing each other.", "Rest your upper arms on the bench, allowing your elbows to hang down and your palms to face forward.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas enfrentadas entre sí.", "Apoya los brazos superiores en el banco, permitiendo que los codos cuelguen hacia abajo y las palmas miren hacia adelante.", "Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.", "Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps Interno Sentado', 'dumbbell-seated-inner-biceps-curl.gif', 'upper arms', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.", "Rest your upper arms on your thighs, allowing the dumbbells to hang down.", "Keeping your upper arms stationary, curl the dumbbells up towards your shoulders by contracting your biceps.", "Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en cada mano, con las palmas hacia arriba.", "Apoya la parte superior de los brazos sobre los muslos, dejando que las mancuernas cuelguen hacia abajo.", "Manteniendo la parte superior de los brazos fija, flexiona las mancuernas hacia los hombros contrayendo los bíceps.", "Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps por Encima de la Cabeza a 1 Brazo con Banda Elástica', 'band-one-arm-overhead-biceps-curl.gif', 'upper arms', '["Stand with your feet shoulder-width apart and place one end of the band under your foot.", "Hold the other end of the band with your arm fully extended overhead, palm facing forward.", "Keeping your upper arm stationary, curl your forearm towards your shoulder, squeezing your biceps.", "Pause for a moment at the top, then slowly lower your forearm back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Ponte de pie con los pies separados a la altura de los hombros y coloca un extremo de la banda bajo el pie.", "Sostén el otro extremo de la banda con el brazo completamente extendido por encima de la cabeza, con la palma hacia adelante.", "Manteniendo quieta la parte superior del brazo, flexiona el antebrazo hacia el hombro, apretando el bíceps.", "Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Curl de Bíceps por Encima de la Cabeza en Polea Doble', 'cable-overhead-curl.gif', 'upper arms', '["Attach a straight bar to a high pulley cable machine.", "Stand facing the machine with your feet shoulder-width apart.", "Grasp the bar with an underhand grip, hands shoulder-width apart.", "Keep your elbows close to your sides and your upper arms stationary.", "Exhale and curl the bar down towards your forehead, keeping your upper arms stationary.", "Pause for a moment at the bottom of the movement, squeezing your biceps.", "Inhale and slowly return the bar to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Sujeta una barra recta a una máquina de cable con polea alta.", "Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.", "Sujeta la barra con agarre supino, manos separadas a la altura de los hombros.", "Mantén los codos cerca de los costados y los brazos superiores quietos.", "Exhala y curva la barra hacia la frente, manteniendo la parte superior de los brazos inmóvil.", "Haz una pausa por un momento en la parte baja del movimiento, apretando los bíceps.", "Inhala y regresa lentamente la barra a la posición inicial, extendiendo los brazos por completo.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps por Encima de la Cabeza Sentado en Polea', 'cable-seated-overhead-curl.gif', 'upper arms', '["Sit on a bench facing the cable machine with your feet flat on the ground.", "Grasp the cable attachment with an underhand grip, palms facing up, and your hands shoulder-width apart.", "Keep your upper arms stationary and your elbows close to your sides.", "Exhale and curl the cable attachment towards your shoulders, contracting your biceps.", "Pause for a moment at the top of the movement, squeezing your biceps.", "Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco frente a la máquina de cable con los pies apoyados planos en el suelo.", "Sujeta el accesorio del cable con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros.", "Mantén la parte superior de los brazos inmóvil y los codos cerca de los costados.", "Exhala y flexiona el accesorio del cable hacia los hombros, contrayendo los bíceps.", "Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.", "Inhala y baja lentamente el accesorio del cable de vuelta a la posición inicial, extendiendo completamente los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps Sentado con Banda Elástica', 'resistance-band-seated-biceps-curl.gif', 'upper arms', '["Sit on a chair or bench with your back straight and feet flat on the ground.", "Hold the resistance band with an underhand grip, palms facing up, and arms extended down by your sides.", "Keeping your upper arms stationary, exhale and curl the resistance band up towards your shoulders.", "Pause for a moment at the top, squeezing your biceps.", "Inhale and slowly lower the resistance band back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en una silla o banco con la espalda recta y los pies apoyados en el suelo.", "Sostén la banda elástica con un agarre supino, con las palmas hacia arriba y los brazos extendidos a los lados del cuerpo.", "Manteniendo la parte superior de los brazos inmóvil, exhala y flexiona la banda elástica hacia los hombros.", "Haz una pausa breve en la parte alta, apretando los bíceps.", "Inhala y baja lentamente la banda elástica de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps Sentado con Barra Z', 'ez-barbell-seated-curls.gif', 'upper arms', '["Sit on a bench with your feet flat on the ground and your back straight.", "Hold the ez barbell with an underhand grip, palms facing up, and your hands shoulder-width apart.", "Rest your upper arms on your thighs, allowing the ez barbell to hang down in front of you.", "Keeping your upper arms stationary, exhale and curl the ez barbell upwards towards your shoulders.", "Pause for a moment at the top, squeezing your biceps.", "Inhale and slowly lower the ez barbell back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con los pies apoyados planos en el suelo y la espalda recta.", "Sostén la barra EZ con agarre supino, palmas hacia arriba, y las manos separadas a la altura de los hombros.", "Apoya los brazos superiores en los muslos, dejando que la barra EZ cuelgue frente a ti.", "Manteniendo los brazos superiores inmóviles, exhala y sube la barra EZ hacia los hombros.", "Haz una pausa breve en la parte alta, apretando los bíceps.", "Inhala y baja lentamente la barra EZ a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps Sentado con Mancuernas', 'dumbbell-seated-bicep-curl.gif', 'upper arms', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.", "Keep your back straight and your elbows close to your torso.", "Exhale and curl the dumbbells up towards your shoulders, contracting your biceps.", "Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en cada mano, con las palmas hacia arriba.", "Mantén la espalda recta y los codos cerca del torso.", "Exhala y flexiona las mancuernas hacia los hombros, contrayendo los bíceps.", "Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps Sentado en Polea', 'cable-seated-curl.gif', 'upper arms', '["Sit on a cable machine with your feet flat on the ground and your back straight.", "Grasp the cable attachment with an underhand grip, palms facing up, and your arms fully extended.", "Keeping your upper arms stationary, exhale and curl the cable attachment towards your shoulders, contracting your biceps.", "Pause for a moment at the top of the movement, squeezing your biceps.", "Inhale and slowly lower the cable attachment back to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Siéntate en una máquina de cable con los pies apoyados planos en el suelo y la espalda recta.", "Sujeta el accesorio del cable con un agarre supino, con las palmas hacia arriba y los brazos completamente extendidos.", "Manteniendo la parte superior de los brazos inmóvil, exhala y curva el accesorio del cable hacia los hombros, contrayendo los bíceps.", "Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.", "Inhala y baja lentamente el accesorio del cable de vuelta a la posición inicial, extendiendo completamente los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps Sentado sobre Fitball', 'dumbbell-seated-biceps-curl-on-stability-ball.gif', 'upper arms', '["Sit on a stability ball with your feet flat on the ground and your back straight.", "Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.", "Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.", "Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta.", "Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos.", "Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas contrayendo los bíceps.", "Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps Sentado sobre Fitball con Balón Medicinal', 'weighted-seated-bicep-curl-on-stability-ball.gif', 'upper arms', '["Sit on a stability ball with your feet flat on the ground and your back straight.", "Hold a medicine ball with an underhand grip, palms facing up, and let your arms hang down by your sides.", "Keeping your upper arms stationary, exhale and curl the medicine ball up towards your shoulders.", "Pause for a moment at the top, squeezing your biceps.", "Inhale and slowly lower the medicine ball back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta.", "Sostén un balón medicinal con un agarre supino, las palmas hacia arriba, y deja que los brazos cuelguen a los lados.", "Manteniendo la parte superior de los brazos quieta, exhala y curva el balón medicinal hacia los hombros.", "Haz una pausa breve en la parte alta, apretando los bíceps.", "Inhala y baja lentamente el balón medicinal de nuevo a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps sobre Fitball con Pierna Elevada', 'dumbbell-bicep-curl-on-exercise-ball-with-leg-raised.gif', 'upper arms', '["Sit on an exercise ball with your feet flat on the ground and your back straight.", "Hold a dumbbell in each hand with your palms facing forward and your arms fully extended.", "Slowly curl the dumbbells towards your shoulders, keeping your elbows close to your sides.", "Pause for a moment at the top of the movement, then slowly lower the dumbbells back to the starting position.", "While performing the bicep curl, raise one leg off the ground and hold it in the air for the duration of the exercise.", "Repeat for the desired number of repetitions, then switch legs and repeat."]', '["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.", "Sujeta una mancuerna en cada mano con las palmas hacia adelante y los brazos completamente extendidos.", "Flexiona lentamente las mancuernas hacia los hombros, manteniendo los codos cerca de los costados.", "Haz una pausa breve en la parte alta del movimiento, luego baja lentamente las mancuernas de vuelta a la posición inicial.", "Mientras realizas el curl de bíceps, levanta una pierna del suelo y mantenla en el aire durante todo el ejercicio.", "Repite el número de repeticiones deseado y luego cambia de pierna y repite."]'),
  ('Curl de Bíceps Tumbado Boca Arriba con Mancuernas', 'dumbbell-lying-supine-biceps-curl.gif', 'upper arms', '["Lie flat on a bench with your back and head supported, and your feet flat on the ground.", "Hold a dumbbell in each hand with your palms facing up and your arms fully extended.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca arriba en un banco con la espalda y la cabeza apoyadas, y los pies planos sobre el suelo.", "Sostén una mancuerna en cada mano con las palmas hacia arriba y los brazos completamente extendidos.", "Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.", "Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps Tumbado con Agarre Abierto', 'dumbbell-lying-wide-curl.gif', 'upper arms', '["Lie flat on a bench with a dumbbell in each hand, palms facing up and arms fully extended.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas hacia arriba y los brazos completamente extendidos.", "Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.", "Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps Tumbado de Lado con Peso Corporal', 'bodyweight-side-lying-biceps-curl.gif', 'upper arms', '["Lie on your side with your legs extended and your head supported by your arm.", "Hold your upper arm against your side and bend your elbow to curl your forearm towards your shoulder.", "Pause for a moment at the top, then slowly lower your forearm back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate de lado con las piernas extendidas y la cabeza apoyada sobre el brazo.", "Mantén el brazo superior junto al cuerpo y flexiona el codo para llevar el antebrazo hacia el hombro.", "Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps Tumbado en Polea', 'cable-lying-bicep-curl.gif', 'upper arms', '["Attach a straight bar to a low pulley cable machine.", "Lie face up on a flat bench with your feet flat on the ground.", "Grasp the bar with an underhand grip, hands shoulder-width apart.", "Extend your arms fully, keeping your elbows close to your sides.", "Keeping your upper arms stationary, exhale and curl the bar up towards your shoulders.", "Pause for a moment at the top, squeezing your biceps.", "Inhale and slowly lower the bar back to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Coloca una barra recta en una máquina de cable con polea baja.", "Túmbate boca arriba en un banco plano con los pies apoyados planos en el suelo.", "Sujeta la barra con agarre supino, manos separadas a la altura de los hombros.", "Extiende los brazos por completo, manteniendo los codos cerca de los costados.", "Manteniendo la parte superior de los brazos inmóvil, exhala y curva la barra hacia los hombros.", "Haz una pausa breve en la parte alta, apretando los bíceps.", "Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Bíceps Tumbado en Polea con Agarre Cerrado', 'cable-lying-close-grip-curl.gif', 'upper arms', '["Attach a straight bar to a low pulley cable machine.", "Lie face up on a flat bench with your feet flat on the ground.", "Grasp the bar with an underhand grip, hands shoulder-width apart.", "Extend your arms fully, keeping your elbows close to your sides.", "Keeping your upper arms stationary, curl the bar towards your chest by contracting your biceps.", "Pause for a moment at the top, squeezing your biceps.", "Slowly lower the bar back to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Coloca una barra recta en una máquina de cable con polea baja.", "Túmbate boca arriba en un banco plano con los pies apoyados planos en el suelo.", "Sujeta la barra con agarre supino, manos separadas a la altura de los hombros.", "Extiende los brazos por completo, manteniendo los codos cerca de los costados.", "Manteniendo la parte superior de los brazos inmóvil, curva la barra hacia el pecho contrayendo los bíceps.", "Haz una pausa breve en la parte alta, apretando los bíceps.", "Baja lentamente la barra de vuelta a la posición inicial, extendiendo los brazos por completo.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Muñeca Neutro a 1 Brazo sobre Banco', 'dumbbell-over-bench-one-arm-neutral-wrist-curl.gif', 'upper arms', '["Sit on a bench with a dumbbell in one hand and your arm extended over the bench, palm facing up.", "Keep your upper arm stationary and curl the dumbbell towards your shoulder, keeping your wrist in a neutral position.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Siéntate en un banco con una mancuerna en una mano y el brazo extendido sobre el banco, con la palma hacia arriba.", "Mantén el brazo superior quieto y flexiona la mancuerna hacia el hombro, manteniendo la muñeca en posición neutra.", "Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Curl de Muñeca Neutro con Mancuernas sobre Banco', 'dumbbell-over-bench-neutral-wrist-curl.gif', 'upper arms', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing up.", "Rest your forearms on the bench, allowing your wrists to hang off the edge.", "Keeping your upper arms stationary, exhale and curl the dumbbells up towards your shoulders.", "Pause for a moment at the top, then inhale and slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con los pies apoyados en el suelo y sostén una mancuerna en cada mano, con las palmas hacia arriba.", "Apoya los antebrazos sobre el banco, dejando que las muñecas cuelguen del borde.", "Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas hacia los hombros.", "Haz una pausa por un momento en la parte superior, luego inhala y baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl de Muñeca Neutro Sentado con Mancuernas', 'dumbbell-seated-neutral-wrist-curl.gif', 'upper arms', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand, palms facing each other.", "Rest your forearms on your thighs, allowing the dumbbells to hang down.", "Keeping your wrists in a neutral position, curl the dumbbells up towards your shoulders.", "Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna en cada mano, con las palmas mirándose entre sí.", "Apoya los antebrazos sobre los muslos, dejando que las mancuernas cuelguen hacia abajo.", "Manteniendo las muñecas en posición neutra, flexiona las mancuernas hacia los hombros.", "Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl Inverso a 1 Brazo de Pie', 'dumbbell-standing-one-arm-reverse-curl.gif', 'upper arms', '["Stand up straight with your feet shoulder-width apart and hold a dumbbell in one hand with an overhand grip.", "Keep your arm fully extended and close to your body, with your palm facing down.", "Slowly curl the dumbbell up towards your shoulder, keeping your upper arm stationary.", "Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch to the other arm."]', '["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros, sujetando una mancuerna con una mano con agarre prono.", "Mantén el brazo completamente extendido y cerca del cuerpo, con la palma hacia abajo.", "Flexiona lentamente la mancuerna hacia tu hombro, manteniendo fija la parte superior del brazo.", "Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia al otro brazo."]'),
  ('Curl Inverso a 1 Brazo en Polea', 'cable-reverse-one-arm-curl.gif', 'upper arms', '["Stand facing a cable machine with your feet shoulder-width apart.", "Grasp the cable handle with an underhand grip, palm facing down.", "Keep your elbow close to your side and slowly curl your forearm up towards your shoulder.", "Pause for a moment at the top, then slowly lower your forearm back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.", "Sujeta la agarradera del cable con un agarre supino, con la palma hacia abajo.", "Mantén el codo cerca del costado y curva lentamente el antebrazo hacia el hombro.", "Haz una pausa por un momento en la parte superior, luego baja lentamente el antebrazo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl Inverso con Barra Z', 'ez-barbell-reverse-grip-curl.gif', 'upper arms', '["Stand up straight with your feet shoulder-width apart and hold the ez barbell with an underhand grip.", "Keep your elbows close to your torso and your upper arms stationary throughout the exercise.", "Curl the barbell upwards by contracting your biceps, while exhaling.", "Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Slowly begin to bring the barbell back to the starting position as you inhale.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre supino.", "Mantén los codos cerca del torso y los brazos superiores inmóviles durante todo el ejercicio.", "Sube la barra contrayendo los bíceps, mientras exhalas.", "Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Comienza a regresar la barra lentamente a la posición inicial mientras inhalas.", "Repite el número de repeticiones deseado."]'),
  ('Curl Inverso de Pie con Mancuernas', 'dumbbell-standing-reverse-curl.gif', 'upper arms', '["Stand up straight with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing your body.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano, con las palmas hacia tu cuerpo.", "Manteniendo fija la parte superior de los brazos, exhala y flexiona los pesos mientras contraes los bíceps. Continúa subiendo los pesos hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl Inverso en Polea', 'cable-reverse-curl.gif', 'upper arms', '["Attach a straight bar to a low pulley cable machine.", "Stand facing the machine with your feet shoulder-width apart and your knees slightly bent.", "Grasp the bar with an underhand grip, hands shoulder-width apart.", "Keep your elbows close to your sides and your upper arms stationary throughout the exercise.", "Exhale and curl the bar up towards your shoulders, contracting your biceps.", "Pause for a moment at the top, squeezing your biceps.", "Inhale and slowly lower the bar back to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Coloca una barra recta en una máquina de cable con polea baja.", "Ponte de pie frente a la máquina con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.", "Sujeta la barra con agarre supino, manos separadas a la altura de los hombros.", "Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio.", "Exhala y flexiona la barra hacia los hombros, contrayendo los bíceps.", "Haz una pausa breve en la parte alta, apretando los bíceps.", "Inhala y baja lentamente la barra de vuelta a la posición inicial, extendiendo completamente los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Curl Martillo a 1 Brazo de Pie', 'dumbbell-one-arm-standing-hammer-curl.gif', 'upper arms', '["Stand up straight with a dumbbell in each hand, palms facing your torso.", "Keep your elbows close to your torso and your upper arms stationary.", "Exhale and curl the weights while contracting your biceps.", "Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso.", "Mantén los codos cerca del torso y los brazos superiores quietos.", "Exhala y flexiona las pesas mientras contraes los bíceps.", "Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl Martillo a 1 Brazo Sentado', 'dumbbell-one-arm-seated-hammer-curl.gif', 'upper arms', '["Sit on a bench with your back straight and feet flat on the ground.", "Hold a dumbbell in one hand with a neutral grip (palms facing each other).", "Rest your elbow on the inside of your thigh, just above the knee.", "Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.", "Pause for a moment at the top, squeezing your biceps.", "Inhale and slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.", "Sostén una mancuerna en una mano con agarre neutro (palmas enfrentadas entre sí).", "Apoya el codo en la parte interna del muslo, justo por encima de la rodilla.", "Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro.", "Haz una pausa breve en la parte alta, apretando los bíceps.", "Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Curl Martillo Alterno con Press de Pie', 'dumbbell-standing-alternate-hammer-curl-and-press.gif', 'upper arms', '["Stand up straight with a dumbbell in each hand, palms facing your body.", "Keep your elbows close to your torso and your back straight.", "Exhale and curl the dumbbell in your right hand towards your shoulder, keeping your upper arm stationary.", "Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.", "Inhale and slowly lower the dumbbell back to the starting position.", "Repeat the curl with your left hand.", "After completing the curl with your left hand, exhale and press the dumbbell in your right hand overhead.", "Extend your arm fully and hold for a moment at the top.", "Inhale and slowly lower the dumbbell back to the starting position.", "Repeat the press with your left hand.", "Continue alternating between curls and presses for the desired number of repetitions."]', '["Ponte de pie con una mancuerna en cada mano, con las palmas hacia tu cuerpo.", "Mantén los codos cerca del torso y la espalda recta.", "Exhala y flexiona la mancuerna de tu mano derecha hacia el hombro, manteniendo el brazo superior quieto.", "Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.", "Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el curl con la mano izquierda.", "Después de completar el curl con la mano izquierda, exhala y presiona la mancuerna de la mano derecha por encima de la cabeza.", "Extiende completamente el brazo y mantén la posición por un momento en la parte superior.", "Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el press con la mano izquierda.", "Continúa alternando entre curls y press durante el número de repeticiones deseado."]'),
  ('Curl Martillo Alterno Sentado con Mancuernas', 'dumbbell-alternate-seated-hammer-curl.gif', 'upper arms', '["Sit on a bench with a dumbbell in each hand, palms facing your torso and arms extended down.", "Keep your back straight and your elbows close to your torso.", "Exhale and curl the dumbbell in your right hand towards your shoulder, keeping your upper arm stationary.", "Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.", "Pause for a brief moment, then inhale and slowly lower the dumbbell back to the starting position.", "Repeat the movement with your left arm.", "Continue alternating arms for the desired number of repetitions."]', '["Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia tu torso y los brazos extendidos hacia abajo.", "Mantén la espalda recta y los codos cerca del torso.", "Exhala y flexiona la mancuerna de tu mano derecha hacia el hombro, manteniendo el brazo superior quieto.", "Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.", "Haz una pausa breve, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el movimiento con el brazo izquierdo.", "Continúa alternando los brazos durante el número de repeticiones deseado."]'),
  ('Curl Martillo Alterno Sentado sobre Fitball', 'dumbbell-seated-alternate-hammer-curl-on-exercise-ball.gif', 'upper arms', '["Sit on an exercise ball with your feet flat on the ground and your back straight.", "Hold a dumbbell in each hand with your palms facing your body and your arms fully extended.", "Keeping your upper arms stationary, exhale and curl one dumbbell up towards your shoulder while keeping your palm facing your body.", "Continue to raise the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly lower the dumbbell back to the starting position.", "Repeat the movement with the opposite arm.", "Continue alternating arms for the desired number of repetitions."]', '["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.", "Sostén una mancuerna en cada mano con las palmas hacia el cuerpo y los brazos completamente extendidos.", "Manteniendo la parte superior de los brazos fija, exhala y flexiona una mancuerna hacia el hombro mientras mantienes la palma hacia tu cuerpo.", "Continúa levantando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el movimiento con el brazo contrario.", "Continúa alternando los brazos durante el número de repeticiones deseado."]'),
  ('Curl Martillo con Barra Olímpica', 'olympic-barbell-hammer-curl.gif', 'upper arms', '["Stand up straight with your feet shoulder-width apart and hold an Olympic barbell with an overhand grip.", "Let the barbell hang at arm''s length in front of your thighs, with your palms facing your body.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra olímpica con un agarre prono.", "Deja que la barra cuelgue a la altura de los brazos frente a tus muslos, con las palmas hacia tu cuerpo.", "Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.", "Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl Martillo con Mancuernas y Arm Blaster', 'dumbbell-hammer-curls-with-arm-blaster.gif', 'upper arms', '["Stand up straight with a dumbbell in each hand, palms facing your torso.", "Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.", "This will be your starting position.", "Now, while holding your upper arm stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Then, inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the recommended amount of repetitions."]', '["Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso.", "Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante.", "Esta será tu posición inicial.", "Ahora, manteniendo el brazo superior quieto, exhala y flexiona los brazos contrayendo los bíceps.", "Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Luego, inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones recomendado."]'),
  ('Curl Martillo en Banco Inclinado', 'dumbbell-incline-hammer-curl.gif', 'upper arms', '["Sit on an incline bench with a dumbbell in each hand, palms facing your torso and arms fully extended.", "Keep your back against the bench and your feet flat on the floor.", "While keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas hacia el torso y los brazos completamente extendidos.", "Mantén la espalda contra el banco y los pies apoyados en el suelo.", "Manteniendo los brazos superiores quietos, exhala y flexiona los brazos contrayendo los bíceps.", "Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl Martillo en Polea con Cuerda', 'cable-hammer-curl-with-rope.gif', 'upper arms', '["Stand upright with your feet shoulder-width apart and a slight bend in your knees.", "Hold the cable rope attachment with an underhand grip, palms facing each other, and your arms fully extended.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the cable rope attachment until your biceps are fully contracted and the rope is at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the cable rope attachment back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y una ligera flexión en las rodillas.", "Sujeta el accesorio de cuerda del cable con agarre supino, palmas mirándose entre sí, y los brazos completamente extendidos.", "Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.", "Continúa levantando el accesorio de cuerda del cable hasta que los bíceps estén completamente contraídos y la cuerda esté a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y comienza a bajar lentamente el accesorio de cuerda del cable de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl Martillo Predicador a 1 Brazo', 'dumbbell-one-arm-hammer-preacher-curl.gif', 'upper arms', '["Sit on a preacher bench with a dumbbell in one hand and your upper arm resting on the pad.", "Hold the dumbbell with a neutral grip (palms facing your body).", "Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.", "Pause for a moment at the top, squeezing your biceps.", "Inhale and slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Siéntate en un banco scott con una mancuerna en una mano y el brazo superior apoyado sobre la almohadilla.", "Sostén la mancuerna con agarre neutro (palmas hacia el cuerpo).", "Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro.", "Haz una pausa breve en la parte alta, apretando los bíceps.", "Inhala y baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Curl Martillo Predicador a 1 Brazo en Polea con Cuerda', 'cable-rope-one-arm-hammer-preacher-curl.gif', 'upper arms', '["Attach a rope handle to a low pulley cable machine.", "Stand facing the machine with your feet shoulder-width apart.", "Grasp the rope handle with an underhand grip, palms facing up.", "Position your upper arm against the preacher bench pad, keeping your elbow slightly bent.", "Keep your back straight and your core engaged throughout the exercise.", "Slowly curl the rope handle towards your shoulder, keeping your upper arm stationary.", "Squeeze your biceps at the top of the movement, then slowly lower the rope handle back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Sujeta una agarradera de cuerda a una máquina de cable con polea baja.", "Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.", "Sujeta la agarradera de cuerda con un agarre supino, con las palmas hacia arriba.", "Coloca la parte superior del brazo contra la almohadilla del banco scott, manteniendo el codo ligeramente flexionado.", "Mantén la espalda recta y el core activado durante todo el ejercicio.", "Curva lentamente la agarradera de cuerda hacia el hombro, manteniendo la parte superior del brazo inmóvil.", "Aprieta el bíceps en la parte más alta del movimiento y luego baja lentamente la agarradera de cuerda de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Curl Martillo Predicador Alterno con Mancuernas', 'dumbbell-alternate-hammer-preacher-curl.gif', 'upper arms', '["Sit on a preacher bench with a dumbbell in each hand, palms facing your torso and arms fully extended.", "Keep your upper arms stationary and exhale as you curl the weights while contracting your biceps.", "Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the recommended amount of repetitions."]', '["Siéntate en un banco scott con una mancuerna en cada mano, con las palmas hacia tu torso y los brazos completamente extendidos.", "Mantén los brazos superiores fijos y exhala mientras levantas el peso contrayendo los bíceps.", "Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones recomendado."]'),
  ('Curl Martillo Predicador con Mancuernas', 'dumbbell-peacher-hammer-curl.gif', 'upper arms', '["Stand up straight with a dumbbell in each hand, palms facing your torso.", "Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward.", "This will be your starting position.", "Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Then, inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the recommended amount of repetitions."]', '["Ponte de pie con una mancuerna en cada mano, con las palmas mirando hacia el torso.", "Mantén los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia adelante.", "Esta será tu posición inicial.", "Ahora, manteniendo los brazos superiores quietos, exhala y flexiona los brazos contrayendo los bíceps.", "Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Luego, inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones recomendado."]'),
  ('Curl Martillo Predicador en Polea con Cuerda', 'cable-rope-hammer-preacher-curl.gif', 'upper arms', '["Attach a rope attachment to a low pulley cable machine.", "Stand facing the machine with your feet shoulder-width apart.", "Grasp the rope with a neutral grip (palms facing each other).", "Position your upper arms against the preacher bench pad, keeping your elbows slightly bent.", "Keeping your upper arms stationary, exhale and curl the rope towards your shoulders by contracting your biceps.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly lower the rope back to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta un accesorio de cuerda a una máquina de cable con polea baja.", "Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.", "Sujeta la cuerda con un agarre neutro (las palmas una frente a la otra).", "Coloca la parte superior de los brazos contra la almohadilla del banco scott, manteniendo los codos ligeramente flexionados.", "Manteniendo la parte superior de los brazos inmóvil, exhala y curva la cuerda hacia los hombros contrayendo los bíceps.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y baja lentamente la cuerda de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl Martillo Prono a 1 Brazo', 'dumbbell-one-arm-prone-hammer-curl.gif', 'upper arms', '["Lie face down on a flat bench with a dumbbell in one hand, palm facing your body and arm fully extended.", "Keep your upper arm stationary and curl the dumbbell towards your shoulder, contracting your biceps.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Túmbate boca abajo en un banco plano con una mancuerna en una mano, con la palma hacia el cuerpo y el brazo completamente extendido.", "Mantén el brazo superior quieto y flexiona la mancuerna hacia el hombro, contrayendo el bíceps.", "Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Curl Martillo Prono en Banco Inclinado', 'dumbbell-prone-incline-hammer-curl.gif', 'upper arms', '["Adjust the bench to a 45-degree incline.", "Lie face down on the bench with a dumbbell in each hand, palms facing each other.", "Allow your arms to hang straight down towards the floor, keeping your elbows slightly bent.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta el banco a una inclinación de 45 grados.", "Túmbate boca abajo en el banco con una mancuerna en cada mano, con las palmas mirándose entre sí.", "Deja que los brazos cuelguen rectos hacia el suelo, manteniendo los codos ligeramente flexionados.", "Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.", "Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl Martillo Sentado con Mancuernas', 'dumbbell-seated-hammer-curl.gif', 'upper arms', '["Sit on a bench with a dumbbell in each hand, palms facing your torso and arms extended straight down.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia tu torso y los brazos extendidos rectos hacia abajo.", "Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.", "Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl Martillo sobre Fitball', 'dumbbell-hammer-curl-on-exercise-ball.gif', 'upper arms', '["Sit on an exercise ball with your feet flat on the ground and your back straight.", "Hold a dumbbell in each hand with your palms facing your body and your arms fully extended.", "Keeping your upper arms stationary, exhale and curl the dumbbells while contracting your biceps.", "Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.", "Sostén una mancuerna en cada mano con las palmas hacia el cuerpo y los brazos completamente extendidos.", "Manteniendo los brazos superiores quietos, exhala y flexiona las mancuernas contrayendo los bíceps.", "Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl por Encima de la Cabeza en Polea sobre Fitball', 'cable-overhead-curl-on-exercise-ball.gif', 'upper arms', '["Sit on an exercise ball and hold the cable handle with an underhand grip.", "Extend your arms fully overhead, keeping your elbows close to your ears.", "Slowly curl the cable down towards your forehead, keeping your upper arms stationary.", "Pause for a moment at the bottom of the movement, then slowly return to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate sobre un balón de ejercicio y sujeta la agarradera del cable con un agarre supino.", "Extiende los brazos completamente por encima de la cabeza, manteniendo los codos cerca de las orejas.", "Curva lentamente el cable hacia la frente, manteniendo la parte superior de los brazos inmóvil.", "Haz una pausa breve en la parte más baja del movimiento, luego vuelve lentamente a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl Predicador a 1 Brazo en Polea', 'cable-one-arm-preacher-curl.gif', 'upper arms', '["Adjust the cable machine so that the preacher curl pad is at chest height.", "Stand facing the cable machine with your feet shoulder-width apart.", "Grasp the cable handle with an underhand grip and position your upper arm against the preacher curl pad.", "Keep your back straight and your core engaged.", "Slowly curl the cable handle towards your shoulder, keeping your upper arm against the pad.", "Pause for a moment at the top of the movement, squeezing your biceps.", "Slowly lower the cable handle back to the starting position.", "Repeat for the desired number of repetitions.", "Switch arms and repeat the exercise."]', '["Ajusta la máquina de cable de modo que la almohadilla para curl en banco scott quede a la altura del pecho.", "Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.", "Sujeta la agarradera del cable con un agarre supino y coloca la parte superior del brazo contra la almohadilla del banco scott.", "Mantén la espalda recta y el core activado.", "Curva lentamente la agarradera del cable hacia el hombro, manteniendo la parte superior del brazo contra la almohadilla.", "Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.", "Baja lentamente la agarradera del cable de vuelta a la posición inicial.", "Repite el número de repeticiones deseado.", "Cambia de brazo y repite el ejercicio."]'),
  ('Curl Predicador Alterno con Mancuernas', 'dumbbell-alternate-preacher-curl.gif', 'upper arms', '["Sit on a preacher bench with a dumbbell in each hand, palms facing up.", "Rest your upper arms on the pad of the preacher bench, allowing your arms to fully extend.", "Keeping your upper arms stationary, exhale and curl the dumbbell in your right hand as you contract your biceps.", "Continue to curl the dumbbell until your biceps are fully contracted and the dumbbell is at shoulder level.", "Pause for a moment, then inhale and slowly lower the dumbbell back to the starting position.", "Repeat the movement with your left arm.", "Continue alternating arms for the desired number of repetitions."]', '["Siéntate en un banco scott con una mancuerna en cada mano, con las palmas hacia arriba.", "Apoya la parte superior de los brazos en la almohadilla del banco scott, permitiendo que los brazos se extiendan completamente.", "Manteniendo los brazos superiores quietos, exhala y flexiona la mancuerna en tu mano derecha mientras contraes el bíceps.", "Continúa flexionando la mancuerna hasta que el bíceps esté completamente contraído y la mancuerna esté a la altura del hombro.", "Haz una pausa breve, luego inhala y baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el movimiento con el brazo izquierdo.", "Continúa alternando los brazos durante el número de repeticiones deseado."]'),
  ('Curl Predicador con Barra Z y Agarre Cerrado', 'ez-barbell-close-grip-preacher-curl.gif', 'upper arms', '["Sit on a preacher curl bench and place your upper arms on the pad, gripping the ez barbell with an underhand grip.", "Rest your triceps on the pad and fully extend your arms, keeping your back straight.", "Slowly curl the barbell towards your shoulders, contracting your biceps.", "Pause for a moment at the top, squeezing your biceps.", "Lower the barbell back to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco scott y coloca los brazos superiores sobre la almohadilla, sujetando la barra EZ con agarre supino.", "Apoya los tríceps sobre la almohadilla y extiende los brazos por completo, manteniendo la espalda recta.", "Sube lentamente la barra hacia los hombros, contrayendo los bíceps.", "Haz una pausa breve en la parte alta, apretando los bíceps.", "Baja la barra a la posición inicial, extendiendo los brazos por completo.", "Repite el número de repeticiones deseado."]'),
  ('Curl Predicador con Mancuernas', 'dumbbell-preacher-curl.gif', 'upper arms', '["Sit on a preacher curl bench with your upper arms resting on the pad and your chest against it.", "Hold a dumbbell in each hand with your palms facing up and your arms fully extended.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco scott con la parte superior de los brazos apoyada en la almohadilla y el pecho contra ella.", "Sostén una mancuerna en cada mano con las palmas hacia arriba y los brazos completamente extendidos.", "Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.", "Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl Predicador de Pie con Mancuernas', 'dumbbell-standing-preacher-curl.gif', 'upper arms', '["Stand upright with your feet shoulder-width apart and hold a dumbbell in each hand, palms facing forward.", "Rest the back of your upper arms against the preacher bench or an incline bench, with your elbows slightly bent.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna en cada mano, con las palmas hacia adelante.", "Apoya la parte posterior de la parte superior de los brazos contra el banco scott o un banco inclinado, con los codos ligeramente flexionados.", "Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.", "Continúa levantando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl Predicador en Máquina', 'lever-preacher-curl.gif', 'upper arms', '["Adjust the seat height and position yourself on the leverage machine.", "Place your upper arms on the pad and grip the handles with an underhand grip.", "Keep your back straight and your elbows positioned on the pad.", "Exhale and curl your forearms towards your upper arms, contracting your biceps.", "Pause for a moment at the top of the movement, squeezing your biceps.", "Inhale and slowly lower the handles back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento y colócate en la máquina de palanca.", "Coloca los brazos superiores en la almohadilla y sujeta las asas con un agarre supino.", "Mantén la espalda recta y los codos colocados sobre la almohadilla.", "Exhala y flexiona los antebrazos hacia los brazos superiores, contrayendo los bíceps.", "Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.", "Inhala y baja lentamente las asas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl Predicador en Máquina con Agarre Neutro', 'lever-hammer-grip-preacher-curl.gif', 'upper arms', '["Adjust the seat height and position yourself on the leverage machine.", "Place your upper arms on the preacher pad, ensuring your chest is pressed against it.", "Grasp the handles with a hammer grip (palms facing each other).", "Keeping your upper arms stationary, exhale and curl the handles towards your shoulders.", "Pause for a moment at the top, squeezing your biceps.", "Inhale and slowly lower the handles back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento y colócate en la máquina de palanca.", "Coloca los brazos superiores sobre la almohadilla de predicador, asegurándote de que el pecho quede apoyado contra ella.", "Sujeta las asas con agarre neutro (palmas una frente a la otra).", "Manteniendo los brazos superiores inmóviles, exhala y flexiona las asas hacia los hombros.", "Haz una pausa breve en la parte alta, apretando los bíceps.", "Inhala y baja lentamente las asas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl Predicador en Máquina con Agarre Prono', 'lever-reverse-grip-preacher-curl.gif', 'upper arms', '["Adjust the seat height and position yourself on the leverage machine.", "Grasp the handles with an underhand grip, palms facing up.", "Rest your upper arms on the preacher pad, ensuring your elbows are fully extended.", "Keeping your upper arms stationary, exhale and curl the handles towards your shoulders.", "Pause for a moment at the top of the movement, squeezing your biceps.", "Inhale and slowly lower the handles back to the starting position, fully extending your elbows.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento y colócate en la máquina de palanca.", "Sujeta las asas con un agarre supino, con las palmas hacia arriba.", "Apoya los brazos superiores sobre la almohadilla de predicador, asegurándote de que los codos queden completamente extendidos.", "Manteniendo los brazos superiores inmóviles, exhala y flexiona las asas hacia los hombros.", "Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.", "Inhala y baja lentamente las agarraderas de vuelta a la posición inicial, extendiendo los codos por completo.", "Repite el número de repeticiones deseado."]'),
  ('Curl Predicador en Polea', 'cable-preacher-curl.gif', 'upper arms', '["Adjust the cable machine so that the preacher curl pad is at chest height.", "Sit on the preacher curl bench and place your upper arms on the pad, gripping the cable attachment with an underhand grip.", "Keep your back straight and your elbows tucked in at your sides.", "Slowly curl the cable attachment up towards your shoulders, squeezing your biceps at the top of the movement.", "Pause for a moment, then slowly lower the cable attachment back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la máquina de cable de modo que la almohadilla para curl en banco scott quede a la altura del pecho.", "Siéntate en el banco scott y coloca la parte superior de los brazos sobre la almohadilla, agarrando el accesorio del cable con un agarre supino.", "Mantén la espalda recta y los codos pegados a los costados.", "Curva lentamente el accesorio del cable hacia los hombros, apretando los bíceps en la parte más alta del movimiento.", "Haz una pausa por un momento y luego baja lentamente el accesorio del cable de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl Predicador Inverso a 1 Brazo con Mancuerna', 'dumbbell-one-arm-reverse-preacher-curl.gif', 'upper arms', '["Sit on a preacher bench with your chest against the pad and your arm extended over the edge of the bench, holding a dumbbell with an underhand grip.", "Lower the dumbbell slowly until your arm is fully extended.", "Curl the dumbbell back up towards your shoulder, keeping your upper arm stationary.", "Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Siéntate en un banco scott con el pecho contra la almohadilla y el brazo extendido sobre el borde del banco, sosteniendo una mancuerna con agarre supino.", "Baja lentamente la mancuerna hasta que el brazo quede completamente extendido.", "Flexiona la mancuerna de nuevo hacia el hombro, manteniendo el brazo superior quieto.", "Contrae el bíceps en la parte más alta del movimiento, luego baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Curl Predicador Inverso a 1 Brazo en Polea', 'cable-one-arm-reverse-preacher-curl.gif', 'upper arms', '["Adjust the cable machine so that the pulley is at the lowest position.", "Stand facing the cable machine with your feet shoulder-width apart.", "Grasp the cable handle with an underhand grip and position your upper arm against the preacher bench pad.", "Keep your back straight and your core engaged throughout the exercise.", "Slowly curl your forearm towards your bicep, keeping your upper arm stationary against the pad.", "Pause for a moment at the top of the movement, squeezing your bicep.", "Slowly lower the cable handle back to the starting position.", "Repeat for the desired number of repetitions.", "Switch arms and repeat the exercise."]', '["Ajusta la máquina de cable de modo que la polea quede en la posición más baja.", "Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.", "Sujeta la agarradera del cable con un agarre supino y coloca la parte superior del brazo contra la almohadilla del banco scott.", "Mantén la espalda recta y el core activado durante todo el ejercicio.", "Curva lentamente el antebrazo hacia el bíceps, manteniendo la parte superior del brazo inmóvil contra la almohadilla.", "Haz una pausa por un momento en la parte más alta del movimiento, apretando el bíceps.", "Baja lentamente la agarradera del cable de vuelta a la posición inicial.", "Repite el número de repeticiones deseado.", "Cambia de brazo y repite el ejercicio."]'),
  ('Curl Predicador Inverso con Barra', 'barbell-reverse-preacher-curl.gif', 'upper arms', '["Sit on a preacher bench with your chest against the pad and your arms extended straight down, holding a barbell with an overhand grip.", "Keeping your upper arms stationary, exhale and curl the barbell upward while contracting your biceps.", "Continue to raise the barbell until your biceps are fully contracted and the barbell is at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco predicador con el pecho apoyado en el cojín y los brazos extendidos rectos hacia abajo, sujetando una barra con un agarre pronado.", "Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia arriba mientras contraes los bíceps.", "Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y baja lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl Predicador Inverso con Barra Z', 'ez-barbell-reverse-grip-preacher-curl.gif', 'upper arms', '["Sit on a preacher bench with your chest against the pad and your feet flat on the floor.", "Grasp the ez barbell with an underhand grip, hands shoulder-width apart.", "Rest your upper arms on the pad, allowing your forearms to hang down.", "Keeping your upper arms stationary, exhale and curl the barbell up towards your shoulders.", "Pause for a moment at the top, then inhale and slowly lower the barbell back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco scott con el pecho apoyado en la almohadilla y los pies planos sobre el suelo.", "Sujeta la barra EZ con agarre supino, manos separadas a la altura de los hombros.", "Apoya los brazos superiores en la almohadilla, dejando que los antebrazos cuelguen hacia abajo.", "Manteniendo los brazos superiores fijos, exhala y levanta la barra hacia los hombros.", "Haz una pausa breve en la parte más alta, luego inhala y baja lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl Predicador Inverso con Mancuernas', 'dumbbell-reverse-preacher-curl.gif', 'upper arms', '["Sit on a preacher bench with your upper arms resting on the pad and your chest against the support.", "Hold a dumbbell in each hand with an underhand grip, palms facing up.", "Keeping your upper arms stationary, exhale and curl the dumbbells as you contract your biceps.", "Continue to curl the dumbbells until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco predicador con los brazos superiores apoyados en el cojín y el pecho contra el soporte.", "Sujeta una mancuerna en cada mano con agarre supino, con las palmas hacia arriba.", "Manteniendo la parte superior de los brazos fija, exhala y flexiona las mancuernas mientras contraes los bíceps.", "Continúa flexionando las mancuernas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl Predicador Inverso en Polea', 'cable-reverse-preacher-curl.gif', 'upper arms', '["Adjust the cable machine so that the preacher curl pad is at chest height.", "Sit on the preacher curl bench and place your upper arms on the pad, with your palms facing down and your elbows fully extended.", "Grab the cable handles with an underhand grip, shoulder-width apart.", "Keeping your upper arms stationary, exhale and curl the handles towards your shoulders, contracting your biceps.", "Pause for a moment at the top of the movement, squeezing your biceps.", "Inhale and slowly lower the handles back to the starting position, fully extending your elbows.", "Repeat for the desired number of repetitions."]', '["Ajusta la máquina de cable de modo que la almohadilla para curl en banco scott quede a la altura del pecho.", "Siéntate en el banco scott y coloca la parte superior de los brazos sobre la almohadilla, con las palmas hacia abajo y los codos completamente extendidos.", "Agarra las agarraderas del cable con un agarre supino, separadas a la altura de los hombros.", "Manteniendo la parte superior de los brazos inmóvil, exhala y curva las agarraderas hacia los hombros, contrayendo los bíceps.", "Haz una pausa breve en la parte más alta del movimiento, contrayendo los bíceps.", "Inhala y baja lentamente las agarraderas de vuelta a la posición inicial, extendiendo los codos por completo.", "Repite el número de repeticiones deseado."]'),
  ('Curl Predicador sobre Fitball', 'dumbbell-preacher-curl-over-exercise-ball.gif', 'upper arms', '["Sit on an exercise ball with your feet flat on the ground and your back straight.", "Hold a dumbbell in one hand with an underhand grip, resting your elbow on the exercise ball.", "Keeping your upper arm stationary, exhale and curl the dumbbell up towards your shoulder.", "Pause for a moment at the top, then inhale and slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.", "Sujeta una mancuerna con una mano con agarre supino, apoyando el codo sobre el balón de estabilidad.", "Manteniendo el brazo superior quieto, exhala y flexiona la mancuerna hacia el hombro.", "Haz una pausa por un momento arriba, luego inhala y baja lentamente la mancuerna a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Curl Predicador Tumbado con Barra', 'barbell-lying-preacher-curl.gif', 'upper arms', '["Sit on a preacher bench with your chest against the pad and your arms extended over the edge, holding a barbell with an underhand grip.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the bar until your biceps are fully contracted and the bar is at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco predicador con el pecho apoyado en el respaldo y los brazos extendidos sobre el borde, sujetando una barra con un agarre supino.", "Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.", "Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl Prono a 1 Brazo con Mancuerna', 'dumbbell-one-arm-prone-curl.gif', 'upper arms', '["Lie face down on a flat bench with a dumbbell in one hand, palm facing down.", "Extend your arm fully, letting it hang straight down towards the floor.", "Keeping your upper arm stationary, curl the dumbbell up towards your shoulder by contracting your biceps.", "Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Túmbate boca abajo en un banco plano con una mancuerna en una mano, con la palma hacia abajo.", "Extiende completamente el brazo, dejando que cuelgue recto hacia el suelo.", "Manteniendo el brazo superior quieto, flexiona la mancuerna hacia el hombro contrayendo el bíceps.", "Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Curl Prono en Banco Inclinado con Barra', 'barbell-prone-incline-curl.gif', 'upper arms', '["Set up an incline bench at a 45-degree angle.", "Lie face down on the bench with your chest and stomach resting against it.", "Hold a barbell with an underhand grip, shoulder-width apart.", "Extend your arms fully, allowing the barbell to hang down towards the floor.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the barbell until your biceps are fully contracted and the bar is at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the barbell back to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca un banco inclinado a un ángulo de 45 grados.", "Túmbate boca abajo en el banco con el pecho y el abdomen apoyados contra él.", "Sujeta una barra con un agarre supino, separado a la altura de los hombros.", "Extiende completamente los brazos, dejando que la barra cuelgue hacia el suelo.", "Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.", "Continúa levantando la barra hasta que los bíceps estén completamente contraídos y la barra esté a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y comienza a bajar lentamente la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl Prono en Banco Inclinado con Mancuernas', 'dumbbell-prone-incline-curl.gif', 'upper arms', '["Adjust the bench to a 45-degree incline.", "Lie face down on the bench with your chest and stomach resting against it.", "Hold a dumbbell in each hand with your palms facing down and your arms fully extended.", "Keeping your upper arms stationary, exhale and curl the weights while contracting your biceps.", "Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level.", "Hold the contracted position for a brief pause as you squeeze your biceps.", "Inhale and slowly begin to lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta el banco a una inclinación de 45 grados.", "Túmbate boca abajo en el banco con el pecho y el abdomen apoyados contra él.", "Sujeta una mancuerna en cada mano con las palmas hacia abajo y los brazos completamente extendidos.", "Manteniendo los brazos superiores fijos, exhala y levanta el peso mientras contraes los bíceps.", "Continúa levantando las pesas hasta que los bíceps estén completamente contraídos y las mancuernas estén a la altura de los hombros.", "Mantén la posición contraída durante una breve pausa mientras aprietas los bíceps.", "Inhala y comienza a bajar lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl Zottman con Mancuernas', 'dumbbell-zottman-curl.gif', 'upper arms', '["Stand up straight with a dumbbell in each hand, palms facing your body.", "Keep your elbows close to your torso and rotate your palms to face forward.", "Curl the dumbbells up to your shoulders while keeping your upper arms stationary.", "At the top of the movement, rotate your wrists so that your palms are facing away from your body.", "Slowly lower the dumbbells back to the starting position, rotating your palms back to facing your body.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con una mancuerna en cada mano, con las palmas hacia tu cuerpo.", "Mantén los codos cerca del torso y gira las palmas para que queden hacia adelante.", "Flexiona las mancuernas hacia los hombros mientras mantienes fija la parte superior de los brazos.", "En la parte superior del movimiento, gira las muñecas de modo que las palmas queden alejadas de tu cuerpo.", "Baja lentamente las mancuernas de vuelta a la posición inicial, girando las palmas de nuevo hacia tu cuerpo.", "Repite el número de repeticiones deseado."]'),
  ('Curl Zottman Predicador a 1 Brazo', 'dumbbell-one-arm-zottman-preacher-curl.gif', 'upper arms', '["Sit on a preacher curl bench and hold a dumbbell in one hand with an underhand grip.", "Rest your upper arm on the preacher bench pad, allowing your arm to fully extend.", "Curl the dumbbell up towards your shoulder, keeping your upper arm stationary.", "At the top of the curl, rotate your wrist so that your palm faces up.", "Slowly lower the dumbbell back down to the starting position, rotating your wrist back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Siéntate en un banco scott y sostén una mancuerna en una mano con agarre supino.", "Apoya el brazo superior sobre la almohadilla del banco scott, permitiendo que el brazo se extienda completamente.", "Flexiona la mancuerna de nuevo hacia el hombro, manteniendo el brazo superior quieto.", "En la parte superior del curl, gira la muñeca de modo que la palma quede hacia arriba.", "Baja lentamente la mancuerna de vuelta a la posición inicial, girando la muñeca de regreso a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Curl Zottman Predicador de Pie', 'dumbbell-standing-zottman-preacher-curl.gif', 'upper arms', '["Stand up straight with a dumbbell in each hand, palms facing forward.", "Place your upper arms against the preacher bench and keep your elbows slightly bent.", "Curl the dumbbells up towards your shoulders while keeping your upper arms stationary.", "At the top of the movement, rotate your wrists so that your palms are facing downward.", "Slowly lower the dumbbells back to the starting position, rotating your wrists back to the starting position as well.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con una mancuerna en cada mano, con las palmas hacia adelante.", "Apoya la parte superior de los brazos contra el banco scott y mantén los codos ligeramente flexionados.", "Flexiona las mancuernas hacia los hombros mientras mantienes fija la parte superior de los brazos.", "En la parte superior del movimiento, gira las muñecas de modo que las palmas queden hacia abajo.", "Baja lentamente las mancuernas de vuelta a la posición inicial, girando también las muñecas a su posición original.", "Repite el número de repeticiones deseado."]'),
  ('Curl Zottman Predicador Sentado', 'dumbbell-zottman-preacher-curl.gif', 'upper arms', '["Sit on a preacher bench with a dumbbell in each hand, palms facing up and elbows resting on the pad.", "Curl the dumbbells up towards your shoulders, keeping your upper arms stationary and your palms facing up.", "At the top of the curl, rotate your wrists so that your palms are facing down.", "Slowly lower the dumbbells back down to the starting position, rotating your wrists back to the starting position as you do so.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco scott con una mancuerna en cada mano, con las palmas hacia arriba y los codos apoyados en la almohadilla.", "Flexiona las mancuernas hacia los hombros, manteniendo fija la parte superior de los brazos y las palmas hacia arriba.", "En la parte superior del curl, gira las muñecas de modo que las palmas queden hacia abajo.", "Baja lentamente las mancuernas de vuelta a la posición inicial, girando también las muñecas a su posición original mientras lo haces.", "Repite el número de repeticiones deseado."]'),
  ('Dominada Prona al Ancho de Hombros', 'biceps-pull-up.gif', 'upper arms', '["Hang from a pull-up bar with your palms facing away from you and your hands shoulder-width apart.", "Engage your core and pull yourself up by bending your elbows, bringing your chest towards the bar.", "Pause at the top of the movement, then slowly lower yourself back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Cuélgate de una barra de dominadas con las palmas mirando hacia afuera y las manos separadas a la altura de los hombros.", "Activa el core y tira de tu cuerpo hacia arriba flexionando los codos, llevando el pecho hacia la barra.", "Haz una pausa en la parte más alta del movimiento, luego baja lentamente de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Dominada Supina Cerrada para Bíceps', 'biceps-narrow-pull-ups.gif', 'upper arms', '["Hang from a pull-up bar with your palms facing towards you and your hands shoulder-width apart.", "Engage your core and pull yourself up towards the bar, focusing on using your biceps to lift your body.", "Pause for a moment at the top, then slowly lower yourself back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Cuélgate de una barra de dominadas con las palmas mirando hacia ti y las manos separadas a la altura de los hombros.", "Activa el core y tira de tu cuerpo hacia la barra, enfocándote en usar los bíceps para levantar el cuerpo.", "Haz una pausa breve en la parte más alta, luego baja lentamente de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Ergómetro de Esquí (SkiErg)', 'ski-ergometer.gif', 'upper arms', '["Adjust the seat height and footrests to a comfortable position.", "Grasp the handles with an overhand grip, palms facing down.", "Sit up straight with your feet flat on the footrests.", "Extend your arms straight out in front of you, keeping your elbows slightly bent.", "Engage your triceps and push the handles down towards your thighs.", "Pause for a moment at the bottom, then slowly return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento y los apoyapiés a una posición cómoda.", "Sujeta las agarraderas con un agarre prono, con las palmas hacia abajo.", "Siéntate erguido con los pies planos sobre los apoyapiés.", "Extiende los brazos rectos frente a ti, manteniendo los codos ligeramente flexionados.", "Activa los tríceps y empuja las asas hacia abajo, hacia los muslos.", "Haz una pausa por un momento en la parte inferior, luego regresa lentamente a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Estiramiento de Tríceps', 'triceps-stretch.gif', 'upper arms', '["Stand or sit upright with your back straight.", "Extend one arm overhead, bending it at the elbow.", "Place your opposite hand on the bent elbow and gently pull it towards your head.", "Hold the stretch for 15-30 seconds, feeling a gentle stretch in your triceps.", "Release the stretch and repeat on the other arm."]', '["Ponte de pie o siéntate erguido con la espalda recta.", "Extiende un brazo por encima de la cabeza, flexionándolo por el codo.", "Coloca la mano opuesta sobre el codo flexionado y tira de él suavemente hacia tu cabeza.", "Mantén el estiramiento de 15 a 30 segundos, sintiendo un estiramiento suave en el tríceps.", "Suelta el estiramiento y repite con el otro brazo."]'),
  ('Estiramiento de Tríceps por Encima de la Cabeza', 'overhead-triceps-stretch.gif', 'upper arms', '["Stand or sit upright with your feet shoulder-width apart.", "Extend one arm overhead, bending at the elbow so that your hand reaches towards the opposite shoulder blade.", "With your other hand, gently pull the elbow of the extended arm towards the opposite side of your head, feeling a stretch in your triceps.", "Hold the stretch for 15-30 seconds, then release.", "Repeat on the other side."]', '["Ponte de pie o siéntate erguido con los pies separados a la altura de los hombros.", "Extiende un brazo por encima de la cabeza, flexionando el codo de modo que la mano llegue hacia la escápula opuesta.", "Con la otra mano, tira suavemente del codo del brazo extendido hacia el lado opuesto de la cabeza, sintiendo un estiramiento en el tríceps.", "Mantén el estiramiento durante 15-30 segundos, luego suelta.", "Repite del otro lado."]'),
  ('Estiramiento de Tríceps Sentado sobre Fitball', 'exercise-ball-seated-triceps-stretch.gif', 'upper arms', '["Sit on a stability ball with your feet flat on the ground and your back straight.", "Hold a dumbbell in one hand and extend your arm straight up above your head.", "Bend your elbow and lower the dumbbell behind your head, keeping your upper arm close to your ear.", "Hold the stretch for a few seconds, then return to the starting position.", "Repeat with the other arm."]', '["Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y la espalda recta.", "Sostén una mancuerna con una mano y extiende el brazo recto por encima de la cabeza.", "Dobla el codo y baja la mancuerna detrás de la cabeza, manteniendo el brazo cerca de la oreja.", "Mantén el estiramiento durante unos segundos, luego regresa a la posición inicial.", "Repite con el otro brazo."]'),
  ('Extensión de Tríceps a 1 Brazo Inclinado de Pie', 'dumbbell-standing-bent-over-one-arm-triceps-extension.gif', 'upper arms', '["Stand with your feet shoulder-width apart and hold a dumbbell in one hand.", "Bend forward at the waist, keeping your back straight and parallel to the ground.", "Extend your arm straight back, keeping your elbow close to your body.", "Slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta una mancuerna con una mano.", "Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y paralela al suelo.", "Extiende el brazo recto hacia atrás, manteniendo el codo cerca de tu cuerpo.", "Baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Extensión de Tríceps a 1 Brazo Sentado en Banco', 'dumbbell-one-arm-triceps-extension-on-bench.gif', 'upper arms', '["Sit on a bench with your back straight and feet flat on the ground.", "Hold a dumbbell in one hand and place your other hand on the bench for support.", "Raise the dumbbell overhead, keeping your upper arm close to your head and your elbow pointing forward.", "Lower the dumbbell behind your head by bending your elbow, keeping your upper arm stationary.", "Extend your arm back up to the starting position, fully straightening your elbow.", "Repeat for the desired number of repetitions, then switch arms."]', '["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.", "Sostén una mancuerna en una mano y coloca la otra mano sobre el banco para apoyarte.", "Levanta la mancuerna por encima de la cabeza, manteniendo el brazo superior cerca de la cabeza y el codo apuntando hacia adelante.", "Baja la mancuerna detrás de la cabeza flexionando el codo, manteniendo el brazo superior quieto.", "Extiende el brazo de vuelta a la posición inicial, estirando completamente el codo.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Extensión de Tríceps a 2 Brazos en Banco Inclinado', 'dumbbell-incline-two-arm-extension.gif', 'upper arms', '["Sit on an incline bench with a dumbbell in each hand, resting on your thighs.", "Slowly lie back on the bench, keeping the dumbbells close to your chest.", "Once you are fully lying down, extend your arms straight up towards the ceiling, keeping your elbows slightly bent.", "Pause for a moment at the top, then slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco inclinado con una mancuerna en cada mano, apoyadas sobre los muslos.", "Recuéstate lentamente en el banco, manteniendo las mancuernas cerca del pecho.", "Una vez completamente recostado, extiende los brazos rectos hacia el techo, manteniendo los codos ligeramente flexionados.", "Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión de Tríceps Alterna en Polea', 'cable-alternate-triceps-extension.gif', 'upper arms', '["Stand facing the cable machine with your feet shoulder-width apart.", "Hold the cable handle with your right hand and bring your arm up so that your upper arm is parallel to the ground and your elbow is bent at a 90-degree angle.", "Keep your upper arm stationary and extend your forearm backward, fully straightening your arm.", "Pause for a moment, then slowly return to the starting position.", "Repeat with your left arm.", "Continue alternating arms for the desired number of repetitions."]', '["Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.", "Sujeta la agarradera del cable con la mano derecha y levanta el brazo de modo que el brazo superior quede paralelo al suelo y el codo flexionado en un ángulo de 90 grados.", "Mantén el brazo superior quieto y extiende el antebrazo hacia atrás, estirando completamente el brazo.", "Haz una pausa por un momento, luego regresa lentamente a la posición inicial.", "Repite con el brazo izquierdo.", "Continúa alternando los brazos durante el número de repeticiones deseado."]'),
  ('Extensión de Tríceps Alterna Tumbado con Mancuernas', 'dumbbell-lying-alternate-extension.gif', 'upper arms', '["Lie flat on a bench with a dumbbell in each hand, palms facing each other.", "Extend your arms straight up over your chest, keeping a slight bend in your elbows.", "Lower one dumbbell down towards your head, bending at the elbow, while keeping the other arm extended.", "Pause for a moment at the bottom, then raise the dumbbell back up to the starting position.", "Repeat with the other arm, alternating sides for the desired number of repetitions."]', '["Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí.", "Extiende los brazos rectos hacia arriba sobre el pecho, con una ligera flexión en los codos.", "Baja una mancuerna hacia la cabeza, flexionando el codo, mientras mantienes el otro brazo extendido.", "Haz una pausa breve en la parte baja, luego levanta la mancuerna de vuelta a la posición inicial.", "Repite con el otro brazo, alternando lados el número de repeticiones deseado."]'),
  ('Extensión de Tríceps Boca Arriba sobre Fitball', 'exercise-ball-supine-triceps-extension.gif', 'upper arms', '["Sit on an exercise ball with your feet flat on the ground and your knees bent at a 90-degree angle.", "Hold a dumbbell with both hands and extend your arms straight up towards the ceiling.", "Slowly lower the dumbbell behind your head, keeping your elbows close to your ears.", "Pause for a moment, then raise the dumbbell back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate sobre un balón de estabilidad con los pies apoyados en el suelo y las rodillas flexionadas en un ángulo de 90 grados.", "Sostén una mancuerna con ambas manos y extiende los brazos rectos hacia el techo.", "Baja lentamente la mancuerna detrás de la cabeza, manteniendo los codos cerca de las orejas.", "Haz una pausa por un momento, luego sube la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión de Tríceps con Barra Olímpica', 'olympic-barbell-triceps-extension.gif', 'upper arms', '["Start by standing with your feet shoulder-width apart and holding the barbell with an overhand grip.", "Raise the barbell above your head, fully extending your arms.", "Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.", "Pause for a moment, then extend your arms back to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza de pie con los pies separados a la altura de los hombros y sosteniendo la barra con un agarre prono.", "Levanta la barra por encima de la cabeza, extendiendo completamente los brazos.", "Manteniendo los brazos superiores cerca de la cabeza, baja lentamente la barra detrás de la cabeza flexionando los codos.", "Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión de Tríceps con Barra Z en Banco Declinado', 'ez-barbell-decline-triceps-extension.gif', 'upper arms', '["Lie on a decline bench with your head lower than your feet and your feet secured.", "Hold the ez barbell with an overhand grip, hands shoulder-width apart.", "Extend your arms fully, keeping your elbows close to your head.", "Lower the barbell slowly towards your forehead, bending your elbows.", "Pause for a moment, then extend your arms back to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate en un banco declinado con la cabeza más baja que los pies y los pies asegurados.", "Sostén la barra EZ con agarre prono, manos separadas a la altura de los hombros.", "Extiende completamente los brazos, manteniendo los codos cerca de la cabeza.", "Baja la barra lentamente hacia la frente, doblando los codos.", "Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión de Tríceps con Mancuernas en Banco Inclinado', 'dumbbell-incline-triceps-extension.gif', 'upper arms', '["Sit on an incline bench with a dumbbell in each hand, palms facing inwards.", "Extend your arms fully overhead, keeping your elbows close to your head.", "Lower the dumbbells behind your head by bending your elbows, keeping your upper arms stationary.", "Pause for a moment, then raise the dumbbells back to the starting position by extending your arms.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco inclinado con una mancuerna en cada mano, con las palmas hacia adentro.", "Extiende completamente los brazos por encima de la cabeza, manteniendo los codos cerca de la cabeza.", "Baja las mancuernas detrás de la cabeza flexionando los codos, manteniendo los brazos superiores quietos.", "Haz una pausa por un momento, luego levanta las mancuernas de vuelta a la posición inicial extendiendo los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Extensión de Tríceps con Peso Corporal en Barra Smith', 'triceps-press.gif', 'upper arms', '["Hold a Smith bar at chest height and walk your feet back until you lean with your body straight.", "Bend your elbows and bring your forehead below the bar without moving your upper arms.", "Extend your elbows to return to the starting position.", "Keep your core tight and your body in a straight line.", "Repeat for the desired number of repetitions."]', '["Sujeta una barra Smith a la altura del pecho y retrocede los pies hasta quedar inclinado con el cuerpo recto.", "Flexiona los codos y lleva la frente por debajo de la barra, sin mover la parte superior de los brazos.", "Extiende los codos para volver a la posición inicial.", "Mantén el core activo y el cuerpo en línea recta.", "Repite el número de repeticiones deseado."]'),
  ('Extensión de Tríceps Concentrada en Polea (sobre la Rodilla)', 'cable-concentration-extension-on-knee.gif', 'upper arms', '["Sit on a bench or chair with your knees bent and feet flat on the ground.", "Hold the cable handle with your right hand and place your elbow on the inside of your right knee.", "Extend your arm fully, keeping your elbow stationary and close to your knee.", "Pause for a moment at the top, then slowly lower your arm back to the starting position.", "Repeat for the desired number of repetitions, then switch sides."]', '["Siéntate en un banco o silla con las rodillas flexionadas y los pies planos en el suelo.", "Sujeta la agarradera del cable con la mano derecha y coloca el codo en la parte interna de la rodilla derecha.", "Extiende completamente el brazo, manteniendo el codo quieto y cerca de la rodilla.", "Haz una pausa breve en la parte más alta, luego baja lentamente el brazo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Extensión de Tríceps de Pie Asistida con Toalla', 'assisted-standing-triceps-extension-with-towel.gif', 'upper arms', '["Stand with your feet shoulder-width apart and hold a towel with both hands behind your head.", "Keep your elbows close to your ears and your upper arms stationary.", "Slowly extend your forearms upward, squeezing your triceps at the top.", "Pause for a moment, then slowly lower the towel back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sostén una toalla con ambas manos detrás de la cabeza.", "Mantén los codos cerca de las orejas y la parte superior de los brazos quieta.", "Extiende lentamente los antebrazos hacia arriba, apretando los tríceps en la parte superior.", "Haz una pausa por un momento, luego baja lentamente la toalla de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión de Tríceps de Rodillas con Peso Corporal', 'bodyweight-kneeling-triceps-extension.gif', 'upper arms', '["Kneel down on the ground with your knees hip-width apart.", "Place your hands on the ground in front of you, shoulder-width apart, fingers pointing forward.", "Extend your legs straight behind you, balancing on your toes and hands, forming a straight line from head to heels.", "Bend your elbows and lower your upper body towards the ground, keeping your elbows close to your sides.", "Pause for a moment at the bottom, then push through your hands to straighten your arms and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de rodillas en el suelo con las rodillas separadas a la altura de las caderas.", "Coloca las manos en el suelo frente a ti, separadas a la altura de los hombros, con los dedos apuntando hacia adelante.", "Extiende las piernas rectas detrás de ti, equilibrándote sobre las puntas de los pies y las manos, formando una línea recta desde la cabeza hasta los talones.", "Flexiona los codos y baja la parte superior del cuerpo hacia el suelo, manteniendo los codos cerca del cuerpo.", "Haz una pausa breve en la posición más baja, luego empuja con las manos para extender los brazos y volver a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión de Tríceps de Rodillas en Polea', 'cable-kneeling-triceps-extension.gif', 'upper arms', '["Attach a rope handle to a high pulley and kneel down facing the cable machine.", "Grasp the rope with a neutral grip (palms facing each other) and bring your hands to the sides of your head.", "Keep your elbows close to your head and your upper arms stationary throughout the exercise.", "Extend your forearms by contracting your triceps until your arms are fully extended.", "Pause for a moment, then slowly return to the starting position by bending your elbows.", "Repeat for the desired number of repetitions."]', '["Sujeta una agarradera de cuerda a una polea alta y ponte de rodillas frente a la máquina de cable.", "Sujeta la cuerda con un agarre neutro (las palmas una frente a la otra) y lleva las manos a los lados de la cabeza.", "Mantén los codos cerca de la cabeza y la parte superior de los brazos inmóvil durante todo el ejercicio.", "Extiende los antebrazos contrayendo los tríceps hasta que los brazos queden completamente extendidos.", "Haz una pausa por un momento y luego vuelve lentamente a la posición inicial flexionando los codos.", "Repite el número de repeticiones deseado."]'),
  ('Extensión de Tríceps en Banco Inclinado en Máquina Smith', 'smith-machine-incline-tricep-extension.gif', 'upper arms', '["Adjust the seat of the smith machine so that the bar is at shoulder height.", "Sit on the bench with your back against the pad and your feet flat on the ground.", "Grasp the bar with an overhand grip, slightly wider than shoulder-width apart.", "Extend your arms fully, lifting the bar off the rack and holding it directly above your chest.", "Lower the bar slowly towards your forehead, keeping your elbows close to your head.", "Pause for a moment at the bottom, then push the bar back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta el asiento de la máquina Smith de modo que la barra quede a la altura de los hombros.", "Siéntate en el banco con la espalda apoyada en el respaldo y los pies planos sobre el suelo.", "Sujeta la barra con agarre prono, un poco más separado que el ancho de los hombros.", "Extiende los brazos por completo, levantando la barra del soporte y sosteniéndola directamente sobre el pecho.", "Baja la barra lentamente hacia la frente, manteniendo los codos cerca de la cabeza.", "Haz una pausa por un momento en la posición baja, luego empuja la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión de Tríceps en Polea con Cuerda en Banco Inclinado', 'cable-rope-incline-tricep-extension.gif', 'upper arms', '["Attach a rope to a high pulley and adjust the incline bench to a comfortable angle.", "Stand facing away from the pulley with your feet shoulder-width apart.", "Grasp the rope with an overhand grip and extend your arms straight overhead.", "Keep your elbows close to your head and your upper arms stationary throughout the exercise.", "Lower the rope behind your head by bending your elbows until your forearms touch your biceps.", "Pause for a moment, then extend your arms back to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta una cuerda a una polea alta y ajusta el banco inclinado a un ángulo cómodo.", "Ponte de pie de espaldas a la polea con los pies separados a la altura de los hombros.", "Sujeta la cuerda con un agarre prono y extiende los brazos rectos por encima de la cabeza.", "Mantén los codos cerca de la cabeza y la parte superior de los brazos inmóvil durante todo el ejercicio.", "Baja la cuerda detrás de la cabeza flexionando los codos hasta que los antebrazos toquen los bíceps.", "Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión de Tríceps en Polea en Banco Inclinado', 'cable-incline-triceps-extension.gif', 'upper arms', '["Adjust the cable machine to a low pulley position.", "Attach a straight bar to the cable.", "Stand facing away from the machine with your feet shoulder-width apart.", "Grasp the bar with an overhand grip and extend your arms straight overhead.", "Lean forward slightly, keeping your back straight and core engaged.", "Bend your elbows and lower the bar behind your head, keeping your upper arms close to your ears.", "Pause for a moment, then extend your arms back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la máquina de cable a una posición de polea baja.", "Sujeta una barra recta al cable.", "Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.", "Sujeta la barra con un agarre prono y extiende los brazos rectos por encima de la cabeza.", "Inclínate ligeramente hacia adelante, manteniendo la espalda recta y el core activado.", "Flexiona los codos y baja la barra detrás de la cabeza, manteniendo la parte superior de los brazos cerca de las orejas.", "Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión de Tríceps por Encima de la Cabeza a 1 Brazo de Pie', 'dumbbell-standing-one-arm-extension.gif', 'upper arms', '["Stand with your feet shoulder-width apart, holding a dumbbell in one hand.", "Raise the dumbbell overhead, fully extending your arm.", "Keep your upper arm close to your head and perpendicular to the ground.", "Slowly lower the dumbbell behind your head, bending your elbow.", "Pause for a moment, then raise the dumbbell back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna con una mano.", "Levanta la mancuerna por encima de la cabeza, extendiendo completamente el brazo.", "Mantén la parte superior del brazo cerca de la cabeza y perpendicular al suelo.", "Baja lentamente la mancuerna detrás de la cabeza, flexionando el codo.", "Haz una pausa por un momento, luego levanta la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión de Tríceps por Encima de la Cabeza a 1 Brazo en Polea con Agarre Supino', 'cable-standing-reverse-grip-one-arm-overhead-tricep-extension.gif', 'upper arms', '["Stand facing away from the cable machine with your feet shoulder-width apart.", "Hold the cable handle with an underhand grip and extend your arm overhead, keeping your elbow close to your head.", "Keep your upper arm stationary and slowly lower the cable handle behind your head by bending your elbow.", "Pause for a moment at the bottom, then extend your arm back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Ponte de pie de espaldas a la máquina de cable con los pies separados a la altura de los hombros.", "Sujeta el mango del cable con un agarre supino y extiende el brazo por encima de la cabeza, manteniendo el codo cerca de la cabeza.", "Mantén el brazo superior quieto y baja lentamente el mango del cable detrás de la cabeza flexionando el codo.", "Haz una pausa breve en la parte baja, luego extiende el brazo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Extensión de Tríceps por Encima de la Cabeza a 1 Brazo Sentado con Agarre Supino', 'dumbbell-seated-reverse-grip-one-arm-overhead-tricep-extension.gif', 'upper arms', '["Sit on a bench with your back straight and feet flat on the ground.", "Hold a dumbbell with an underhand grip and extend your arm straight up overhead.", "Lower the dumbbell behind your head by bending your elbow, keeping your upper arm stationary.", "Pause for a moment, then extend your arm back up to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.", "Sujeta una mancuerna con agarre supino y extiende el brazo recto por encima de la cabeza.", "Baja la mancuerna detrás de la cabeza flexionando el codo, manteniendo el brazo superior quieto.", "Haz una pausa por un momento, luego extiende el brazo de vuelta hacia arriba, hasta la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Extensión de Tríceps por Encima de la Cabeza de Pie con Barra', 'barbell-standing-overhead-triceps-extension.gif', 'upper arms', '["Stand with your feet shoulder-width apart and hold a barbell with an overhand grip.", "Raise the barbell overhead, fully extending your arms.", "Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.", "Pause for a moment, then raise the barbell back to the starting position by extending your arms.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sujeta una barra con agarre prono.", "Levanta la barra por encima de la cabeza, extendiendo completamente los brazos.", "Manteniendo los brazos superiores cerca de la cabeza, baja lentamente la barra detrás de la cabeza flexionando los codos.", "Haz una pausa breve, luego levanta la barra de vuelta a la posición inicial extendiendo los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Extensión de Tríceps por Encima de la Cabeza en Polea Alta', 'cable-high-pulley-overhead-tricep-extension.gif', 'upper arms', '["Attach a rope to a high pulley and stand facing away from the machine.", "Grasp the rope with both hands and extend your arms overhead.", "Keep your elbows close to your head and your upper arms stationary.", "Slowly lower the rope behind your head by bending your elbows.", "Pause for a moment, then extend your arms back to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca una cuerda en una polea alta y ponte de pie de espaldas a la máquina.", "Sujeta la cuerda con ambas manos y extiende los brazos por encima de la cabeza.", "Mantén los codos cerca de la cabeza y la parte superior de los brazos inmóvil.", "Baja lentamente la cuerda detrás de la cabeza flexionando los codos.", "Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión de Tríceps por Encima de la Cabeza en Polea Alta con Cuerda', 'cable-rope-high-pulley-overhead-tricep-extension.gif', 'upper arms', '["Attach a rope to a high pulley and adjust the weight accordingly.", "Stand facing away from the pulley machine with your feet shoulder-width apart.", "Grasp the rope with both hands, palms facing down, and bring your hands above your head.", "Keep your upper arms close to your head and perpendicular to the floor.", "Slowly lower the rope behind your head by bending your elbows.", "Pause for a moment, then extend your arms back to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta una cuerda a una polea alta y ajusta el peso según corresponda.", "Ponte de pie de espaldas a la máquina de poleas con los pies separados a la altura de los hombros.", "Sujeta la cuerda con ambas manos, con las palmas hacia abajo, y lleva las manos por encima de la cabeza.", "Mantén la parte superior de los brazos cerca de la cabeza y perpendicular al suelo.", "Baja lentamente la cuerda detrás de la cabeza flexionando los codos.", "Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión de Tríceps por Encima de la Cabeza en Polea con Cuerda', 'cable-overhead-triceps-extension-rope-attachment.gif', 'upper arms', '["Attach a rope to a cable machine at a high position.", "Stand facing away from the machine with your feet shoulder-width apart.", "Grasp the rope with both hands, palms facing each other, and bring your hands above your head.", "Keep your upper arms close to your head and your elbows pointing forward.", "Slowly lower the rope behind your head by bending your elbows.", "Pause for a moment, then extend your arms back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta una cuerda a una máquina de cable en una posición alta.", "Ponte de pie de espaldas a la máquina con los pies separados a la altura de los hombros.", "Sujeta la cuerda con ambas manos, con las palmas una frente a la otra, y lleva las manos por encima de la cabeza.", "Mantén la parte superior de los brazos cerca de la cabeza y los codos apuntando hacia adelante.", "Baja lentamente la cuerda detrás de la cabeza flexionando los codos.", "Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión de Tríceps por Encima de la Cabeza Sentado con Barra', 'barbell-seated-overhead-triceps-extension.gif', 'upper arms', '["Sit on a bench with your back straight and feet flat on the ground.", "Hold a barbell with an overhand grip, hands shoulder-width apart, and raise it overhead.", "Lower the barbell behind your head by bending your elbows, keeping your upper arms close to your head.", "Pause for a moment, then extend your arms to raise the barbell back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.", "Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y levántala por encima de la cabeza.", "Baja la barra detrás de la cabeza flexionando los codos, manteniendo los brazos superiores cerca de la cabeza.", "Haz una pausa breve y luego extiende los brazos para levantar la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión de Tríceps Sentado con 2 Mancuernas', 'dumbbells-seated-triceps-extension.gif', 'upper arms', '["Sit on a bench with your back straight and feet flat on the ground.", "Hold a dumbbell in both hands with an overhand grip, and raise it above your head.", "Bend your elbows and lower the dumbbell behind your head, keeping your upper arms close to your ears.", "Extend your arms and raise the dumbbell back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.", "Sujeta una mancuerna con ambas manos con agarre prono y levántala por encima de la cabeza.", "Flexiona los codos y baja la mancuerna detrás de la cabeza, manteniendo la parte superior de los brazos cerca de las orejas.", "Extiende los brazos y sube la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión de Tríceps Sentado con Barra Z', 'ez-barbell-seated-triceps-extension.gif', 'upper arms', '["Sit on a bench with your back straight and feet flat on the ground.", "Hold the ez barbell with an overhand grip, hands shoulder-width apart.", "Raise the barbell overhead, fully extending your arms.", "Keeping your upper arms stationary, lower the barbell behind your head by bending your elbows.", "Pause for a moment, then raise the barbell back to the starting position by extending your arms.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.", "Sostén la barra EZ con agarre prono, manos separadas a la altura de los hombros.", "Levanta la barra por encima de la cabeza, extendiendo completamente los brazos.", "Manteniendo los brazos superiores inmóviles, baja la barra detrás de la cabeza doblando los codos.", "Haz una pausa breve, luego levanta la barra de vuelta a la posición inicial extendiendo los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Extensión de Tríceps Sentado con Mancuerna', 'dumbbell-seated-triceps-extension.gif', 'upper arms', '["Sit on a bench with your back straight and feet flat on the ground.", "Hold a dumbbell with both hands and extend your arms straight up overhead.", "Bend your elbows and lower the dumbbell behind your head, keeping your upper arms close to your ears.", "Pause for a moment, then straighten your arms and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.", "Sujeta una mancuerna con ambas manos y extiende los brazos rectos por encima de la cabeza.", "Flexiona los codos y baja la mancuerna detrás de la cabeza, manteniendo la parte superior de los brazos cerca de las orejas.", "Haz una pausa por un momento, luego endereza los brazos y vuelve a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión de Tríceps Tras la Cabeza Tumbado con Barra', 'barbell-lying-back-of-the-head-tricep-extension.gif', 'upper arms', '["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.", "Hold a barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.", "Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows.", "Pause for a moment, then extend your arms back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.", "Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho.", "Manteniendo los brazos superiores fijos, baja lentamente la barra detrás de la cabeza flexionando los codos.", "Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión de Tríceps Tras la Cabeza Tumbado con Barra Z y Agarre Cerrado', 'ez-bar-lying-close-grip-triceps-extension-behind-head.gif', 'upper arms', '["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.", "Hold the ez barbell with a close grip, palms facing up, and extend your arms straight up over your chest.", "Keeping your upper arms stationary, slowly lower the barbell behind your head by bending your elbows.", "Pause for a moment, then extend your arms back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.", "Sostén la barra EZ con agarre cerrado, palmas hacia arriba, y extiende los brazos rectos por encima del pecho.", "Manteniendo los brazos superiores fijos, baja lentamente la barra detrás de la cabeza flexionando los codos.", "Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión de Tríceps Tras Nuca Sentado con Barra y Agarre Cerrado', 'barbell-seated-close-grip-behind-neck-triceps-extension.gif', 'upper arms', '["Sit on a bench with your back straight and feet flat on the ground.", "Hold the barbell with a close grip behind your neck, palms facing forward.", "Keep your elbows close to your head and slowly lower the barbell towards the back of your head.", "Pause for a moment, then extend your arms back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con la espalda recta y los pies planos sobre el suelo.", "Sujeta la barra con un agarre cerrado detrás del cuello, con las palmas mirando hacia delante.", "Mantén los codos cerca de la cabeza y baja lentamente la barra hacia la parte de atrás de la cabeza.", "Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión de Tríceps Tumbado a 1 Brazo', 'dumbbell-lying-single-extension.gif', 'upper arms', '["Lie flat on a bench with a dumbbell in one hand and your arm fully extended above your chest.", "Lower the dumbbell in a controlled manner towards your forehead, keeping your upper arm stationary.", "Pause briefly at the bottom of the movement, then extend your arm back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Túmbate boca arriba en un banco con una mancuerna en una mano y el brazo completamente extendido por encima del pecho.", "Baja la mancuerna de manera controlada hacia la frente, manteniendo el brazo superior quieto.", "Haz una breve pausa en la parte inferior del movimiento, luego extiende el brazo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Extensión de Tríceps Tumbado a 1 Brazo con Agarre Prono', 'dumbbell-lying-one-arm-pronated-triceps-extension.gif', 'upper arms', '["Lie flat on a bench with your back and head supported, and your feet flat on the ground.", "Hold a dumbbell in one hand with your palm facing down, and extend your arm straight up above your shoulder.", "Keeping your upper arm stationary, slowly lower the dumbbell behind your head by bending your elbow.", "Pause for a moment at the bottom, then extend your arm back up to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Túmbate boca arriba en un banco con la espalda y la cabeza apoyadas, y los pies planos sobre el suelo.", "Sostén una mancuerna en una mano con la palma hacia abajo, y extiende el brazo recto por encima del hombro.", "Manteniendo el brazo superior quieto, baja lentamente la mancuerna detrás de la cabeza flexionando el codo.", "Haz una pausa por un momento en la parte inferior, luego extiende el brazo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Extensión de Tríceps Tumbado a 1 Brazo con Agarre Supino', 'dumbbell-lying-one-arm-supinated-triceps-extension.gif', 'upper arms', '["Lie flat on a bench with your back and head supported, and your feet flat on the ground.", "Hold a dumbbell in one hand with an underhand grip, and extend your arm straight up above your shoulder.", "Keeping your upper arm stationary, slowly lower the dumbbell behind your head by bending your elbow.", "Pause for a moment at the bottom, then extend your arm back up to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Túmbate boca arriba en un banco con la espalda y la cabeza apoyadas, y los pies planos sobre el suelo.", "Sostén una mancuerna en una mano con agarre supino, y extiende el brazo recto por encima del hombro.", "Manteniendo el brazo superior quieto, baja lentamente la mancuerna detrás de la cabeza flexionando el codo.", "Haz una pausa por un momento en la parte inferior, luego extiende el brazo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Extensión de Tríceps Tumbado con Agarre Prono', 'dumbbell-pronate-grip-triceps-extension.gif', 'upper arms', '["Sit on a bench or chair with your back straight and feet flat on the ground.", "Hold a dumbbell with both hands, palms facing down, and extend your arms straight up overhead.", "Keeping your upper arms close to your head and elbows pointing forward, slowly lower the dumbbell behind your head by bending your elbows.", "Pause for a moment, then extend your arms back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco o silla con la espalda recta y los pies apoyados en el suelo.", "Sujeta una mancuerna con ambas manos, con las palmas hacia abajo, y extiende los brazos rectos por encima de la cabeza.", "Manteniendo la parte superior de los brazos cerca de la cabeza y los codos apuntando hacia adelante, baja lentamente la mancuerna detrás de la cabeza flexionando los codos.", "Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión de Tríceps Tumbado con Barra', 'barbell-lying-triceps-extension.gif', 'upper arms', '["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.", "Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.", "Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.", "Pause for a moment at the bottom, then extend your arms back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.", "Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho.", "Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos.", "Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión de Tríceps Tumbado con Barra en Rack', 'barbell-lying-extension.gif', 'upper arms', '["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.", "Hold the barbell with an overhand grip, hands shoulder-width apart, and extend your arms straight up over your chest.", "Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.", "Pause for a moment, then extend your arms back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.", "Sujeta una barra con un agarre pronado, manos separadas a la altura de los hombros, y extiende los brazos rectos por encima del pecho.", "Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos.", "Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión de Tríceps Tumbado con Barra y Agarre Cerrado', 'barbell-lying-close-grip-triceps-extension.gif', 'upper arms', '["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.", "Grasp the barbell with a close grip, hands shoulder-width apart, palms facing up.", "Extend your arms fully, lifting the barbell above your chest.", "Keeping your upper arms stationary, slowly lower the barbell towards your forehead by bending your elbows.", "Pause for a moment at the bottom, then extend your arms back to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.", "Agarra la barra con un agarre cerrado, manos separadas a la altura de los hombros, con las palmas hacia arriba.", "Extiende completamente los brazos, levantando la barra por encima del pecho.", "Manteniendo los brazos superiores fijos, baja lentamente la barra hacia la frente flexionando los codos.", "Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión de Tríceps Tumbado con Mancuernas', 'dumbbell-lying-triceps-extension.gif', 'upper arms', '["Lie flat on a bench with a dumbbell in each hand, palms facing each other.", "Extend your arms straight up over your chest, keeping your elbows close to your body.", "Lower the dumbbells down towards your forehead, bending your elbows.", "Pause for a moment, then extend your arms back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí.", "Extiende los brazos rectos hacia arriba sobre el pecho, manteniendo los codos cerca del cuerpo.", "Baja las mancuernas hacia la frente, flexionando los codos.", "Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión de Tríceps Tumbado Cruzando la Cara', 'dumbbell-lying-extension-across-face.gif', 'upper arms', '["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.", "Hold a dumbbell with both hands and extend your arms straight up above your chest, palms facing each other.", "Keeping your upper arms stationary, slowly lower the dumbbell in an arc behind your head until your forearms are parallel to the ground.", "Pause for a moment, then contract your triceps to bring the dumbbell back to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.", "Sostén una mancuerna con ambas manos y extiende los brazos rectos hacia arriba sobre el pecho, con las palmas enfrentadas entre sí.", "Manteniendo los brazos superiores quietos, baja lentamente la mancuerna describiendo un arco detrás de la cabeza hasta que los antebrazos queden paralelos al suelo.", "Haz una pausa por un momento, luego contrae los tríceps para llevar la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión de Tríceps Tumbado en el Suelo en Polea con Cuerda', 'cable-rope-lying-on-floor-tricep-extension.gif', 'upper arms', '["Attach a rope to a cable machine and set it to the lowest position.", "Lie on the floor facing up, with your head towards the cable machine.", "Hold the rope with both hands, palms facing each other, and extend your arms straight up towards the ceiling.", "Keep your upper arms stationary and slowly lower the rope towards your forehead, bending your elbows.", "Pause for a moment, then extend your arms back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta una cuerda a una máquina de cable y colócala en la posición más baja.", "Túmbate en el suelo boca arriba, con la cabeza orientada hacia la máquina de cable.", "Sujeta la cuerda con ambas manos, con las palmas una frente a la otra, y extiende los brazos rectos hacia el techo.", "Mantén la parte superior de los brazos inmóvil y baja lentamente la cuerda hacia la frente, flexionando los codos.", "Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Extensión de Tríceps Tumbado en Polea', 'cable-lying-triceps-extension-v-2.gif', 'upper arms', '["Attach a rope handle to a low pulley cable machine.", "Lie down on a flat bench facing up, with your head towards the cable machine.", "Grasp the rope handle with both hands, palms facing each other, and extend your arms straight up over your chest.", "Keeping your upper arms stationary, slowly lower the rope handle towards your forehead by bending your elbows.", "Pause for a moment at the bottom, then extend your arms back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta una agarradera de cuerda a una máquina de cable con polea baja.", "Túmbate boca arriba en un banco plano con la cabeza orientada hacia la máquina de cable.", "Sujeta la agarradera de cuerda con ambas manos, con las palmas una frente a la otra, y extiende los brazos rectos por encima del pecho.", "Manteniendo la parte superior de los brazos inmóvil, baja lentamente la agarradera de cuerda hacia la frente flexionando los codos.", "Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Flexión Cerrada sobre Balón Medicinal', 'medicine-ball-close-grip-push-up.gif', 'upper arms', '["Start in a high plank position with your hands on the medicine ball, shoulder-width apart.", "Lower your body towards the ground by bending your elbows, keeping them close to your sides.", "Push back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Comienza en una posición de plancha alta con las manos sobre el balón medicinal, separadas a la altura de los hombros.", "Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.", "Empuja de vuelta hasta la posición inicial, extendiendo completamente los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Flexión Cerrada sobre Fitball', 'narrow-push-up-on-exercise-ball.gif', 'upper arms', '["Place the stability ball on the ground and position yourself in a push-up position with your hands on the ball, slightly narrower than shoulder-width apart.", "Engage your core and keep your body in a straight line from head to toe.", "Lower your chest towards the ball by bending your elbows, keeping them close to your body.", "Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."]', '["Coloca el balón de estabilidad en el suelo y ponte en posición de flexión con las manos sobre el balón, un poco más juntas que la anchura de los hombros.", "Activa el core y mantén el cuerpo en línea recta de la cabeza a los pies.", "Baja el pecho hacia el balón flexionando los codos, manteniéndolos cerca del cuerpo.", "Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Flexión Cerrada sobre Mancuernas', 'push-up-close-grip-off-dumbbell.gif', 'upper arms', '["Start in a push-up position with your hands placed close together, directly under your shoulders.", "Hold a dumbbell in each hand, resting them on the ground.", "Lower your body towards the ground by bending your elbows, keeping them close to your sides.", "Push through your palms to extend your arms and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza en posición de flexión con las manos juntas, directamente debajo de los hombros.", "Sostén una mancuerna en cada mano, apoyándolas en el suelo.", "Baja el cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.", "Empuja con las palmas para extender los brazos y regresar a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Flexión con Agarre Cerrado', 'close-grip-push-up.gif', 'upper arms', '["Start in a high plank position with your hands placed close together, directly under your shoulders.", "Engage your core and lower your body towards the ground, keeping your elbows close to your sides.", "Push through your palms to extend your arms and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza en posición de plancha alta con las manos juntas, directamente debajo de los hombros.", "Activa el core y baja el cuerpo hacia el suelo, manteniendo los codos cerca de los costados.", "Empuja con las palmas para extender los brazos y regresar a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Flexión con Agarre Cerrado con Banda Elástica', 'band-close-grip-push-up.gif', 'upper arms', '["Place a band around your upper arms, just above the elbows.", "Assume a push-up position with your hands directly under your shoulders and your body in a straight line from head to heels.", "Bend your elbows and lower your chest towards the ground, keeping your elbows close to your sides.", "Push through your palms to extend your arms and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Coloca una banda alrededor de la parte superior de los brazos, justo por encima de los codos.", "Adopta una posición de flexión de brazos con las manos justo debajo de los hombros y el cuerpo en línea recta desde la cabeza hasta los talones.", "Flexiona los codos y baja el pecho hacia el suelo, manteniendo los codos cerca de los costados.", "Empuja con las palmas para extender los brazos y regresar a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Flexión de Rodillas con Agarre Cerrado', 'close-grip-push-up-on-knees.gif', 'upper arms', '["Start by getting on your hands and knees, with your hands shoulder-width apart and your knees hip-width apart.", "Lower your upper body towards the ground by bending your elbows, keeping them close to your sides.", "Pause for a moment when your chest is just above the ground.", "Push through your palms to straighten your arms and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza apoyándote sobre las manos y las rodillas, con las manos separadas a la altura de los hombros y las rodillas separadas a la altura de las caderas.", "Baja la parte superior del cuerpo hacia el suelo flexionando los codos, manteniéndolos cerca de los costados.", "Haz una pausa breve cuando tu pecho esté justo por encima del suelo.", "Empuja con las palmas para estirar los brazos y regresar a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Flexión Diamante', 'diamond-push-up.gif', 'upper arms', '["Start in a high plank position with your hands close together, forming a diamond shape with your thumbs and index fingers.", "Keep your body in a straight line from head to toe, engaging your core and glutes.", "Lower your chest towards the diamond shape formed by your hands, keeping your elbows close to your body.", "Pause for a moment at the bottom, then push yourself back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza en posición de plancha alta con las manos juntas, formando una figura de diamante con los pulgares y los índices.", "Mantén el cuerpo en línea recta de la cabeza a los pies, activando el core y los glúteos.", "Baja el pecho hacia la figura de diamante formada por tus manos, manteniendo los codos cerca del cuerpo.", "Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Flexión en Parada de Manos', 'handstand-push-up.gif', 'upper arms', '["Find a wall and face away from it, standing a few feet away.", "Place your hands on the ground shoulder-width apart and kick your feet up against the wall, coming into a handstand position.", "Bend your elbows and lower your head towards the ground, keeping your body in a straight line.", "Push through your hands and extend your arms to return to the starting position.", "Repeat for the desired number of repetitions."]', '["Busca una pared y colócate de espaldas a ella, de pie a unos pasos de distancia.", "Coloca las manos en el suelo separadas a la altura de los hombros y lanza los pies hacia la pared, llegando a una posición de pino.", "Dobla los codos y baja la cabeza hacia el suelo, manteniendo el cuerpo en línea recta.", "Empuja con las manos y extiende los brazos para volver a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Flexión Inclinada con Agarre Cerrado', 'incline-close-grip-push-up.gif', 'upper arms', '["Place your hands on an elevated surface, such as a bench or step, slightly wider than shoulder-width apart.", "Extend your legs behind you, resting on the balls of your feet, with your body forming a straight line from head to heels.", "Lower your chest towards the elevated surface by bending your elbows, keeping them close to your sides.", "Pause for a moment at the bottom, then push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."]', '["Coloca las manos sobre una superficie elevada, como un banco o un escalón, ligeramente más separadas que la altura de los hombros.", "Extiende las piernas detrás de ti, apoyándote en la punta de los pies, con el cuerpo formando una línea recta desde la cabeza hasta los talones.", "Baja el pecho hacia la superficie elevada doblando los codos, manteniéndolos cerca de los costados.", "Haz una pausa breve en la parte baja, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Flexión Lateral', 'side-push-up.gif', 'upper arms', '["Start by lying on your side with your legs extended and stacked on top of each other.", "Place your bottom hand on the ground directly under your shoulder, fingers pointing forward.", "Press through your bottom hand to lift your body off the ground, keeping your legs straight and your core engaged.", "Extend your top arm straight up towards the ceiling, creating a straight line from your head to your heels.", "Lower your body back down to the starting position with control.", "Repeat for the desired number of repetitions, then switch sides."]', '["Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra.", "Coloca la mano de abajo en el suelo directamente debajo del hombro, con los dedos apuntando hacia delante.", "Empuja con la mano de abajo para levantar el cuerpo del suelo, manteniendo las piernas rectas y el core activado.", "Extiende el brazo de arriba recto hacia el techo, formando una línea recta desde la cabeza hasta los talones.", "Baja el cuerpo de nuevo a la posición inicial con control.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Flexión sobre Antebrazos', 'push-up-on-lower-arms.gif', 'upper arms', '["Start in a plank position with your forearms on the ground and elbows directly below your shoulders.", "Engage your core and keep your body in a straight line from head to toe.", "Lower your chest towards the ground by bending your elbows, keeping them close to your body.", "Pause for a moment at the bottom, then push yourself back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza en posición de plancha con los antebrazos en el suelo y los codos directamente debajo de los hombros.", "Activa el core y mantén el cuerpo en línea recta de la cabeza a los pies.", "Baja el pecho hacia el suelo flexionando los codos, manteniéndolos cerca del cuerpo.", "Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Fondos a 1 Brazo', 'one-arm-dip.gif', 'upper arms', '["Stand facing away from a bench or chair, with your feet shoulder-width apart.", "Place one hand on the bench or chair behind you, fingers pointing towards your body.", "Extend your legs out in front of you, keeping your heels on the ground.", "Bend your elbows and lower your body towards the ground, keeping your back close to the bench or chair.", "Pause for a moment at the bottom, then push through your palms to straighten your arms and return to the starting position.", "Repeat for the desired number of repetitions, then switch sides and repeat with the other arm."]', '["Ponte de pie de espaldas a un banco o silla, con los pies separados a la altura de los hombros.", "Coloca una mano en el banco o silla detrás de ti, con los dedos apuntando hacia tu cuerpo.", "Extiende las piernas hacia adelante, manteniendo los talones en el suelo.", "Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco o silla.", "Haz una pausa por un momento en la parte baja y luego empuja con las palmas para estirar los brazos y volver a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado y repite con el otro brazo."]'),
  ('Fondos con Fitball', 'exercise-ball-dip.gif', 'upper arms', '["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.", "Place your hands on the ball beside your hips, fingers pointing forward.", "Engage your triceps and push through your hands to lift your body off the ball, straightening your arms.", "Lower your body back down by bending your elbows, keeping them close to your sides.", "Repeat for the desired number of repetitions."]', '["Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.", "Coloca las manos sobre el balón junto a las caderas, con los dedos apuntando hacia adelante.", "Activa el tríceps y empuja con las manos para levantar el cuerpo del balón, enderezando los brazos.", "Baja el cuerpo flexionando los codos, manteniéndolos cerca de los costados.", "Repite el número de repeticiones deseado."]'),
  ('Fondos de Codos', 'elbow-dips.gif', 'upper arms', '["Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.", "Slide your hips forward off the bench and straighten your legs, keeping your heels on the ground.", "Bend your elbows and lower your body towards the ground, keeping your back close to the bench.", "Pause for a moment at the bottom, then push through your hands to straighten your arms and lift your body back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en el borde de un banco o silla con las manos sujetando el borde junto a las caderas.", "Desliza las caderas hacia adelante, fuera del banco, y estira las piernas, manteniendo los talones en el suelo.", "Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco.", "Haz una pausa por un momento en la posición más baja, luego empuja con las manos para enderezar los brazos y levantar el cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Fondos de Tríceps con Lastre', 'weighted-tricep-dips.gif', 'upper arms', '["Sit on the edge of a bench or chair with your hands gripping the edge next to your hips.", "Slide your butt off the front of the bench with your legs extended in front of you.", "Keep your back close to the bench and your elbows slightly bent.", "Lower your body by bending your elbows until your upper arms are parallel to the floor.", "Push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."]', '["Siéntate en el borde de un banco o silla con las manos sujetando el borde junto a las caderas.", "Desliza los glúteos fuera del frente del banco con las piernas extendidas frente a ti.", "Mantén la espalda cerca del banco y los codos ligeramente flexionados.", "Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.", "Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Fondos de Tríceps con Lastre en Paralelas Altas', 'weighted-triceps-dip-on-high-parallel-bars.gif', 'upper arms', '["Position yourself between two parallel bars with your hands gripping the bars and your arms fully extended.", "Bend your elbows and lower your body until your upper arms are parallel to the ground.", "Pause for a moment, then push through your palms to straighten your arms and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Colócate entre dos barras paralelas con las manos agarrando las barras y los brazos completamente extendidos.", "Flexiona los codos y baja el cuerpo hasta que la parte superior de los brazos quede paralela al suelo.", "Haz una pausa de un momento, luego empuja con las palmas para estirar los brazos y volver a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Fondos de Tríceps en Banco con Pies Elevados', 'triceps-dip-bench-leg.gif', 'upper arms', '["Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward.", "Walk your feet forward, sliding your butt off the bench, and straighten your arms.", "Bend your elbows and lower your body towards the ground, keeping your back close to the bench.", "Push through your palms to straighten your arms and return to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en el borde de un banco con las manos agarrando el borde, los dedos apuntando hacia adelante.", "Camina con los pies hacia adelante, deslizando los glúteos fuera del banco, y estira los brazos.", "Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco.", "Empuja con las palmas para estirar los brazos y regresar a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Fondos de Tríceps en el Suelo', 'triceps-dips-floor.gif', 'upper arms', '["Sit on the edge of a chair or bench with your hands next to your hips, fingers pointing forward.", "Slide your butt off the front of the chair with your legs extended in front of you.", "Straighten your arms, keeping a little bend in your elbows to keep tension on your triceps and off your elbow joints.", "Slowly bend your elbows to lower your body toward the floor until your elbows are at about a 90-degree angle.", "Once you reach the bottom of the movement, press down into the chair to straighten your elbows, returning to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en el borde de una silla o banco con las manos junto a las caderas, los dedos apuntando hacia adelante.", "Desliza los glúteos fuera del frente de la silla con las piernas extendidas frente a ti.", "Estira los brazos, manteniendo una ligera flexión en los codos para conservar la tensión en los tríceps y aliviarla en las articulaciones del codo.", "Flexiona lentamente los codos para bajar el cuerpo hacia el suelo hasta que los codos formen un ángulo de aproximadamente 90 grados.", "Cuando llegues al punto más bajo del movimiento, empuja hacia abajo contra la silla para estirar los codos, volviendo a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Fondos de Tríceps en Máquina con Agarre Prono', 'lever-overhand-triceps-dip.gif', 'upper arms', '["Adjust the machine to the appropriate height and secure your body in position.", "Grasp the handles with an overhand grip and position your body so that your arms are fully extended.", "Lower your body by bending your elbows, keeping your upper arms close to your sides.", "Continue lowering until your upper arms are parallel to the floor.", "Pause for a moment, then push yourself back up to the starting position by extending your elbows.", "Repeat for the desired number of repetitions."]', '["Ajusta la máquina a la altura adecuada y asegura tu cuerpo en posición.", "Sujeta las asas con un agarre prono y coloca el cuerpo de modo que los brazos queden completamente extendidos.", "Baja el cuerpo flexionando los codos, manteniendo los brazos superiores cerca de los costados.", "Continúa bajando hasta que los brazos superiores queden paralelos al suelo.", "Haz una pausa breve, luego empújate de vuelta hacia arriba a la posición inicial extendiendo los codos.", "Repite el número de repeticiones deseado."]'),
  ('Fondos de Tríceps entre 2 Bancos', 'triceps-dip-between-benches.gif', 'upper arms', '["Sit on a bench with your hands gripping the edge of the bench, fingers pointing forward.", "Slide your butt off the bench, supporting your weight with your hands.", "Bend your elbows and lower your body towards the ground, keeping your back close to the bench.", "Pause for a moment at the bottom, then push yourself back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con las manos agarrando el borde del banco, los dedos apuntando hacia adelante.", "Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos.", "Flexiona los codos y baja el cuerpo hacia el suelo, manteniendo la espalda cerca del banco.", "Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Fondos en Banco con Lastre', 'weighted-bench-dip.gif', 'upper arms', '["Sit on a bench with your hands gripping the edge, fingers pointing forward.", "Slide your butt off the bench, supporting your weight with your hands.", "Lower your body by bending your elbows until your upper arms are parallel to the floor.", "Push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con las manos agarrando el borde, los dedos apuntando hacia adelante.", "Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos.", "Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.", "Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Fondos en Banco con Piernas Extendidas', 'bench-dip-on-floor.gif', 'upper arms', '["Sit on the edge of a bench or chair with your hands gripping the edge, fingers pointing forward.", "Slide your butt off the bench, supporting your weight with your hands.", "Lower your body by bending your elbows until your upper arms are parallel to the floor.", "Push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."]', '["Siéntate en el borde de un banco o silla con las manos sujetando el borde, los dedos apuntando hacia adelante.", "Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos.", "Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.", "Empújate de vuelta hacia arriba a la posición inicial extendiendo los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Fondos entre 3 Bancos', 'three-bench-dip.gif', 'upper arms', '["Sit on a bench with your hands gripping the edge, fingers pointing forward.", "Slide your butt off the bench, supporting your weight with your hands.", "Bend your elbows and lower your body until your upper arms are parallel to the ground.", "Push yourself back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con las manos agarrando el borde, los dedos apuntando hacia adelante.", "Desliza los glúteos fuera del banco, sosteniendo tu peso con las manos.", "Flexiona los codos y baja el cuerpo hasta que la parte superior de los brazos quede paralela al suelo.", "Empújate de vuelta hacia arriba hasta la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Fondos entre 3 Bancos con Lastre', 'weighted-three-bench-dips.gif', 'upper arms', '["Sit on the edge of a bench with your hands gripping the edge, fingers pointing forward.", "Walk your feet forward, sliding your butt off the bench and supporting your weight with your arms.", "Lower your body by bending your elbows, keeping your back close to the bench.", "Pause for a moment at the bottom, then push yourself back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en el borde de un banco con las manos agarrando el borde, los dedos apuntando hacia adelante.", "Camina con los pies hacia adelante, deslizando los glúteos fuera del banco y sosteniendo tu peso con los brazos.", "Baja el cuerpo flexionando los codos, manteniendo la espalda cerca del banco.", "Haz una pausa por un momento en la parte inferior, luego empuja tu cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Fondos Imposibles', 'impossible-dips.gif', 'upper arms', '["Position yourself between two parallel bars with your arms fully extended and your body suspended in the air.", "Bend your knees and cross your ankles.", "Lower your body by bending your elbows until your upper arms are parallel to the ground.", "Pause for a moment, then push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."]', '["Colócate entre dos barras paralelas con los brazos completamente extendidos y el cuerpo suspendido en el aire.", "Flexiona las rodillas y cruza los tobillos.", "Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.", "Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Fondos Invertidos', 'reverse-dip.gif', 'upper arms', '["Position yourself between two parallel bars with your arms fully extended and your body straight.", "Lower your body by bending your elbows until your upper arms are parallel to the ground.", "Pause for a moment, then push yourself back up to the starting position by straightening your arms.", "Repeat for the desired number of repetitions."]', '["Colócate entre dos barras paralelas con los brazos completamente extendidos y el cuerpo recto.", "Baja el cuerpo flexionando los codos hasta que los brazos queden paralelos al suelo.", "Haz una pausa breve, luego empújate de nuevo hacia arriba a la posición inicial estirando los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Jalón de Pie en Polea con Cuerda', 'cable-standing-pulldown-with-rope.gif', 'upper arms', '["Attach a rope to the cable machine at the highest setting.", "Stand facing the machine with your feet shoulder-width apart.", "Grasp the rope with an overhand grip, palms facing down.", "Keep your back straight and core engaged throughout the exercise.", "Pull the rope down towards your thighs, squeezing your biceps.", "Pause for a moment at the bottom, then slowly release the rope back up.", "Repeat for the desired number of repetitions."]', '["Sujeta una cuerda a la máquina de cable en el ajuste más alto.", "Ponte de pie frente a la máquina con los pies separados a la altura de los hombros.", "Agarra la cuerda con un agarre prono, con las palmas hacia abajo.", "Mantén la espalda recta y el core activado durante todo el ejercicio.", "Tira de la cuerda hacia abajo, hacia los muslos, apretando los bíceps.", "Haz una pausa breve en la parte baja, luego suelta lentamente la cuerda hacia arriba.", "Repite el número de repeticiones deseado."]'),
  ('Lanzamiento de Pecho Tumbado con Balón Medicinal', 'medicine-ball-supine-chest-throw.gif', 'upper arms', '["Lie flat on your back on a bench with your knees bent and feet flat on the ground.", "Hold the medicine ball with both hands, extending your arms straight up above your chest.", "Lower the medicine ball towards your chest, keeping your elbows close to your body.", "Explosively push the medicine ball upwards, extending your arms fully and throwing the ball as high as possible.", "Catch the medicine ball and repeat for the desired number of repetitions."]', '["Túmbate boca arriba en un banco con las rodillas flexionadas y los pies planos en el suelo.", "Sostén el balón medicinal con ambas manos, extendiendo los brazos rectos por encima del pecho.", "Baja el balón medicinal hacia el pecho, manteniendo los codos cerca del cuerpo.", "Empuja el balón medicinal explosivamente hacia arriba, extendiendo completamente los brazos y lanzando el balón lo más alto posible.", "Atrapa el balón medicinal y repite el número de repeticiones deseado."]'),
  ('Parada de Manos (Handstand)', 'handstand.gif', 'upper arms', '["Find an open space with enough room to perform a handstand.", "Place your hands on the ground shoulder-width apart, fingers pointing forward.", "Kick your legs up towards the wall, using your core and shoulders to maintain balance.", "Once in a handstand position, engage your triceps to support your body weight.", "Hold the handstand for as long as you can maintain balance.", "To come down, slowly lower your legs back to the ground.", "Repeat for the desired number of repetitions."]', '["Busca un espacio abierto con suficiente espacio para hacer un pino.", "Coloca las manos en el suelo separadas a la altura de los hombros, con los dedos apuntando hacia adelante.", "Lanza las piernas hacia la pared, usando el core y los hombros para mantener el equilibrio.", "Una vez en posición de pino, activa los tríceps para sostener el peso corporal.", "Mantén el pino el mayor tiempo posible mientras conserves el equilibrio.", "Para bajar, lleva lentamente las piernas de vuelta al suelo.", "Repite el número de repeticiones deseado."]'),
  ('Patada de Tríceps a 1 Brazo de Pie', 'dumbbell-one-arm-kickback.gif', 'upper arms', '["Stand with your feet shoulder-width apart and hold a dumbbell in your right hand.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Bring your right elbow up to your side, keeping it bent at a 90-degree angle.", "Extend your right arm straight back, squeezing your triceps at the top of the movement.", "Slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch sides."]', '["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en la mano derecha.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.", "Lleva el codo derecho hacia el costado, manteniéndolo flexionado en un ángulo de 90 grados.", "Extiende el brazo derecho recto hacia atrás, contrayendo el tríceps en la parte superior del movimiento.", "Baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Patada de Tríceps a 1 Brazo Sentado', 'dumbbell-seated-one-arm-kickback.gif', 'upper arms', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in one hand.", "Bend your torso forward at the waist, keeping your back straight and parallel to the ground.", "Extend your arm straight back, keeping your elbow close to your body.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna con una mano.", "Inclina el torso hacia adelante desde la cintura, manteniendo la espalda recta y paralela al suelo.", "Extiende el brazo recto hacia atrás, manteniendo el codo cerca de tu cuerpo.", "Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Patada de Tríceps a 1 Pierna (Postura de Cigüeña)', 'dumbbell-tricep-kickback-with-stork-stance.gif', 'upper arms', '["Stand with your feet shoulder-width apart and hold a dumbbell in your right hand.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Bring your right elbow up to your side, keeping it bent at a 90-degree angle.", "Extend your right arm straight back, squeezing your triceps.", "Pause for a moment, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch sides."]', '["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en la mano derecha.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.", "Lleva el codo derecho hacia el costado, manteniéndolo flexionado en un ángulo de 90 grados.", "Extiende el brazo derecho recto hacia atrás, apretando el tríceps.", "Haz una pausa por un momento, luego baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Patada de Tríceps a 2 Brazos en Polea', 'cable-two-arm-tricep-kickback.gif', 'upper arms', '["Stand with your feet shoulder-width apart and knees slightly bent.", "Hold the cable handle in each hand with your palms facing inwards and your arms bent at a 90-degree angle.", "Keeping your upper arms stationary, extend your forearms backwards until your arms are fully extended.", "Pause for a moment, then slowly return to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y las rodillas ligeramente flexionadas.", "Sujeta el mango del cable en cada mano con las palmas hacia adentro y los brazos flexionados en un ángulo de 90 grados.", "Manteniendo los brazos superiores quietos, extiende los antebrazos hacia atrás hasta que los brazos estén completamente extendidos.", "Haz una pausa por un momento, luego regresa lentamente a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Patada de Tríceps Alterna de Pie', 'dumbbell-standing-alternating-tricep-kickback.gif', 'upper arms', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Extend your arms straight back, keeping your elbows close to your body.", "Pause for a moment at the top, then slowly lower the dumbbells back to the starting position.", "Repeat with the other arm, alternating sides with each repetition."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.", "Extiende los brazos rectos hacia atrás, manteniendo los codos cerca del cuerpo.", "Haz una pausa breve en la parte alta, luego baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite con el otro brazo, alternando lados en cada repetición."]'),
  ('Patada de Tríceps Alterna Sentado Inclinado', 'dumbbell-seated-bent-over-alternate-kickback.gif', 'upper arms', '["Sit on a bench with a dumbbell in each hand, palms facing inwards.", "Bend forward at the waist, keeping your back straight and parallel to the ground.", "Extend one arm straight back, keeping it close to your body, until your arm is fully extended.", "Pause for a moment, then slowly lower the dumbbell back to the starting position.", "Repeat with the other arm.", "Continue alternating arms for the desired number of repetitions."]', '["Siéntate en un banco con una mancuerna en cada mano, con las palmas hacia adentro.", "Inclínate hacia adelante desde la cintura, manteniendo la espalda recta y paralela al suelo.", "Extiende un brazo recto hacia atrás, manteniéndolo cerca de tu cuerpo, hasta que el brazo esté completamente extendido.", "Haz una pausa por un momento, luego baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite con el otro brazo.", "Continúa alternando los brazos durante el número de repeticiones deseado."]'),
  ('Patada de Tríceps de Pie con Mancuernas', 'dumbbell-standing-kickback.gif', 'upper arms', '["Stand with your feet shoulder-width apart and hold a dumbbell in each hand.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Extend your arms straight back, squeezing your triceps at the top of the movement.", "Pause for a moment, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sostén una mancuerna en cada mano.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.", "Extiende los brazos rectos hacia atrás, contrayendo los tríceps en la parte superior del movimiento.", "Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Patada de Tríceps en Polea', 'cable-kickback-0860.gif', 'upper arms', '["Stand facing a cable machine with your feet shoulder-width apart.", "Hold the cable handle with your right hand and step back to create tension in the cable.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Keep your upper arm close to your body and your elbow bent at a 90-degree angle.", "Extend your forearm backward, straightening your arm fully.", "Pause for a moment, then slowly return to the starting position.", "Repeat for the desired number of repetitions, then switch sides."]', '["Ponte de pie frente a una máquina de cable con los pies separados a la altura de los hombros.", "Sujeta la agarradera del cable con la mano derecha y retrocede un paso para crear tensión en el cable.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.", "Mantén la parte superior del brazo cerca del cuerpo y el codo flexionado en un ángulo de 90 grados.", "Extiende el antebrazo hacia atrás, enderezando el brazo por completo.", "Haz una pausa por un momento, luego regresa lentamente a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Patada de Tríceps Sentado Inclinado', 'dumbbell-seated-kickback.gif', 'upper arms', '["Sit on a bench with your feet flat on the ground and hold a dumbbell in each hand.", "Bend your knees slightly and lean forward from your hips, keeping your back straight.", "Bring your upper arms close to your sides and keep your elbows bent at a 90-degree angle.", "Extend your arms straight back, squeezing your triceps at the top of the movement.", "Pause for a moment, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco con los pies apoyados en el suelo y sujeta una mancuerna en cada mano.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.", "Acerca la parte superior de los brazos a tus costados y mantén los codos flexionados en un ángulo de 90 grados.", "Extiende los brazos rectos hacia atrás, contrayendo los tríceps en la parte superior del movimiento.", "Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Patada de Tríceps sobre Fitball', 'dumbbell-kickbacks-on-exercise-ball.gif', 'upper arms', '["Sit on an exercise ball with your feet flat on the ground and your back straight.", "Hold a dumbbell in each hand with your palms facing inwards and your arms bent at a 90-degree angle.", "Extend your arms straight back, squeezing your triceps at the top of the movement.", "Pause for a moment, then slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.", "Sostén una mancuerna en cada mano con las palmas hacia adentro y los brazos flexionados en un ángulo de 90 grados.", "Extiende los brazos rectos hacia atrás, contrayendo los tríceps en la parte superior del movimiento.", "Haz una pausa por un momento, luego baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Press a 1 Brazo con Agarre Neutro sobre Fitball', 'dumbbell-one-arm-hammer-press-on-exercise-ball.gif', 'upper arms', '["Sit on an exercise ball with your feet flat on the ground and your back straight.", "Hold a dumbbell in one hand with your palm facing inwards and your elbow bent at a 90-degree angle.", "Place your other hand on your hip for stability.", "Press the dumbbell upwards, extending your arm fully.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.", "Sostén una mancuerna en una mano con la palma hacia adentro y el codo flexionado en un ángulo de 90 grados.", "Coloca la otra mano en la cadera para mantener el equilibrio.", "Empuja la mancuerna hacia arriba, extendiendo completamente el brazo.", "Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Press a la Cara con Barra Z en Banco Declinado', 'ez-barbell-decline-close-grip-face-press.gif', 'upper arms', '["Lie on a decline bench with your head lower than your feet.", "Grasp the ez barbell with a close grip, palms facing each other.", "Extend your arms straight up above your chest, keeping your elbows close to your body.", "Lower the barbell towards your forehead by bending your elbows.", "Pause for a moment, then press the barbell back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate en un banco declinado con la cabeza más baja que los pies.", "Sujeta la barra EZ con agarre cerrado, palmas una frente a la otra.", "Extiende los brazos rectos por encima del pecho, manteniendo los codos cerca del cuerpo.", "Baja la barra hacia la frente doblando los codos.", "Haz una pausa breve, luego empuja la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Press Cerrado a la Frente con Barra en Banco Declinado', 'barbell-decline-close-grip-to-skull-press.gif', 'upper arms', '["Lie on a decline bench with your head lower than your feet and hold a barbell with a close grip.", "Lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary.", "Pause for a moment, then extend your arms to press the barbell back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate en un banco declinado con la cabeza más baja que los pies y sujeta una barra con un agarre cerrado.", "Baja la barra hacia la frente flexionando los codos, manteniendo los brazos superiores fijos.", "Haz una pausa breve y luego extiende los brazos para empujar la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Press Cerrado con Mancuernas', 'dumbbell-close-grip-press.gif', 'upper arms', '["Sit on a flat bench with a dumbbell in each hand, resting on your thighs.", "Using your thighs to help raise the dumbbells, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width.", "Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.", "As you breathe in, slowly lower the dumbbells to your side until they are about level with your chest.", "As you exhale, use your triceps to lift the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate en un banco plano con una mancuerna en cada mano, apoyadas en los muslos.", "Usando los muslos para ayudar a levantar las mancuernas, levanta las mancuernas una a la vez para poder sostenerlas frente a ti a la altura de los hombros.", "Una vez a la altura de los hombros, rota las muñecas hacia adelante de modo que las palmas de las manos miren hacia afuera de ti. Esta será tu posición inicial.", "Mientras inhalas, baja lentamente las mancuernas hacia tu lado hasta que queden aproximadamente a la altura del pecho.", "Mientras exhalas, usa los tríceps para levantar las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Press de Banca Cerrado con Barra y Agarre Supino', 'barbell-reverse-close-grip-bench-press.gif', 'upper arms', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.", "Grasp the barbell with a reverse grip, hands shoulder-width apart.", "Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.", "Slowly lower the barbell down towards your chest, keeping your elbows close to your body.", "Pause for a moment when the barbell is just above your chest.", "Push the barbell back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.", "Agarra la barra con un agarre invertido, manos separadas a la altura de los hombros.", "Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.", "Baja la barra lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.", "Haz una pausa breve cuando la barra esté justo encima del pecho.", "Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Press de Banca Cerrado con Barra Z', 'ez-bar-close-grip-bench-press.gif', 'upper arms', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.", "Grasp the ez barbell with a close grip, hands shoulder-width apart, palms facing forward.", "Lift the barbell off the rack and hold it directly above your chest with your arms fully extended.", "Slowly lower the barbell towards your chest, keeping your elbows close to your body.", "Pause for a moment when the barbell touches your chest.", "Push the barbell back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.", "Sujeta la barra EZ con agarre cerrado, manos separadas a la altura de los hombros, palmas hacia adelante.", "Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.", "Baja la barra lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.", "Haz una pausa breve cuando la barra toque el pecho.", "Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Press de Banca Cerrado en Máquina Smith', 'smith-close-grip-bench-press.gif', 'upper arms', '["Adjust the seat height and position yourself on the bench with your feet flat on the ground.", "Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.", "Lower the barbell towards your chest, keeping your elbows close to your body.", "Pause for a moment at the bottom, then push the barbell back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la altura del asiento y colócate en el banco con los pies planos sobre el suelo.", "Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros.", "Baja la barra hacia el pecho, manteniendo los codos pegados cerca del cuerpo.", "Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Press de Banca con Giro con Mancuernas', 'dumbbell-twisting-bench-press.gif', 'upper arms', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.", "Hold a dumbbell in each hand with an overhand grip, palms facing away from you.", "Extend your arms straight up over your chest, keeping a slight bend in your elbows.", "Lower the dumbbells down towards your chest, keeping your elbows close to your body.", "As you lower the dumbbells, twist your wrists so that your palms face towards you at the bottom of the movement.", "Pause for a moment at the bottom, then reverse the movement by pressing the dumbbells back up to the starting position.", "As you press the dumbbells up, twist your wrists back to the starting position with palms facing away from you.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.", "Sujeta una mancuerna en cada mano con agarre prono, con las palmas alejadas de ti.", "Extiende los brazos rectos hacia arriba sobre el pecho, con una ligera flexión en los codos.", "Baja las mancuernas hacia el pecho, manteniendo los codos cerca del cuerpo.", "Mientras bajas las mancuernas, gira las muñecas de modo que las palmas queden hacia ti en la parte más baja del movimiento.", "Haz una pausa por un momento en la parte más baja, luego invierte el movimiento presionando las mancuernas de vuelta hacia arriba, hasta la posición inicial.", "Mientras presionas las mancuernas hacia arriba, gira las muñecas de vuelta a la posición inicial con las palmas alejadas de ti.", "Repite el número de repeticiones deseado."]'),
  ('Press de Codo Tumbado con Mancuernas', 'dumbbell-lying-elbow-press.gif', 'upper arms', '["Lie flat on a bench with a dumbbell in each hand, palms facing each other and arms extended straight up over your chest.", "Lower the dumbbells towards your shoulders by bending your elbows, keeping your upper arms stationary.", "Pause for a moment at the bottom, then press the dumbbells back up to the starting position by extending your elbows.", "Repeat for the desired number of repetitions."]', '["Túmbate boca arriba en un banco con una mancuerna en cada mano, con las palmas enfrentadas entre sí y los brazos extendidos rectos hacia arriba sobre el pecho.", "Baja las mancuernas hacia los hombros flexionando los codos, manteniendo los brazos superiores quietos.", "Haz una pausa por un momento en la parte inferior, luego empuja las mancuernas de nuevo hacia arriba hasta la posición inicial extendiendo los codos.", "Repite el número de repeticiones deseado."]'),
  ('Press Declinado a 1 Brazo con Mancuerna y Agarre Neutro', 'dumbbell-decline-one-arm-hammer-press.gif', 'upper arms', '["Lie on a decline bench with a dumbbell in one hand, resting on your chest.", "Extend your arm straight up, keeping your elbow slightly bent.", "Lower the dumbbell down towards your shoulder, keeping your elbow close to your body.", "Press the dumbbell back up to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Túmbate en un banco declinado con una mancuerna en una mano, apoyada sobre el pecho.", "Extiende el brazo recto hacia arriba, manteniendo el codo ligeramente flexionado.", "Baja la mancuerna hacia el hombro, manteniendo el codo cerca del cuerpo.", "Empuja la mancuerna de nuevo hacia arriba hasta la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Press Declinado Cerrado en Máquina Smith', 'smith-machine-decline-close-grip-bench-press.gif', 'upper arms', '["Adjust the bench on the smith machine to a decline position.", "Lie down on the bench with your feet firmly planted on the ground.", "Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.", "Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.", "Pause for a moment when the barbell is just above your chest.", "Push the barbell back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Ajusta el banco de la máquina Smith a una posición declinada.", "Túmbate en el banco con los pies firmemente apoyados en el suelo.", "Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros.", "Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.", "Haz una pausa breve cuando la barra esté justo encima del pecho.", "Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Press desde Pines con Barra', 'barbell-pin-presses.gif', 'upper arms', '["Set up a barbell on a power rack at chest height.", "Stand facing the barbell and position yourself underneath it, with your feet shoulder-width apart.", "Grip the barbell with an overhand grip, slightly wider than shoulder-width apart.", "Lift the barbell off the rack and hold it directly above your chest, with your arms fully extended.", "Lower the barbell down towards your chest, keeping your elbows tucked in close to your body.", "Pause for a moment when the barbell touches your chest.", "Push the barbell back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Coloca una barra en un rack de potencia a la altura del pecho.", "Ponte de pie frente a la barra y colócate debajo de ella, con los pies separados a la altura de los hombros.", "Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.", "Levanta la barra del soporte y sostenla directamente sobre el pecho con los brazos completamente extendidos.", "Baja la barra hacia el pecho, manteniendo los codos pegados cerca del cuerpo.", "Haz una pausa breve cuando la barra toque el pecho.", "Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Press en el Suelo a 1 Brazo con Barra', 'barbell-one-arm-floor-press.gif', 'upper arms', '["Lie flat on your back on the floor with your knees bent and feet flat on the ground.", "Hold the barbell with one hand, palm facing up, and extend your arm straight up over your chest.", "Slowly lower the barbell towards your chest, keeping your elbow close to your body.", "Pause for a moment at the bottom, then push the barbell back up to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies planos sobre el suelo.", "Sujeta la barra con una mano, con la palma hacia arriba, y extiende el brazo recto por encima del pecho.", "Baja la barra lentamente hacia el pecho, manteniendo el codo cerca del cuerpo.", "Haz una pausa breve en la parte baja y luego empuja la barra de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Press Francés a 1 Brazo sobre Fitball', 'dumbbell-one-arm-french-press-on-exercise-ball.gif', 'upper arms', '["Sit on an exercise ball with your feet flat on the ground and your back straight.", "Hold a dumbbell in one hand with your palm facing up and your elbow bent at a 90-degree angle.", "Extend your arm straight up towards the ceiling, keeping your elbow stationary.", "Slowly lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Siéntate sobre un balón de ejercicio con los pies apoyados planos en el suelo y la espalda recta.", "Sostén una mancuerna en una mano con la palma hacia arriba y el codo flexionado en un ángulo de 90 grados.", "Extiende el brazo recto hacia el techo, manteniendo el codo quieto.", "Baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Press Francés con Barra Z sobre Fitball', 'ez-bar-french-press-on-exercise-ball.gif', 'upper arms', '["Sit on an exercise ball and hold an EZ barbell with an overhand grip.", "Extend your arms straight up, keeping your elbows close to your head.", "Slowly lower the barbell behind your head by bending your elbows.", "Pause for a moment, then extend your arms back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate sobre un balón de ejercicio y sostén una barra EZ con agarre prono.", "Extiende los brazos rectos hacia arriba, manteniendo los codos cerca de la cabeza.", "Baja lentamente la barra detrás de la cabeza doblando los codos.", "Haz una pausa breve y luego extiende los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Press Francés de Pie con Barra Z', 'ez-bar-standing-french-press.gif', 'upper arms', '["Stand with your feet shoulder-width apart and hold the ez barbell with an overhand grip.", "Raise the barbell above your head, fully extending your arms.", "Keeping your upper arms close to your head, slowly lower the barbell behind your head by bending your elbows.", "Pause for a moment, then extend your arms back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y sostén la barra EZ con agarre prono.", "Levanta la barra por encima de la cabeza, extendiendo completamente los brazos.", "Manteniendo los brazos superiores cerca de la cabeza, baja lentamente la barra detrás de la cabeza flexionando los codos.", "Haz una pausa por un momento y luego extiende los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Press Inclinado a 1 Brazo con Agarre Neutro sobre Fitball', 'dumbbell-incline-one-arm-hammer-press-on-exercise-ball.gif', 'upper arms', '["Sit on an exercise ball with a dumbbell in one hand.", "Walk your feet forward and roll your body down until your head, neck, and upper back are supported on the ball.", "Hold the dumbbell with your palm facing inward and your elbow bent at a 90-degree angle.", "Press the dumbbell up towards the ceiling, straightening your arm.", "Lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Siéntate sobre un balón de estabilidad con una mancuerna en una mano.", "Camina con los pies hacia adelante y baja el cuerpo rodando hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón.", "Sostén la mancuerna con la palma hacia adentro y el codo flexionado en un ángulo de 90 grados.", "Empuja la mancuerna hacia el techo, estirando el brazo.", "Baja la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Press Inclinado a 1 Brazo con Mancuerna y Agarre Neutro', 'dumbbell-incline-one-arm-hammer-press.gif', 'upper arms', '["Sit on an incline bench with a dumbbell in one hand, resting on your thigh.", "Lean back on the bench and use your thigh to help raise the dumbbell to shoulder height.", "Rotate your wrist so that your palm is facing inward, towards your body.", "Press the dumbbell up and away from your body, extending your arm fully.", "Pause for a moment at the top, then slowly lower the dumbbell back down to the starting position.", "Repeat for the desired number of repetitions, then switch arms."]', '["Siéntate en un banco inclinado con una mancuerna en una mano, apoyada sobre el muslo.", "Recuéstate en el banco y usa el muslo para ayudar a levantar la mancuerna hasta la altura de los hombros.", "Gira la muñeca de modo que la palma quede mirando hacia adentro, hacia el cuerpo.", "Empuja la mancuerna hacia arriba y alejándola del cuerpo, extendiendo completamente el brazo.", "Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de brazo."]'),
  ('Press Inclinado con Agarre Neutro sobre Fitball', 'dumbbell-incline-hammer-press-on-exercise-ball.gif', 'upper arms', '["Sit on an exercise ball with a dumbbell in each hand, palms facing each other.", "Walk your feet forward and roll your body down the ball until your head, neck, and upper back are supported on the ball.", "Hold the dumbbells at shoulder level, elbows bent and pointing out to the sides.", "Press the dumbbells up and slightly inward, keeping your palms facing each other.", "Extend your arms fully, squeezing your triceps at the top of the movement.", "Slowly lower the dumbbells back to the starting position.", "Repeat for the desired number of repetitions."]', '["Siéntate sobre un balón de estabilidad con una mancuerna en cada mano, con las palmas enfrentadas entre sí.", "Camina con los pies hacia adelante y baja el cuerpo rodando sobre el balón hasta que la cabeza, el cuello y la parte superior de la espalda queden apoyados sobre el balón.", "Sostén las mancuernas a la altura de los hombros, con los codos flexionados y apuntando hacia los lados.", "Empuja las mancuernas hacia arriba y ligeramente hacia adentro, manteniendo las palmas enfrentadas entre sí.", "Extiende completamente los brazos, contrayendo los tríceps en la parte superior del movimiento.", "Baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Press Inclinado con Barra y Agarre Cerrado', 'barbell-incline-close-grip-bench-press.gif', 'upper arms', '["Set up an incline bench at a 45-degree angle.", "Lie down on the bench with your feet flat on the ground.", "Grasp the barbell with a close grip, slightly narrower than shoulder-width apart.", "Unrack the barbell and lower it slowly towards your chest, keeping your elbows close to your body.", "Pause for a moment when the barbell touches your chest.", "Push the barbell back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Coloca un banco inclinado a un ángulo de 45 grados.", "Túmbate en el banco con los pies planos sobre el suelo.", "Agarra la barra con un agarre cerrado, un poco más estrecho que el ancho de los hombros.", "Saca la barra del soporte y bájala lentamente hacia el pecho, manteniendo los codos cerca del cuerpo.", "Haz una pausa breve cuando la barra toque el pecho.", "Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Press JM con Barra', 'barbell-jm-bench-press.gif', 'upper arms', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.", "Grasp the barbell with an overhand grip, slightly wider than shoulder-width apart.", "Lower the barbell to your chest, keeping your elbows tucked in close to your body.", "Push the barbell back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.", "Agarra la barra con un agarre pronado un poco más ancho que la separación de los hombros.", "Baja la barra hacia el pecho, manteniendo los codos pegados cerca del cuerpo.", "Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Press JM con Barra Z', 'ez-barbell-jm-bench-press.gif', 'upper arms', '["Lie flat on a bench with your feet flat on the ground and your back pressed against the bench.", "Grasp the ez barbell with an overhand grip, slightly wider than shoulder-width apart.", "Lower the barbell to your chest, keeping your elbows tucked in close to your body.", "Push the barbell back up to the starting position, fully extending your arms.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre un banco con los pies apoyados en el suelo y la espalda presionada contra el banco.", "Sujeta la barra EZ con agarre prono, ligeramente más ancho que la altura de los hombros.", "Baja la barra hacia el pecho, manteniendo los codos pegados cerca del cuerpo.", "Empuja la barra de vuelta a la posición inicial, extendiendo completamente los brazos.", "Repite el número de repeticiones deseado."]'),
  ('Press Stalder (Parada de Manos)', 'stalder-press.gif', 'upper arms', '["Start in a handstand with your body straight.", "Lower your hips and open your legs into a straddle close to the floor, without touching it with your feet.", "Press through your shoulders and core to raise your hips and legs again.", "Bring your legs together at the top in a handstand.", "Repeat for the desired number of repetitions."]', '["Colócate en parada de manos con el cuerpo recto.", "Baja la cadera y abre las piernas hasta quedar cerca del suelo, sin apoyar los pies.", "Empuja con los hombros y el core para volver a subir la cadera y las piernas.", "Junta las piernas arriba, en parada de manos.", "Repite el número de repeticiones deseado."]'),
  ('Press Tate con Mancuernas', 'dumbbell-tate-press.gif', 'upper arms', '["Sit on a flat bench with a dumbbell in each hand, palms facing each other.", "Raise the dumbbells to shoulder height, then rotate your wrists so that your palms are facing away from you.", "Press the dumbbells up until your arms are fully extended, then lower them back down to shoulder height.", "Rotate your wrists back to the starting position and repeat for the desired number of repetitions."]', '["Siéntate en un banco plano con una mancuerna en cada mano, con las palmas mirándose entre sí.", "Sube las mancuernas hasta la altura de los hombros, luego gira las muñecas de modo que las palmas queden mirando hacia afuera.", "Presiona las mancuernas hacia arriba hasta que los brazos queden completamente extendidos, luego bájalas de vuelta a la altura de los hombros.", "Gira las muñecas de vuelta a la posición inicial y repite el número de repeticiones deseado."]'),
  ('Pushdown con Agarre Supino y Barra Z con Arm Blaster', 'cable-reverse-grip-triceps-pushdown-sz-bar-with-arm-blaster.gif', 'upper arms', '["Attach a straight bar to the cable machine at the highest setting.", "Stand facing the cable machine with your feet shoulder-width apart.", "Grasp the bar with an underhand grip, palms facing up, and your hands shoulder-width apart.", "Keep your elbows close to your sides and your upper arms stationary throughout the exercise.", "Engage your triceps and slowly push the bar down until your arms are fully extended.", "Pause for a moment at the bottom, then slowly return the bar to the starting position.", "Repeat for the desired number of repetitions."]', '["Sujeta una barra recta a la máquina de cable en el ajuste más alto.", "Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.", "Sujeta la barra con un agarre supino, con las palmas hacia arriba y las manos separadas a la altura de los hombros.", "Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio.", "Activa los tríceps y empuja lentamente la barra hacia abajo hasta que los brazos queden completamente extendidos.", "Haz una pausa por un momento en la parte baja y luego regresa lentamente la barra a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Pushdown en Polea con Barra en V', 'cable-triceps-pushdown-v-bar.gif', 'upper arms', '["Attach a v-bar attachment to the cable machine at the highest setting.", "Stand facing the cable machine with your feet shoulder-width apart.", "Grasp the v-bar with an overhand grip, palms facing down, and your hands shoulder-width apart.", "Keep your elbows close to your sides and your upper arms stationary throughout the exercise.", "Engage your triceps and exhale as you push the v-bar down until your arms are fully extended.", "Pause for a moment at the bottom of the movement, squeezing your triceps.", "Inhale as you slowly return the v-bar to the starting position, maintaining control.", "Repeat for the desired number of repetitions."]', '["Coloca un accesorio en V en la máquina de cable en el ajuste más alto.", "Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.", "Agarra el accesorio en V con un agarre prono, con las palmas hacia abajo y las manos separadas a la altura de los hombros.", "Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio.", "Activa los tríceps y exhala mientras empujas el accesorio en V hacia abajo hasta que los brazos estén completamente extendidos.", "Haz una pausa breve en la parte baja del movimiento, apretando los tríceps.", "Inhala mientras regresas lentamente el accesorio en V a la posición inicial, manteniendo el control.", "Repite el número de repeticiones deseado."]'),
  ('Pushdown en Polea con Barra en V y Arm Blaster', 'cable-triceps-pushdown-v-bar-with-arm-blaster.gif', 'upper arms', '["Attach a v-bar attachment to the cable machine at the highest setting.", "Stand facing the cable machine with your feet shoulder-width apart.", "Grasp the v-bar with an overhand grip, palms facing down, and your hands shoulder-width apart.", "Keep your elbows close to your sides and your upper arms stationary throughout the exercise.", "Engage your triceps and exhale as you push the v-bar down until your arms are fully extended.", "Pause for a moment at the bottom of the movement, squeezing your triceps.", "Inhale as you slowly return the v-bar to the starting position, maintaining control.", "Repeat for the desired number of repetitions."]', '["Coloca un accesorio en V en la máquina de cable en el ajuste más alto.", "Ponte de pie frente a la máquina de cable con los pies separados a la altura de los hombros.", "Agarra el accesorio en V con un agarre prono, con las palmas hacia abajo y las manos separadas a la altura de los hombros.", "Mantén los codos cerca de los costados y los brazos superiores quietos durante todo el ejercicio.", "Activa los tríceps y exhala mientras empujas el accesorio en V hacia abajo hasta que los brazos estén completamente extendidos.", "Haz una pausa breve en la parte baja del movimiento, apretando los tríceps.", "Inhala mientras regresas lentamente el accesorio en V a la posición inicial, manteniendo el control.", "Repite el número de repeticiones deseado."]'),
  ('Rompecráneos con Agarre Supino', 'barbell-reverse-grip-skullcrusher.gif', 'upper arms', '["Lie flat on a bench with your feet flat on the ground and your head at the end of the bench.", "Hold the barbell with a reverse grip, palms facing towards your face, and your hands shoulder-width apart.", "Extend your arms straight up over your chest, keeping your elbows in and your wrists straight.", "Slowly lower the barbell towards your forehead by bending your elbows, keeping your upper arms stationary.", "Pause for a moment at the bottom, then extend your arms back up to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca arriba en un banco con los pies planos sobre el suelo y la cabeza en el extremo del banco.", "Sujeta la barra con un agarre invertido, palmas mirando hacia la cara, y las manos separadas a la altura de los hombros.", "Extiende los brazos rectos por encima del pecho, manteniendo los codos hacia dentro y las muñecas rectas.", "Baja lentamente la barra hacia la frente flexionando los codos, manteniendo los brazos superiores fijos.", "Haz una pausa breve en la parte baja y luego extiende los brazos de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Sentadilla con Curl de Bíceps', 'dumbbell-biceps-curl-squat.gif', 'upper arms', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.", "Keeping your back straight and your elbows close to your sides, exhale and curl the dumbbells up towards your shoulders.", "Pause for a moment at the top, squeezing your biceps.", "Inhale and slowly lower the dumbbells back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con las palmas hacia adelante.", "Manteniendo la espalda recta y los codos cerca de los costados, exhala y flexiona las mancuernas hacia los hombros.", "Haz una pausa breve en la parte alta, apretando los bíceps.", "Inhala y baja lentamente las mancuernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Step-Up a 1 Pierna con Curl de Bíceps', 'dumbbell-step-up-single-leg-balance-with-bicep-curl.gif', 'upper arms', '["Stand in front of a step or platform with a dumbbell in each hand, palms facing your body.", "Place your right foot on the step, ensuring your entire foot is in contact with the surface.", "Engage your core and push through your right heel to lift your body up onto the step, bringing your left knee up towards your chest.", "At the top of the movement, perform a bicep curl by bending your elbows and bringing the dumbbells towards your shoulders.", "Lower the dumbbells back down and simultaneously lower your left foot back to the ground.", "Repeat the movement on the opposite side, stepping up with your left foot and curling the dumbbells.", "Continue alternating sides for the desired number of repetitions."]', '["Ponte de pie frente a un escalón o plataforma con una mancuerna en cada mano, con las palmas hacia tu cuerpo.", "Coloca el pie derecho sobre el escalón, asegurándote de que todo el pie esté en contacto con la superficie.", "Activa el core y empuja con el talón derecho para subir el cuerpo sobre el escalón, llevando la rodilla izquierda hacia el pecho.", "En la parte superior del movimiento, realiza un curl de bíceps flexionando los codos y llevando las mancuernas hacia los hombros.", "Baja las mancuernas y, al mismo tiempo, baja el pie izquierdo de vuelta al suelo.", "Repite el movimiento del lado contrario, subiendo con el pie izquierdo y flexionando las mancuernas.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Tirón Horizontal a 1 Brazo en Polea (Deltoides Posterior)', 'cable-rear-drive.gif', 'upper arms', '["Set a handle on the pulley at shoulder height and stand side-on to the machine.", "Hold the handle with the far hand, arm extended across your body.", "With your arm almost straight, pull it back horizontally to shoulder line.", "Squeeze your shoulder blade, pause, then return slowly.", "Complete the repetitions, then switch arms."]', '["Coloca un agarre en la polea a la altura del hombro y ponte de lado a la máquina.", "Sujeta el agarre con la mano más alejada, con el brazo extendido cruzando el cuerpo.", "Con el brazo casi recto, llévalo hacia atrás en horizontal hasta la línea del hombro.", "Junta el omóplato, haz una breve pausa y vuelve lentamente.", "Completa las repeticiones y cambia de brazo."]'),
  ('Zancada al Frente con Extensión de Tríceps', 'dumbbell-forward-lunge-triceps-extension.gif', 'upper arms', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand.", "Take a step forward with your right foot, lowering your body into a lunge position.", "Keep your back straight and your chest up.", "Extend your arms straight overhead, keeping your elbows close to your ears.", "Lower the dumbbells behind your head by bending your elbows.", "Pause for a moment, then straighten your arms to return to the starting position.", "Repeat the movement for the desired number of repetitions, then switch legs and repeat."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano.", "Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada.", "Mantén la espalda recta y el pecho elevado.", "Extiende los brazos rectos por encima de la cabeza, manteniendo los codos cerca de las orejas.", "Baja las mancuernas detrás de la cabeza flexionando los codos.", "Haz una pausa por un momento, luego estira los brazos para volver a la posición inicial.", "Repite el movimiento el número de repeticiones deseado, luego cambia de pierna y repite."]'),
  ('Zancada con Curl de Bíceps', 'dumbbell-lunge-with-bicep-curl.gif', 'upper arms', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward.", "Take a step forward with your right foot, lowering your body into a lunge position. Your right knee should be bent at a 90-degree angle and your left knee should be hovering just above the ground.", "As you lunge forward, simultaneously curl the dumbbells towards your shoulders, keeping your elbows close to your body.", "Pause for a moment at the bottom of the lunge, then push through your right heel to return to the starting position, lowering the dumbbells back down to your sides.", "Repeat the lunge and bicep curl on the opposite side, stepping forward with your left foot.", "Continue alternating sides for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con las palmas hacia adelante.", "Da un paso adelante con el pie derecho, bajando el cuerpo hasta una posición de zancada. La rodilla derecha debe quedar flexionada en un ángulo de 90 grados y la rodilla izquierda debe quedar justo por encima del suelo.", "Mientras avanzas en la zancada, flexiona simultáneamente las mancuernas hacia los hombros, manteniendo los codos cerca del cuerpo.", "Haz una pausa por un momento en la parte baja de la zancada, luego empuja con el talón derecho para volver a la posición inicial, bajando las mancuernas de nuevo a los costados.", "Repite la zancada y el curl de bíceps en el lado opuesto, dando un paso adelante con el pie izquierdo.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Abducción de Cadera de Pie con Pierna Recta', 'straight-leg-outer-hip-abductor.gif', 'upper legs', '["Lie on your side with your legs straight and stacked on top of each other.", "Place your bottom arm under your head for support.", "Engage your core and lift your top leg as high as possible without rotating your hips or leaning backward.", "Pause for a moment at the top, then slowly lower your leg back down to the starting position.", "Repeat for the desired number of repetitions, then switch sides."]', '["Túmbate de lado con las piernas rectas y apiladas una sobre la otra.", "Coloca el brazo de abajo bajo la cabeza para apoyarte.", "Activa el core y levanta la pierna superior lo más alto posible sin rotar las caderas ni inclinarte hacia atrás.", "Haz una pausa por un momento en la posición alta, luego baja lentamente la pierna de nuevo a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Abducción de Cadera en Plancha Lateral', 'side-bridge-hip-abduction.gif', 'upper legs', '["Lie on your side with your legs extended and stacked on top of each other.", "Prop yourself up on your forearm, keeping your elbow directly below your shoulder.", "Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.", "While keeping your core engaged, lift your top leg as high as possible without rotating your hips.", "Pause for a moment at the top, then lower your leg back down.", "Repeat for the desired number of repetitions, then switch sides."]', '["Túmbate de lado con las piernas extendidas y una sobre la otra.", "Apóyate sobre el antebrazo, manteniendo el codo directamente debajo del hombro.", "Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies.", "Manteniendo el core activado, levanta la pierna superior lo más alto posible sin rotar las caderas.", "Haz una pausa por un momento en la posición alta, luego baja la pierna de nuevo.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Abrazo de Rodillas al Pecho', 'hug-keens-to-chest.gif', 'upper legs', '["Start by standing with your feet shoulder-width apart.", "Bend your knees and lower your body down into a squat position.", "As you squat down, bring your knees up towards your chest and hug them with your arms.", "Hold this position for a moment, then slowly return to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza de pie con los pies separados a la altura de los hombros.", "Flexiona las rodillas y baja el cuerpo hacia una posición de sentadilla.", "Al ponerte en cuclillas, lleva las rodillas hacia el pecho y abrázalas con los brazos.", "Mantén esta posición por un momento, luego regresa lentamente a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Aducción de Cadera en Plancha Lateral con Banco', 'side-plank-hip-adduction.gif', 'upper legs', '["Start by lying on your side with your legs extended and stacked on top of each other.", "Prop yourself up on your forearm, keeping your elbow directly below your shoulder.", "Engage your core and lift your hips off the ground, creating a straight line from your head to your feet.", "While maintaining the side plank position, lift your top leg towards the ceiling, keeping it straight.", "Slowly lower your leg back down to the starting position.", "Repeat for the desired number of repetitions, then switch sides."]', '["Comienza tumbado de lado con las piernas extendidas y apiladas una sobre la otra.", "Apóyate sobre el antebrazo, manteniendo el codo directamente debajo del hombro.", "Activa el core y levanta las caderas del suelo, formando una línea recta desde la cabeza hasta los pies.", "Manteniendo la posición de plancha lateral, levanta la pierna de arriba hacia el techo, manteniéndola recta.", "Baja lentamente la pierna de nuevo a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Aducción de Cadera Tumbado de Lado', 'side-lying-hip-adduction-male.gif', 'upper legs', '["Lie on your side with your legs straight and stacked on top of each other.", "Place your bottom arm under your head for support.", "Engage your adductors and lift your top leg as high as possible without rotating your hips or leaning backward.", "Pause for a moment at the top, then slowly lower your leg back down to the starting position.", "Repeat for the desired number of repetitions, then switch sides."]', '["Túmbate de lado con las piernas rectas y apiladas una sobre la otra.", "Coloca el brazo de abajo bajo la cabeza para apoyarte.", "Activa los aductores y levanta la pierna de arriba lo más alto posible sin rotar las caderas ni inclinarte hacia atrás.", "Haz una pausa por un momento en la posición alta, luego baja lentamente la pierna de nuevo a la posición inicial.", "Repite el número de repeticiones deseado, luego cambia de lado."]'),
  ('Arrancada a 1 Brazo con Mancuerna', 'dumbbell-one-arm-snatch.gif', 'upper legs', '["Stand with your feet shoulder-width apart, holding a dumbbell in one hand with an overhand grip.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight and chest up.", "Lower the dumbbell towards the ground, keeping it close to your body.", "Explosively extend your hips, knees, and ankles, driving the dumbbell upwards in a straight line.", "As the dumbbell reaches shoulder height, quickly rotate your hand and punch it overhead, fully extending your arm.", "Catch the dumbbell overhead with a slight bend in your knees and hips.", "Lower the dumbbell back down to the starting position in a controlled manner.", "Repeat for the desired number of repetitions, then switch to the other arm."]', '["Ponte de pie con los pies separados a la altura de los hombros, sosteniendo una mancuerna en una mano con agarre prono.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta y el pecho elevado.", "Baja la mancuerna hacia el suelo, manteniéndola cerca del cuerpo.", "Extiende explosivamente las caderas, las rodillas y los tobillos, impulsando la mancuerna hacia arriba en línea recta.", "Cuando la mancuerna alcance la altura del hombro, gira rápidamente la mano y empújala por encima de la cabeza, extendiendo completamente el brazo.", "Recibe la mancuerna por encima de la cabeza con una ligera flexión en las rodillas y las caderas.", "Baja la mancuerna de nuevo a la posición inicial de manera controlada.", "Repite el número de repeticiones deseado, luego cambia al otro brazo."]'),
  ('Cargada Colgante con Kettlebell', 'kettlebell-hang-clean.gif', 'upper legs', '["Stand with your feet shoulder-width apart, holding a kettlebell in front of your thighs.", "Bend your knees slightly and hinge forward at the hips, keeping your back straight.", "Lower the kettlebell towards the ground, allowing it to swing between your legs.", "Quickly extend your hips and knees, using the momentum to swing the kettlebell up to shoulder height.", "As the kettlebell reaches shoulder height, rotate your wrists and catch the kettlebell in the rack position, with your elbow tucked in and the kettlebell resting on your forearm.", "Lower the kettlebell back down to the starting position between your legs, and repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una pesa rusa frente a los muslos.", "Flexiona ligeramente las rodillas e inclínate hacia adelante desde las caderas, manteniendo la espalda recta.", "Baja la pesa rusa hacia el suelo, dejando que se balancee entre las piernas.", "Extiende rápidamente las caderas y las rodillas, usando el impulso para hacer que la pesa rusa suba hasta la altura del hombro.", "Cuando la pesa rusa llegue a la altura del hombro, rota las muñecas y atrápala en posición de descanso, con el codo pegado al cuerpo y la pesa rusa apoyada en el antebrazo.", "Baja la pesa rusa de vuelta a la posición inicial entre las piernas y repite el número de repeticiones deseado."]'),
  ('Cargada con Mancuernas', 'dumbbell-clean.gif', 'upper legs', '["Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip.", "Bend your knees and lower your hips into a squat position, keeping your back straight and chest up.", "Explosively extend your hips and knees, driving through your heels to jump off the ground.", "As you jump, shrug your shoulders and pull the dumbbells up towards your shoulders, keeping them close to your body.", "Catch the dumbbells at shoulder height, with your elbows pointing forward and your palms facing up.", "Lower the dumbbells back down to the starting position by reversing the movement.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros, sujetando una mancuerna en cada mano con un agarre prono.", "Flexiona las rodillas y baja las caderas hacia una posición de sentadilla, manteniendo la espalda recta y el pecho elevado.", "Extiende las caderas y las rodillas de forma explosiva, empujando con los talones para saltar del suelo.", "Mientras saltas, encoge los hombros y tira de las mancuernas hacia arriba, hacia los hombros, manteniéndolas cerca del cuerpo.", "Atrapa las mancuernas a la altura de los hombros, con los codos apuntando hacia adelante y las palmas hacia arriba.", "Baja las mancuernas de vuelta a la posición inicial invirtiendo el movimiento.", "Repite el número de repeticiones deseado."]'),
  ('Cargada y Press con Barra', 'barbell-clean-and-press-0028.gif', 'upper legs', '["Stand with your feet shoulder-width apart and the barbell on the floor in front of you.", "Bend your knees and hinge at the hips to lower down and grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.", "Drive through your heels and extend your hips and knees to lift the barbell off the floor, keeping it close to your body.", "As the barbell reaches your thighs, explosively extend your hips, shrug your shoulders, and pull the barbell up towards your chest.", "As the barbell reaches chest height, quickly drop under it and catch it at shoulder level, with your elbows pointing forward and your palms facing up.", "From the catch position, press the barbell overhead by extending your arms and pushing the barbell straight up.", "Lower the barbell back down to the starting position and repeat for the desired number of repetitions."]', '["Ponte de pie con los pies separados a la altura de los hombros y la barra en el suelo frente a ti.", "Flexiona las rodillas y las caderas para bajar y agarrar la barra con un agarre pronado, con las manos un poco más separadas que el ancho de los hombros.", "Empuja con los talones y extiende las caderas y las rodillas para levantar la barra del suelo, manteniéndola cerca del cuerpo.", "Cuando la barra llegue a los muslos, extiende las caderas de forma explosiva, encoge los hombros y tira de la barra hacia el pecho.", "Cuando la barra llegue a la altura del pecho, baja rápidamente debajo de ella y atrápala a la altura de los hombros, con los codos apuntando hacia delante y las palmas hacia arriba.", "Desde la posición de recepción, empuja la barra por encima de la cabeza extendiendo los brazos y llevando la barra recta hacia arriba.", "Baja la barra de vuelta a la posición inicial y repite el número de repeticiones deseado."]'),
  ('Curl Femoral con Patada Diagonal a 1 Pierna sobre Fitball', 'exercise-ball-one-legged-diagonal-kick-hamstring-curl.gif', 'upper legs', '["Start by lying on your back with your legs extended and your heels resting on top of the stability ball.", "Place your arms by your sides for stability.", "Engage your glutes and core muscles to lift your hips off the ground, creating a straight line from your shoulders to your heels.", "Bend your right knee and bring it towards your chest, keeping your left leg extended and your foot flexed.", "Kick your right leg diagonally across your body, extending it fully and engaging your hamstrings.", "Slowly return your right leg to the starting position, maintaining control and stability.", "Repeat the movement with your left leg, alternating sides for the desired number of repetitions."]', '["Comienza acostado sobre la espalda con las piernas extendidas y los talones apoyados sobre el balón de estabilidad.", "Coloca los brazos a los lados del cuerpo para mantener el equilibrio.", "Activa los glúteos y el abdomen para levantar las caderas del suelo, formando una línea recta desde los hombros hasta los talones.", "Dobla la rodilla derecha y llévala hacia el pecho, manteniendo la pierna izquierda extendida y el pie en flexión.", "Lleva la pierna derecha en diagonal a través del cuerpo, extendiéndola por completo y activando los isquiotibiales.", "Regresa lentamente la pierna derecha a la posición inicial, manteniendo el control y el equilibrio.", "Repite el movimiento con la pierna izquierda, alternando los lados durante el número de repeticiones deseado."]'),
  ('Curl Femoral de Rodillas en Máquina', 'lever-kneeling-leg-curl.gif', 'upper legs', '["Adjust the machine to fit your body and select the desired weight.", "Kneel on the machine facing downwards, with your knees resting on the pad and your feet secured under the footpads.", "Grasp the handles or the sides of the machine for stability.", "Keeping your upper body stationary, exhale and curl your legs up towards your glutes by flexing your knees.", "Pause for a moment at the top of the movement, squeezing your hamstrings.", "Inhale and slowly lower your legs back to the starting position, fully extending your knees.", "Repeat for the desired number of repetitions."]', '["Ajusta la máquina a tu cuerpo y selecciona el peso deseado.", "Arrodíllate en la máquina mirando hacia abajo, con las rodillas apoyadas en la almohadilla y los pies asegurados bajo las almohadillas para los pies.", "Sujeta las asas o los lados de la máquina para mayor estabilidad.", "Manteniendo quieta la parte superior del cuerpo, exhala y flexiona las piernas hacia los glúteos doblando las rodillas.", "Haz una pausa breve en la parte más alta del movimiento, contrayendo los isquiotibiales.", "Inhala y baja lentamente las piernas de vuelta a la posición inicial, extendiendo por completo las rodillas.", "Repite el número de repeticiones deseado."]'),
  ('Curl Femoral Tumbado con Mancuerna', 'dumbbell-lying-femoral.gif', 'upper legs', '["Lie flat on your back with your legs extended and a dumbbell resting on your lower abdomen.", "Bend your knees and bring the dumbbell towards your glutes, keeping your feet flat on the ground.", "Pause for a moment at the top, then slowly lower the dumbbell back to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca arriba con las piernas extendidas y una mancuerna apoyada sobre el abdomen bajo.", "Flexiona las rodillas y lleva la mancuerna hacia los glúteos, manteniendo los pies apoyados en el suelo.", "Haz una pausa breve en la parte más alta, luego baja lentamente la mancuerna de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl Femoral Tumbado de 2 a 1 Pierna en Máquina', 'lever-lying-two-one-leg-curl.gif', 'upper legs', '["Adjust the machine to fit your body and sit on it with your back against the backrest.", "Place your legs on the lever pad, just above your ankles.", "Grasp the handles on the sides of the machine for support.", "Keeping your upper body still, exhale and curl your legs up towards your glutes.", "Pause for a moment at the top, then inhale and slowly lower your legs back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la máquina a tu cuerpo y siéntate en ella con la espalda apoyada en el respaldo.", "Coloca las piernas sobre la almohadilla de la palanca, justo encima de los tobillos.", "Sujeta las asas a los lados de la máquina para mayor apoyo.", "Manteniendo la parte superior del cuerpo inmóvil, exhala y flexiona las piernas hacia los glúteos.", "Haz una pausa breve en lo alto, luego inhala y baja lentamente las piernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl Nórdico Asistido en Polea', 'cable-assisted-inverse-leg-curl.gif', 'upper legs', '["Adjust the cable machine so that the ankle attachment is at the lowest setting.", "Lie face down on the bench with your legs straight and the ankle attachment secured to your ankles.", "Hold onto the handles of the bench for stability.", "Keeping your upper body stationary, exhale and curl your legs up towards your glutes by flexing your knees.", "Pause for a moment at the top of the movement, squeezing your hamstrings.", "Inhale and slowly lower your legs back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la máquina de cable de modo que el accesorio para el tobillo quede en la posición más baja.", "Túmbate boca abajo en el banco con las piernas rectas y el accesorio para el tobillo sujeto a los tobillos.", "Sujétate de las agarraderas del banco para mantener la estabilidad.", "Manteniendo quieta la parte superior del cuerpo, exhala y flexiona las piernas hacia los glúteos doblando las rodillas.", "Haz una pausa breve en la parte más alta del movimiento, contrayendo los isquiotibiales.", "Inhala y baja lentamente las piernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl Nórdico Autoasistido', 'self-assisted-inverse-leg-curl.gif', 'upper legs', '["Lie flat on your back on a mat or bench with your legs extended.", "Place your hands by your sides or under your glutes for support.", "Bend your knees and lift your feet off the ground, bringing your thighs towards your chest.", "Pause for a moment at the top, then slowly lower your legs back to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca arriba sobre una esterilla o banco con las piernas extendidas.", "Coloca las manos a los lados o debajo de los glúteos para apoyarte.", "Dobla las rodillas y levanta los pies del suelo, llevando los muslos hacia el pecho.", "Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Curl Nórdico Autoasistido en el Suelo', 'self-assisted-inverse-leg-curl-on-floor.gif', 'upper legs', '["Lie flat on your back with your legs extended and your arms by your sides.", "Bend your knees and place your feet flat on the ground, hip-width apart.", "Lift your hips off the ground, engaging your glutes and hamstrings.", "Slowly curl your legs towards your glutes, keeping your hips lifted.", "Pause for a moment at the top, then slowly extend your legs back to the starting position.", "Lower your hips back down to the ground.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.", "Dobla las rodillas y coloca los pies planos sobre el suelo, separados a la altura de la cadera.", "Levanta las caderas del suelo, activando los glúteos y los isquiotibiales.", "Flexiona lentamente las piernas hacia los glúteos, manteniendo las caderas elevadas.", "Haz una pausa breve en la parte superior, luego extiende lentamente las piernas de vuelta a la posición inicial.", "Baja las caderas de nuevo hacia el suelo.", "Repite el número de repeticiones deseado."]'),
  ('Curl Nórdico en Máquina de Poleas', 'inverse-leg-curl-on-pull-up-cable-machine.gif', 'upper legs', '["Adjust the cable machine so that the ankle straps are at the lowest setting.", "Lie face down on the bench with your legs extended and the ankle straps attached to your feet.", "Hold onto the handles of the bench for stability.", "Bend your knees and curl your legs towards your glutes, squeezing your hamstrings.", "Pause for a moment at the top of the movement, then slowly lower your legs back to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la máquina de cable para que las correas de tobillo estén en el ajuste más bajo.", "Túmbate boca abajo en el banco con las piernas extendidas y las correas de tobillo sujetas a los pies.", "Sujétate de las agarraderas del banco para mantener la estabilidad.", "Dobla las rodillas y curva las piernas hacia los glúteos, contrayendo los isquiotibiales.", "Haz una pausa breve en la parte superior del movimiento, luego baja lentamente las piernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Deslizamiento de Pierna Tumbado', 'single-leg-platform-slide.gif', 'upper legs', '["Start by standing with one foot on a platform or slide board.", "Bend your knee slightly and slide the foot on the platform backward, extending your leg.", "Keep your core engaged and maintain a straight posture throughout the movement.", "Slowly return to the starting position by sliding your foot back to the initial position.", "Repeat the movement for the desired number of repetitions, then switch legs."]', '["Comienza de pie con un pie sobre una plataforma o tabla deslizante.", "Dobla ligeramente la rodilla y desliza el pie sobre la plataforma hacia atrás, extendiendo la pierna.", "Mantén el core activado y conserva una postura recta durante todo el movimiento.", "Vuelve lentamente a la posición inicial deslizando el pie de regreso a la posición inicial.", "Repite el movimiento el número de repeticiones deseado y luego cambia de pierna."]'),
  ('El Mejor Estiramiento del Mundo', 'world-greatest-stretch.gif', 'upper legs', '["Start in a lunge position with your right foot forward and your left foot back.", "Place your hands on the ground on either side of your right foot.", "Lower your left knee to the ground and extend your right leg, keeping your right foot flat on the ground.", "Rotate your torso to the right, reaching your right arm up towards the ceiling.", "Hold this position for a few seconds, then return to the starting position.", "Switch sides and repeat the stretch with your left foot forward."]', '["Comienza en posición de zancada con el pie derecho adelante y el pie izquierdo atrás.", "Coloca las manos en el suelo a ambos lados de tu pie derecho.", "Baja la rodilla izquierda hacia el suelo y extiende la pierna derecha, manteniendo el pie derecho plano sobre el suelo.", "Gira el torso hacia la derecha, extendiendo el brazo derecho hacia el techo.", "Mantén esta posición durante unos segundos, luego vuelve a la posición inicial.", "Cambia de lado y repite el estiramiento con el pie izquierdo adelante."]'),
  ('Elevación de Cadera con Banda Elástica', 'band-hip-lift.gif', 'upper legs', '["Lie on your back with your knees bent and feet flat on the ground.", "Place a resistance band just above your knees.", "Engage your glutes and core muscles.", "Press your heels into the ground and lift your hips off the floor, squeezing your glutes at the top.", "Pause for a moment at the top, then slowly lower your hips back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Coloca una banda elástica justo por encima de las rodillas.", "Activa los glúteos y los músculos del core.", "Presiona los talones contra el suelo y levanta las caderas del suelo, apretando los glúteos en la parte superior.", "Haz una pausa por un momento en la parte superior, luego baja lentamente las caderas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Elevación de Cadera con Giro', 'twist-hip-lift.gif', 'upper legs', '["Lie on your back with your knees bent and feet flat on the ground.", "Place your hands by your sides for support.", "Engage your glutes and lift your hips off the ground, forming a straight line from your knees to your shoulders.", "While keeping your hips lifted, twist your lower body to the right side, bringing your knees towards the ground.", "Return to the starting position and repeat the twist to the left side.", "Continue alternating twists for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las rodillas flexionadas y los pies apoyados en el suelo.", "Coloca las manos a los lados para mayor apoyo.", "Activa los glúteos y levanta las caderas del suelo, formando una línea recta desde las rodillas hasta los hombros.", "Manteniendo las caderas elevadas, gira la parte inferior del cuerpo hacia el lado derecho, llevando las rodillas hacia el suelo.", "Vuelve a la posición inicial y repite el giro hacia el lado izquierdo.", "Continúa alternando los giros el número de repeticiones deseado."]'),
  ('Elevación Glúteo-Isquio (GHR)', 'glute-ham-raise.gif', 'upper legs', '["Adjust the glute-ham raise machine to fit your body.", "Position yourself face down on the machine with your ankles secured.", "Place your hands on your chest or cross them over your chest.", "Engage your hamstrings and glutes to lift your upper body up towards the ceiling.", "Continue lifting until your body is in a straight line from your head to your heels.", "Pause for a moment at the top, then slowly lower your body back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Ajusta la máquina de extensión de glúteos e isquiotibiales para que se adapte a tu cuerpo.", "Colócate boca abajo en la máquina con los tobillos asegurados.", "Coloca las manos sobre el pecho o crúzalas sobre el pecho.", "Activa los isquiotibiales y los glúteos para levantar la parte superior del cuerpo hacia el techo.", "Continúa levantando hasta que el cuerpo forme una línea recta desde la cabeza hasta los talones.", "Haz una pausa por un momento en la parte superior, luego baja lentamente el cuerpo de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Estiramiento Asistido de Aductores Tumbado de Lado', 'assisted-side-lying-adductor-stretch.gif', 'upper legs', '["Lie on your side with your legs straight and stacked on top of each other.", "Bend your bottom leg slightly for stability.", "Place your top foot on a stable surface, such as a bench or step.", "Keeping your top leg straight, slowly lower it towards the ground, feeling a stretch in your inner thigh.", "Hold the stretch for 20-30 seconds.", "Return to the starting position and repeat on the other side."]', '["Túmbate de lado con las piernas rectas y apiladas una sobre la otra.", "Flexiona ligeramente la pierna de abajo para mayor estabilidad.", "Coloca el pie de arriba sobre una superficie estable, como un banco o un escalón.", "Manteniendo la pierna de arriba recta, bájala lentamente hacia el suelo, sintiendo un estiramiento en la parte interna del muslo.", "Mantén el estiramiento durante 20-30 segundos.", "Regresa a la posición inicial y repite del otro lado."]'),
  ('Estiramiento Asistido de Cuádriceps Boca Abajo', 'assisted-prone-lying-quads-stretch.gif', 'upper legs', '["Lie face down on the ground with your legs extended.", "Bend your left knee and reach back with your left hand to grab your left foot or ankle.", "Gently pull your left foot towards your glutes, feeling a stretch in your left quad.", "Hold the stretch for 20-30 seconds, then release.", "Repeat with your right leg."]', '["Túmbate boca abajo en el suelo con las piernas extendidas.", "Flexiona la rodilla izquierda y lleva la mano izquierda hacia atrás para agarrar el pie o el tobillo izquierdo.", "Jala suavemente el pie izquierdo hacia los glúteos, sintiendo un estiramiento en el cuádriceps izquierdo.", "Mantén el estiramiento durante 20-30 segundos, luego suelta.", "Repite con la pierna derecha."]'),
  ('Estiramiento Asistido de Glúteo y Piriforme Tumbado', 'assisted-lying-gluteus-and-piriformis-stretch.gif', 'upper legs', '["Lie on your back with your legs extended.", "Bend your right knee and place your right ankle on your left thigh, just above the knee.", "Grasp your left thigh with both hands and gently pull it towards your chest.", "Hold the stretch for 20-30 seconds.", "Release the stretch and repeat on the other side."]', '["Túmbate sobre tu espalda con las piernas extendidas.", "Flexiona la rodilla derecha y coloca el tobillo derecho sobre el muslo izquierdo, justo encima de la rodilla.", "Agarra el muslo izquierdo con ambas manos y jálalo suavemente hacia el pecho.", "Mantén el estiramiento durante 20-30 segundos.", "Suelta el estiramiento y repite del otro lado."]'),
  ('Estiramiento Asistido de Glúteos Tumbado', 'assisted-lying-glutes-stretch.gif', 'upper legs', '["Lie on your back with your legs extended.", "Bend your right knee and place your right ankle on your left thigh, just above the knee.", "Grasp your left thigh with both hands and gently pull it towards your chest.", "Hold the stretch for 20-30 seconds.", "Release and repeat on the other side."]', '["Túmbate sobre tu espalda con las piernas extendidas.", "Flexiona la rodilla derecha y coloca el tobillo derecho sobre el muslo izquierdo, justo encima de la rodilla.", "Agarra el muslo izquierdo con ambas manos y jálalo suavemente hacia el pecho.", "Mantén el estiramiento durante 20-30 segundos.", "Suelta y repite del otro lado."]'),
  ('Estiramiento Asistido de Isquiotibiales Boca Abajo', 'assisted-prone-hamstring.gif', 'upper legs', '["Lie face down on a mat or bench with your legs fully extended.", "Have a partner or use a resistance band to secure your ankles.", "Engage your hamstrings and lift your legs towards your glutes, keeping your knees straight.", "Pause for a moment at the top, then slowly lower your legs back down to the starting position.", "Repeat for the desired number of repetitions."]', '["Túmbate boca abajo sobre una esterilla o un banco con las piernas completamente extendidas.", "Pide a un compañero o usa una banda elástica para sujetar tus tobillos.", "Activa los isquiotibiales y levanta las piernas hacia los glúteos, manteniendo las rodillas rectas.", "Haz una pausa por un momento en la parte superior, luego baja lentamente las piernas de vuelta a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Estiramiento Cruz de Hierro', 'iron-cross-stretch.gif', 'upper legs', '["Lie flat on your back with your arms extended out to the sides.", "Raise your legs up towards the ceiling, keeping them straight.", "Slowly lower your legs to one side, aiming to touch the floor with your feet.", "Hold the stretch for a few seconds, then return your legs to the starting position.", "Repeat the stretch on the other side.", "Continue alternating sides for the desired number of repetitions."]', '["Túmbate boca arriba con los brazos extendidos hacia los lados.", "Levanta las piernas hacia el techo, manteniéndolas rectas.", "Baja lentamente las piernas hacia un lado, intentando tocar el suelo con los pies.", "Mantén el estiramiento durante unos segundos, luego regresa las piernas a la posición inicial.", "Repite el estiramiento en el otro lado.", "Continúa alternando lados durante el número de repeticiones deseado."]'),
  ('Estiramiento de Cadera con Rodillo', 'roller-hip-stretch.gif', 'upper legs', '["Start by sitting on the ground with your legs extended in front of you.", "Place the roller under your glutes, just above your knees.", "Lean back and place your hands on the ground behind you for support.", "Engage your glutes and slowly roll the roller forward, bending your knees and bringing them towards your chest.", "Pause for a moment at the end of the movement, feeling a stretch in your glutes.", "Slowly roll the roller back to the starting position, extending your legs.", "Repeat for the desired number of repetitions."]', '["Comienza sentándote en el suelo con las piernas extendidas frente a ti.", "Coloca el rodillo debajo de los glúteos, justo por encima de las rodillas.", "Inclínate hacia atrás y coloca las manos en el suelo detrás de ti para apoyarte.", "Activa los glúteos y rueda lentamente el rodillo hacia adelante, flexionando las rodillas y llevándolas hacia el pecho.", "Haz una pausa al final del movimiento, sintiendo un estiramiento en los glúteos.", "Rueda lentamente el rodillo de vuelta a la posición inicial, extendiendo las piernas.", "Repite el número de repeticiones deseado."]'),
  ('Estiramiento de Cadera y Dorsal con Rodillo', 'roller-hip-lat-stretch.gif', 'upper legs', '["Start by kneeling on the ground with the roller positioned under your hips.", "Place your hands on the roller for support.", "Slowly roll the roller forward, extending your hips and stretching your glutes.", "Hold the stretch for a few seconds, then roll back to the starting position.", "Repeat for the desired number of repetitions."]', '["Comienza arrodillándote en el suelo con el rodillo colocado debajo de las caderas.", "Coloca las manos sobre el rodillo para mayor apoyo.", "Rueda lentamente el rodillo hacia adelante, extendiendo las caderas y estirando los glúteos.", "Mantén el estiramiento durante unos segundos, luego regresa a la posición inicial.", "Repite el número de repeticiones deseado."]'),
  ('Estiramiento de Cuádriceps a Cuatro Apoyos', 'all-fours-squad-stretch.gif', 'upper legs', '["Start on all fours with your hands directly under your shoulders and your knees directly under your hips.", "Extend one leg straight back, keeping your knee bent and your foot flexed.", "Slowly lower your hips towards the ground, feeling a stretch in your quads.", "Hold this position for 20-30 seconds.", "Switch legs and repeat the stretch on the other side."]', '["Comienza apoyado sobre manos y rodillas, con las manos justo debajo de los hombros y las rodillas justo debajo de las caderas.", "Extiende una pierna hacia atrás, manteniendo la rodilla flexionada y el pie en flexión.", "Baja lentamente las caderas hacia el suelo, sintiendo un estiramiento en los cuádriceps.", "Mantén esta posición durante 20-30 segundos.", "Cambia de pierna y repite el estiramiento del otro lado."]'),
  ('Estiramiento de Cuádriceps Tumbado de Lado', 'lying-side-quads-stretch.gif', 'upper legs', '["Lie on your side with your legs straight.", "Bend your top leg and grab your ankle or foot with your hand.", "Gently pull your ankle or foot towards your glutes until you feel a stretch in your quads.", "Hold the stretch for 20-30 seconds.", "Release the stretch and repeat on the other side."]', '["Túmbate de lado con las piernas rectas.", "Flexiona la pierna de arriba y agarra tu tobillo o pie con la mano.", "Tira suavemente del tobillo o del pie hacia los glúteos hasta sentir un estiramiento en los cuádriceps.", "Mantén el estiramiento durante 20-30 segundos.", "Suelta el estiramiento y repite del otro lado."]'),
  ('Estiramiento de Flexor de Cadera con Fitball', 'exercise-ball-hip-flexor-stretch.gif', 'upper legs', '["Place the stability ball on the ground and kneel in front of it.", "Place your right foot on top of the stability ball, with your knee bent at a 90-degree angle.", "Extend your left leg behind you, keeping it straight.", "Lean forward, pushing your hips towards the stability ball, until you feel a stretch in your right hip flexor.", "Hold the stretch for 20-30 seconds, then switch sides and repeat."]', '["Coloca el balón de estabilidad en el suelo y arrodíllate frente a él.", "Coloca el pie derecho sobre el balón de estabilidad, con la rodilla flexionada en un ángulo de 90 grados.", "Extiende la pierna izquierda hacia atrás, manteniéndola recta.", "Inclínate hacia adelante, empujando las caderas hacia el balón de estabilidad, hasta sentir un estiramiento en el flexor de la cadera derecha.", "Mantén el estiramiento durante 20-30 segundos, luego cambia de lado y repite."]'),
  ('Estiramiento de Flexor de Cadera y Cuádriceps con Cuerda', 'intermediate-hip-flexor-and-quad-stretch.gif', 'upper legs', '["Stand upright with your feet shoulder-width apart.", "Hold onto a stable object for support.", "Bend your right knee and bring your right foot towards your glutes, grabbing the rope with your right hand.", "Slowly pull your right foot towards your glutes, feeling a stretch in your right quad.", "Hold the stretch for 20-30 seconds.", "Release the stretch and repeat on the left side."]', '["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.", "Sujétate de un objeto estable para mayor apoyo.", "Dobla la rodilla derecha y lleva el pie derecho hacia los glúteos, sujetando la cuerda con la mano derecha.", "Tira lentamente del pie derecho hacia los glúteos, sintiendo un estiramiento en el cuádriceps derecho.", "Mantén el estiramiento durante 20-30 segundos.", "Suelta el estiramiento y repite en el lado izquierdo."]'),
  ('Estiramiento de Glúteo Sentado', 'seated-glute-stretch.gif', 'upper legs', '["Sit on the ground with your legs extended in front of you.", "Bend your right knee and cross your right ankle over your left thigh.", "Place your right hand on the ground behind you for support.", "With your left hand, gently press down on your right knee to deepen the stretch.", "Hold the stretch for 30 seconds to 1 minute.", "Switch sides and repeat."]', '["Siéntate en el suelo con las piernas extendidas frente a ti.", "Dobla la rodilla derecha y cruza el tobillo derecho sobre el muslo izquierdo.", "Coloca la mano derecha en el suelo detrás de ti para apoyarte.", "Con la mano izquierda, presiona suavemente la rodilla derecha para profundizar el estiramiento.", "Mantén el estiramiento durante 30 segundos a 1 minuto.", "Cambia de lado y repite."]'),
  ('Estiramiento de Isquiotibiales con Pierna Elevada', 'leg-up-hamstring-stretch.gif', 'upper legs', '["Lie flat on your back with your legs extended.", "Bend one knee and bring it towards your chest, holding onto your thigh or shin.", "Straighten your leg as much as possible while keeping it elevated.", "Hold the stretch for 20-30 seconds.", "Repeat with the other leg."]', '["Túmbate boca arriba con las piernas extendidas.", "Flexiona una rodilla y llévala hacia el pecho, sujetándote del muslo o la espinilla.", "Endereza la pierna tanto como sea posible mientras la mantienes elevada.", "Mantén el estiramiento durante 20-30 segundos.", "Repite con la otra pierna."]'),
  ('Estiramiento de Isquiotibiales Sentado sobre Fitball', 'exercise-ball-seated-hamstring-stretch.gif', 'upper legs', '["Sit on the stability ball with your feet flat on the ground and your knees bent at a 90-degree angle.", "Slowly roll the ball forward, walking your feet out until your upper back is resting on the ball and your legs are extended straight in front of you.", "Place your hands on your hips for support.", "Engage your core and slowly lower your upper body towards the ground, keeping your back straight and your chest lifted.", "Stop when you feel a stretch in your hamstrings, and hold the position for 20-30 seconds.", "Slowly return to the starting position by pushing through your heels and using your hamstrings to pull yourself back up.", "Repeat for the desired number of repetitions."]', '["Siéntate en el balón de estabilidad con los pies planos en el suelo y las rodillas flexionadas en un ángulo de 90 grados.", "Haz rodar el balón lentamente hacia adelante, caminando con los pies hacia afuera hasta que la parte superior de la espalda quede apoyada sobre el balón y las piernas queden extendidas rectas frente a ti.", "Coloca las manos en las caderas para mayor apoyo.", "Activa el core y baja lentamente la parte superior del cuerpo hacia el suelo, manteniendo la espalda recta y el pecho elevado.", "Detente cuando sientas un estiramiento en los isquiotibiales y mantén la posición durante 20-30 segundos.", "Regresa lentamente a la posición inicial empujando con los talones y usando los isquiotibiales para volver a subir.", "Repite el número de repeticiones deseado."]'),
  ('Estiramiento de Isquiotibiales Tumbado', 'hamstring-stretch.gif', 'upper legs', '["Stand with your feet shoulder-width apart.", "Step forward with your right foot and shift your weight onto your right leg.", "Keeping your back straight, slowly bend forward at the hips, reaching towards your right foot with both hands.", "Hold the stretch for 20-30 seconds, then return to the starting position.", "Repeat on the other side."]', '["Ponte de pie con los pies separados a la altura de los hombros.", "Da un paso adelante con el pie derecho y traslada el peso hacia la pierna derecha.", "Manteniendo la espalda recta, inclínate lentamente hacia adelante desde las caderas, alcanzando el pie derecho con ambas manos.", "Mantén el estiramiento durante 20-30 segundos, luego vuelve a la posición inicial.", "Repite del otro lado."]'),
  ('Estiramiento de Isquiotibiales Tumbado con Cuerda (Yoga)', 'reclining-big-toe-pose-with-rope.gif', 'upper legs', '["Lie on your back with your legs extended and your arms by your sides.", "Loop the rope around the ball of your right foot and hold the ends of the rope with your hands.", "Slowly raise your right leg towards your chest, keeping your knee straight and your foot flexed.", "Hold the stretch for a few seconds, then slowly lower your leg back down to the starting position.", "Repeat with your left leg.", "Continue alternating legs for the desired number of repetitions."]', '["Túmbate sobre tu espalda con las piernas extendidas y los brazos a los lados.", "Enrolla la cuerda alrededor de la planta del pie derecho y sujeta los extremos de la cuerda con las manos.", "Eleva lentamente la pierna derecha hacia el pecho, manteniendo la rodilla recta y el pie flexionado.", "Mantén el estiramiento durante unos segundos y luego baja lentamente la pierna de vuelta a la posición inicial.", "Repite con la pierna izquierda.", "Continúa alternando las piernas durante el número de repeticiones deseado."]'),
  ('Estiramiento de Isquiotibiales y Gemelos de Pie con Cinta', 'standing-hamstring-and-calf-stretch-with-strap.gif', 'upper legs', '["Stand upright with your feet shoulder-width apart.", "Hold the strap with both hands and place it around the ball of your foot.", "Keep your leg straight and slowly lean forward from your hips, keeping your back straight.", "Feel the stretch in your hamstring and calf muscles.", "Hold the stretch for 20-30 seconds.", "Release the stretch and repeat with the other leg.", "Repeat for the desired number of repetitions."]', '["Ponte de pie con la espalda recta y los pies separados a la altura de los hombros.", "Sostén la correa con ambas manos y colócala alrededor de la parte anterior de la planta del pie.", "Mantén la pierna recta e inclínate lentamente hacia adelante desde las caderas, manteniendo la espalda recta.", "Siente el estiramiento en los isquiotibiales y en los músculos de la pantorrilla.", "Mantén el estiramiento durante 20-30 segundos.", "Suelta el estiramiento y repite con la otra pierna.", "Repite el número de repeticiones deseado."]'),
  ('Estiramiento de Pierna Sentado en Banco', 'chair-leg-extended-stretch.gif', 'upper legs', '["Sit on the edge of a chair with your back straight and feet flat on the ground.", "Extend one leg straight out in front of you, keeping your heel on the ground.", "Lean forward slightly, feeling a stretch in your quadriceps.", "Hold this position for 20-30 seconds.", "Switch legs and repeat the stretch."]', '["Siéntate al borde de una silla con la espalda recta y los pies planos en el suelo.", "Extiende una pierna recta frente a ti, manteniendo el talón en el suelo.", "Inclínate ligeramente hacia adelante, sintiendo un estiramiento en los cuádriceps.", "Mantén esta posición durante 20-30 segundos.", "Cambia de pierna y repite el estiramiento."]'),
  ('Estiramiento de Piriforme Sentado', 'seated-piriformis-stretch.gif', 'upper legs', '["Sit on the ground with your legs extended in front of you.", "Bend your right knee and place your right foot on the outside of your left knee.", "Place your left elbow on the outside of your right knee and gently twist your torso to the right.", "Hold the stretch for 20-30 seconds, then switch sides and repeat."]', '["Siéntate en el suelo con las piernas extendidas frente a ti.", "Dobla la rodilla derecha y coloca el pie derecho en la parte exterior de la rodilla izquierda.", "Coloca el codo izquierdo en la parte exterior de la rodilla derecha y gira suavemente el torso hacia la derecha.", "Mantén el estiramiento durante 20-30 segundos, luego cambia de lado y repite."]'),
  ('Estiramiento de Rana Balanceado', 'rocking-frog-stretch.gif', 'upper legs', '["Start by kneeling on the ground with your knees hip-width apart.", "Place your hands on the ground in front of you for support.", "Slowly lean forward, shifting your weight onto your hands and extending your legs behind you.", "Keep your back straight and engage your glutes as you push your hips back and up towards the ceiling.", "Hold this position for a few seconds, feeling a stretch in your glutes.", "Slowly return to the starting position by bending your knees and lowering your hips back down.", "Repeat for the desired number of repetitions."]', '["Comienza arrodillándote en el suelo con las rodillas separadas a la altura de las caderas.", "Coloca las manos en el suelo frente a ti para mayor apoyo.", "Inclínate lentamente hacia adelante, desplazando el peso hacia las manos y extendiendo las piernas detrás de ti.", "Mantén la espalda recta y activa los glúteos mientras empujas las caderas hacia atrás y hacia arriba en dirección al techo.", "Mantén esta posición durante unos segundos, sintiendo un estiramiento en los glúteos.", "Vuelve lentamente a la posición inicial flexionando las rodillas y bajando las caderas de nuevo.", "Repite el número de repeticiones deseado."]');
insert into public.exercises (name, video_url, body_part_id, instructions_en, instructions_es)
