-- ==========================================================================
-- Exercise catalog, part 3 of 4: 270 exercises from the Gym visual
-- exercises dataset (media © Gym visual — https://gymvisual.com/), each with
-- its own demo GIF in the exercise-media bucket, a Spanish name checked
-- against the GIF, body part and step-by-step instructions (es/en).
-- Body parts in this part: upper arms, upper legs.
--
-- Additive and re-runnable: a name that already exists is skipped (and
-- listed in a notice), never overwritten. Aborts without changing anything
-- if a GIF is missing from the bucket or a GIF would end up shared.
-- Apply parts 1..4 in order in the Supabase SQL editor.
-- ==========================================================================
begin;

create temp table _new (name text, file text, body_part text, en text, es text) on commit drop;

-- 0) Every GIF and body part must exist.
do $$
declare missing text;
begin
  select string_agg(n.file, ' | ') into missing from _new n
   where not exists (select 1 from storage.objects o where o.bucket_id = 'exercise-media' and o.name = n.file);
  if missing is not null then
    raise exception 'Upload these GIFs to the exercise-media bucket first: %', missing;
  end if;
  select string_agg(distinct n.body_part, ' | ') into missing from _new n
   where not exists (select 1 from public.bodyparts b where b.name = n.body_part);
  if missing is not null then
    raise exception 'Unknown body parts: %', missing;
  end if;
end $$;

-- 1) Names that already exist are left alone.
do $$
declare taken text;
begin
  select string_agg(n.name, ' | ') into taken from _new n
   where exists (select 1 from public.exercises e where lower(e.name) = lower(n.name));
  if taken is not null then
    raise notice 'Already in the catalog, skipped: %', taken;
  end if;
end $$;

select n.name, 'https://rzgwkwxskrovxnnymxqo.supabase.co/storage/v1/object/public/exercise-media/' || n.file, b.id, n.en::jsonb, n.es::jsonb
  from _new n
  join public.bodyparts b on b.name = n.body_part
 where not exists (select 1 from public.exercises e where lower(e.name) = lower(n.name))
   and not exists (select 1 from public.exercises e where e.video_url = 'https://rzgwkwxskrovxnnymxqo.supabase.co/storage/v1/object/public/exercise-media/' || n.file);

-- No GIF may be shared.
do $$
declare dup text;
begin
  select string_agg(video_url, ' | ') into dup
    from (select video_url from public.exercises
           where video_url is not null group by video_url having count(*) > 1) d;
  if dup is not null then
    raise exception 'GIF shared by more than one exercise: %', dup;
  end if;
end $$;

commit;
